window.__SUM[0]={"LR002071":{"pair":"ADAM2 -> ITGA4","headline":"Cell adhesion to ADAM2 is blocked by anti-ITGA4 antibody in human HT1080 cells; full-text read.","interaction_type":"direct binding","direction_and_effect":"HT1080 cells (ITGA4-ITGB1) adhere to ADAM2, and adhesion is inhibited by an anti-ITGA4 function-blocking antibody and by the ECD disintegrin-loop and MLD peptides [PMID:21060781].","molecular_requirements":"ITGA4 acts with ITGB1 in HT1080 cells; in RPMI 8866 cells (ITGA4-ITGB7) the anti-ITGA4 antibody only partially inhibited adhesion [PMID:21060781].","affinity_potency":[],"species_and_systems":"Recombinant ADAM2 at 50 \u00b5g/ml as substrate; human HT1080, Tera-2 and RPMI 8866 cell lines; mouse eggs examined for ITGB1 [PMID:21060781].","localisation_and_range":"ADAM2 flagged non-secreted [flag]; adhesion to immobilised ADAM2.","caveats":"Adhesion assays with blocking antibodies, not purified-protein binding. The paper's abstract/evidence concerns ITGA9 more than ITGA4.","key_references":[{"PMID":"21060781","why":"ADAM2 adhesion by ITGA4/ITGA9 integrins, antibody inhibition"}],"covers":["LR002071","LR005397"]},"LR000019":{"pair":"ADAM2 -> ITGB1","headline":"Mouse egg beta1 integrins (alpha6beta1) bind fertilin beta/ADAM2; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Fertilin beta binds directly to alpha6beta1 on the egg surface, mediating sperm-egg fusion [PMID:9889149]. Fertilin-coated beads bind eggs via alpha6beta1 and are blocked by anti-CD9 [PMID:10518536].","molecular_requirements":"ITGB1 acts as the beta subunit with alpha6; CD9 is needed for high-avidity binding [PMID:10518536][PMID:9889149].","affinity_potency":[],"species_and_systems":"Mouse eggs and sperm; bead and photoaffinity assays [PMID:9889149][PMID:10518536]. Human pair is ortholog-inferred.","localisation_and_range":"ADAM2 flagged non-secreted [flag]; sperm-egg contact.","caveats":"Both abstract only; beta1 alone not shown sufficient.","key_references":[{"PMID":"9889149","why":"Fertilin beta binds egg alpha6beta1 directly"},{"PMID":"10518536","why":"Bead binding via alpha6beta1; CD9 role"}],"covers":["LR000019","LR003569"]},"LR001630":{"pair":"ADAM7 -> ITGA4","headline":"ADAM7 disintegrin domain supports alpha4beta1-dependent Jurkat adhesion in an activation-dependent manner; abstract only.","interaction_type":"functional only","direction_and_effect":"The ADAM7 disintegrin domain supported alpha4beta1-dependent Jurkat cell adhesion; recognition required either Mn2+ or an activating monoclonal antibody [PMID:15504110].","molecular_requirements":"Alpha4 acts as alpha4beta1; integrin activation is required. The same residues within an ADAM disintegrin domain recognise multiple integrins, from charge-to-alanine mutagenesis [PMID:15504110].","affinity_potency":[],"species_and_systems":"Human ADAM disintegrin-like domains; Jurkat cell adhesion assays [PMID:15504110]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM7 is flagged secreted [flag]; adhesion to immobilised disintegrin domain.","caveats":"Abstract read only; labelled direct binding by curators but the evidence is a cell-adhesion assay.","key_references":[{"PMID":"15504110","why":"ADAM7 disintegrin recognised by alpha4beta1 and alpha4beta7"}],"covers":["LR001630","LR005018"]},"LR005401":{"pair":"ADAMTS1 -> LRP1","headline":"Direct LRP1 binding of ADAMTS1 reported in a chondrocyte ligandome study (abstract only); no affinity for ADAMTS1.","interaction_type":"direct binding","direction_and_effect":"Purified-protein binding assays confirmed direct LRP1 binding of ADAMTS1 among ten ligands, with LRP1 affinity correlating with endocytosis rate, so LRP1 acts as an endocytic receptor that takes up ADAMTS1 [PMID:36028175].","molecular_requirements":"Not reported in our evidence beyond LRP1 itself.","affinity_potency":[],"species_and_systems":"Human chondrocyte proteomics and purified-protein binding; validation in LRP1-deficient fibroblasts and human chondrocytes; a conditional Lrp1 knockout mouse was used for the general ligand set, not shown for ADAMTS1 specifically [PMID:36028175].","localisation_and_range":"Ligand is flagged as secreted [flag]; LRP1 is a cell-surface endocytic receptor [PMID:36028175], consistent with paracrine uptake.","caveats":"One paper read as abstract only; ADAMTS1 is one of ten ligands handled together. No numerical affinity for ADAMTS1 in our evidence. No database support.","key_references":[{"PMID":"36028175","why":"chondrocyte LRP1 ligandome with direct binding of ADAMTS1"}],"covers":["LR002075","LR005401"]},"LR000028":{"pair":"ADCYAP1 -> VIPR1","headline":"PACAP-27 and PACAP-38 bind and activate VPAC1 with nanomolar affinity in recombinant systems; abstract-level evidence from several papers.","interaction_type":"direct binding","direction_and_effect":"PACAP is an agonist at VPAC1: PACAP-27 inhibited [125I]VIP binding with Ki 1.3 nM and PACAP-38 with Ki 6.8 nM in CHO cells with human VIP1 receptor [PMID:8791009]; GtoPdb lists Agonist [DB:GtoPdb]. In CHO cells expressing human VPAC1, cAMP and calcium responses were measured, with calcium EC50 values roughly 100-fold higher than cAMP [PMID:16930633].","molecular_requirements":"Single receptor chain. PACAP carboxy-terminal shortening raised VIP1 affinity, implicating that end in VIP1/VIP2 discrimination [PMID:9928018].","affinity_potency":[{"value":"Ki 1.3 nM","assay":"inhibition of [125I]VIP binding, PACAP-27","system":"CHO cells, recombinant human VIP1 receptor","cite":"PMID:8791009"},{"value":"Ki 6.8 nM","assay":"inhibition of [125I]VIP binding, PACAP-38","system":"CHO cells, recombinant human VIP1 receptor","cite":"PMID:8791009"},{"value":"Ki 0.9 nM","assay":"inhibition of [125I]VIP binding, VIP","system":"CHO cells, recombinant human VIP1 receptor","cite":"PMID:8791009"}],"species_and_systems":"Human recombinant receptor in CHO cells [PMID:8791009][PMID:16930633]; rat and human receptors compared [PMID:9928018]; rat and mouse islets [PMID:11897681].","localisation_and_range":"Ligand flagged secreted [flag]; peptide acting on a membrane receptor.","caveats":"All read as abstracts only. In islets the abstract does not separate VPAC1 from VPAC2 [PMID:11897681]. Seven confirmed rows but two others were different_entity and one abstract_insufficient. Structures exist [DB:PDB 6VN7].","key_references":[{"PMID":"8791009","why":"Ki values for PACAP-27 and PACAP-38 at human VIP1 receptor"},{"PMID":"16930633","why":"cAMP and calcium potency at hVPAC1R"},{"PMID":"9928018","why":"PACAP analogue binding on VIP1 and VIP2"}],"covers":["LR000028","LR003578"]},"LR005023":{"pair":"ADGRE5 -> CD55","headline":"CD97 (ADGRE5) binds CD55 directly: binding, structural and in vivo functional evidence from three papers (abstract only).","interaction_type":"direct binding","direction_and_effect":"CD97 binds CD55 [PMID:11297558]. Blocking the CD55 (monocyte)-CD97 (T cell) interaction inhibited T cell proliferation and interferon-gamma secretion, suggesting bidirectional interaction [PMID:17449467]. In mice, contact with CD55 downregulated CD97 on circulating leukocytes under shear stress, without evidence of receptor signalling [PMID:23447688].","molecular_requirements":"Binding is mediated solely by the CD97 EGF and CD55 SCR domains; Ca(2+)-dependent [PMID:11297558]. The key leukocyte isoform of CD97 binds CD55 [PMID:17449467]. A model of the complex was built from EMR2 (a CD97 homolog) data [PMID:17449467].","affinity_potency":[{"value":"KD 86 microm (low affinity, rapid off-rate)","assay":"binding analysis of CD97-CD55","system":"CD97 and CD55 modular domains","cite":"PMID:11297558"}],"species_and_systems":"Human proteins and cells [PMID:11297558][PMID:17449467]; CD55-deficient mouse leukocytes in vivo [PMID:23447688]. Database records: IntAct, PDB 7DO4, Reactome, UniProt [DB:IntAct][DB:PDB 7DO4][DB:Reactome][DB:UniProt].","localisation_and_range":"Both partners are cell-surface proteins [flag]; interaction is cell-cell (juxtacrine) in the papers [PMID:17449467].","caveats":"All papers read as abstracts only. Affinity is low. The structural model rests on the homolog EMR2, not CD97 itself [PMID:17449467].","key_references":[{"PMID":"11297558","why":"domain dissection and affinity"},{"PMID":"17449467","why":"structure and T cell function"},{"PMID":"23447688","why":"in vivo CD97 downregulation by CD55"}],"covers":["LR001635","LR005023"]},"LR002080":{"pair":"ADGRL1 -> NRXN1","headline":"Latrophilin-1 ectodomain binds neurexins with nanomolar affinity; evidence is one abstract-only paper that covers neurexins as a group.","interaction_type":"direct binding","direction_and_effect":"Direct binding between the extracellular domains of latrophilin-1 (CL1) and neurexins; CL1 competed with neuroligin-1 for neurexin binding [PMID:22262843]. Cells expressing both formed stable adhesion, so trans-cellular [PMID:22262843].","molecular_requirements":"Neurexins lacking an insert at splice site 4 (SS4) bind CL1; those with an SS4 insert do not. The olfactomedin-like domain of CL1 mediates binding [PMID:22262843].","affinity_potency":[{"value":"nanomolar affinity (value not given)","assay":"saturation binding","system":"purified ectodomains","cite":"PMID:22262843"}],"species_and_systems":"Purified ectodomains and cell adhesion assays; species not stated beyond curator label human [PMID:22262843]. Pair is ortholog-inferred in both species.","localisation_and_range":"Both partners are membrane proteins [flag]; interaction is trans-cellular, suggesting juxtacrine signalling [PMID:22262843].","caveats":"Abstract only, and the abstract speaks of neurexins generally, so isoform specificity for NRXN1 is not shown in our evidence. Only the SS4-minus form binds [PMID:22262843]. Ligand-receptor direction is not defined, as both are membrane proteins.","key_references":[{"PMID":"22262843","why":"identifies latrophilin-1/neurexin binding"}],"covers":["LR002080","LR005406"]},"LR005410":{"pair":"ADGRL1 -> TENM4","headline":"Latrophilin-1 binds teneurin-4 on cells; full-text excerpt shown for Ten4, abstract describes nanomolar teneurin binding.","interaction_type":"direct binding","direction_and_effect":"Lphn1-Ig proteins, including the lectin domain alone, bound strongly to HEK293T cells expressing Ten2 or Ten4 but not control cells [PMID:24273166]. Teneurin binding mediates cell adhesion; soluble Lphn1 fragments decreased synapse density in cultured neurons [PMID:24273166].","molecular_requirements":"The lectin-like domain of latrophilins binds teneurin; alternative splicing modulates teneurin binding in latrophilin-1 [PMID:24273166].","affinity_potency":[{"value":"nanomolar affinity (value not given)","assay":"teneurin-latrophilin binding, per abstract","system":"not specified for Ten4","cite":"PMID:24273166"}],"species_and_systems":"Cell-surface labelling of HEK293T cells; species unspecified [PMID:24273166]. Pair is ortholog-inferred in both species.","localisation_and_range":"Both are membrane proteins; binding mediates cell adhesion, consistent with trans-synaptic interaction [PMID:24273166].","caveats":"The nanomolar affinity is stated for teneurins generally in the abstract, not specifically for Ten4. Direction is not defined, both being membrane proteins.","key_references":[{"PMID":"24273166","why":"Lphn1-Ten2/Ten4 binding and adhesion"}],"covers":["LR002084","LR005410"]},"LR008020":{"pair":"ADM -> CALCRL:RAMP3","headline":"ADM acts at CALCRL with RAMP3 (AM2 receptor); one confirmed abstract-only paper plus database records.","interaction_type":"functional only","direction_and_effect":"CRLR can function as an adrenomedullin receptor depending on which RAMP is expressed [PMID:9620797]. GtoPdb lists ADM as full agonist at ADM-RAMP3 (pKi 8.3 to 9.0) [DB:GtoPdb]. PDB 6UUS and UniProt describe CALCRL-RAMP3 as an ADM/intermedin receptor [DB:PDB 6UUS][DB:UniProt].","molecular_requirements":"Both CALCRL and RAMP3 are needed [DB:UniProt]; RAMP2/RAMP3 present CRLR as core-glycosylated ADM receptor [PMID:9620797].","affinity_potency":[{"value":"pKi 8.3-9.0","assay":"GtoPdb ADM-RAMP3 record","system":"not specified","cite":"PMID:10347248"}],"species_and_systems":"Transfected mammalian cells, species unspecified [PMID:9620797].","localisation_and_range":"ADM flagged secreted [flag].","caveats":"The confirmed paper's evidence sentence is general to RAMPs and not RAMP3-specific. Abstract only.","key_references":[{"PMID":"9620797","why":"RAMPs define CRLR phenotype"}],"covers":["LR008020"]},"LR000037":{"pair":"ADM -> RAMP2","headline":"ADM acts through CALCRL with RAMP2; confirmed in four abstract-only papers, RAMP2 being a co-receptor chain.","interaction_type":"direct binding","direction_and_effect":"RAMP2 confers an adrenomedullin-receptor phenotype on CRLR [PMID:9620797]. [125I]rADM binding was enhanced with hRAMP2 and inhibited by 50% when hRAMP1 was coexpressed [PMID:10342881]. GtoPdb lists ADM as full agonist [DB:GtoPdb]. Structures of CLR:RAMP2 with ADM exist [DB:PDB 4RWF].","molecular_requirements":"RAMP2 must pair with CLR (CALCRL); RAMPs are needed for CRLR surface transport [PMID:9620797]. RAMP2 and RAMP3 present CRLR as core-glycosylated ADM receptor [PMID:11693189].","affinity_potency":[{"value":"EC50 0.19 +/- 0.05 nM","assay":"rADM-induced CRE-luc reporter","system":"rat CRLR in UMR-106 cells","cite":"PMID:10342881"},{"value":"pKi 8.3-9.2","assay":"GtoPdb record","system":"HEK-293 per paper","cite":"PMID:11693189"}],"species_and_systems":"Human and rat receptors with rat ADM in UMR-106 and COS-7 cells, HEK-293 cells [PMID:10342881][PMID:11693189].","localisation_and_range":"ADM flagged secreted [flag].","caveats":"All abstract only. RAMP2 alone is not a receptor; the effect needs CRLR. Four further rows were abstract_insufficient. Mouse pair ortholog-inferred.","key_references":[{"PMID":"9620797","why":"RAMP2 confers ADM receptor phenotype"},{"PMID":"10342881","why":"rADM binding with RAMP2 and potency"},{"PMID":"30139742","why":"CLR-RAMP complex structure (AM2/IMD, not ADM)"}],"covers":["LR000037","LR003587"]},"LR005032":{"pair":"ALKAL1 -> ALK","headline":"ALKAL1 is a weak, not potent, ligand of ALK; sources agree it prefers LTK, but one paper shows some ALK activity.","interaction_type":"conflicting","direction_and_effect":"AUG-beta (ALKAL1) is described as LTK-specific and only weakly binding ALK [PMID:26630010]. The 2021 structural study says both ALKAL1 and ALKAL2 strongly activate LTK, but only ALKAL2 potently activates ALK [PMID:34646012]. UniProt states ALKAL1 is not a potent physiological ALK ligand [DB:UniProt].","molecular_requirements":"ALKTG-EGFL-ALKAL1 and ALKAL2 complexes show 1:1 stoichiometry [PMID:34646012]. Charge-reversal mutations in the cytokines lowered affinity for both receptors [PMID:34646012].","affinity_potency":[],"species_and_systems":"Cells expressing ALK or LTK [PMID:26630010]; purified human ALK and cell proliferation assays [PMID:34646012]. IntAct lists co-IP [DB:IntAct Q6UXT8-Q9UM73].","localisation_and_range":"ALKAL1 flagged secreted, ALK transmembrane [flag].","caveats":"The same structural paper reports the conserved C-terminal domains of ALKAL1 and ALKAL2 and full-length ALKAL1 could drive ALK-dependent proliferation [PMID:34646012], so weak activity is not absence. No affinity numbers in our evidence. PMID:26630010 read as abstract only.","key_references":[{"PMID":"26630010","why":"Hierarchy of ALKAL1/ALKAL2 at ALK and LTK"},{"PMID":"34646012","why":"Structures; only ALKAL2 potently activates ALK"}],"covers":["LR001644","LR005032"]},"LR003601":{"pair":"AMH -> AMHR2","headline":"AMH binds AMHR2 directly: a 2.6 A crystal structure plus binding and signalling data; the best-supported AMH receptor pair here.","interaction_type":"direct binding","direction_and_effect":"AMH binds and activates AMHR2, its dedicated type II receptor, as an agonist [PMID:34155118]. Cloned rabbit AMHR2 (longer 569-amino acid isoform) binds AMH when expressed in COS cells [PMID:7997230]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"X-ray structure of AMH bound to the AMHR2 extracellular domain at 2.6 A shows one AMHR2 contacting one AMH chain, with AMH dimerised via disulfide at C525 [PMID:34155118]. A finger-1 conformation and a K534 (AMH) salt bridge with D81/E84 (AMHR2) are key in a luciferase assay [PMID:34155118]. The longer isoform, not the shorter, binds AMH [PMID:7997230]. Type I partners are not defined in these papers.","affinity_potency":[],"species_and_systems":"Human proteins for the structure [PMID:34155118]; rabbit cDNA expressed in COS cells [PMID:7997230]. The mouse pair is inferred by orthology.","localisation_and_range":"AMH is flagged secreted [flag]; Reactome has AMH dimer:AMHR2 at the plasma membrane [DB:Reactome].","caveats":"[PMID:34155118] and [PMID:7997230] were read at abstract level by the curator; no affinity values in our evidence. One row pending, one review_only. IntAct records ELISA, pull-down and crystallography [DB:IntAct].","key_references":[{"PMID":"34155118","why":"Crystal structure of AMH-AMHR2 and key interface residues"},{"PMID":"7997230","why":"Cloning of AMHR2 and AMH binding in COS cells"}],"covers":["LR000051","LR003601"]},"LR000055":{"pair":"ANGPT1 -> TEK","headline":"Well-established direct ANGPT1 agonist ligand of TEK (Tie2), with binding mapping, phosphorylation, mouse knockout and many database records.","interaction_type":"direct binding","direction_and_effect":"ANGPT1 is a secreted TEK ligand that binds TIE2 and induces its tyrosine phosphorylation without directly promoting cultured endothelial cell growth [PMID:8980223]. Angiopoietin-1 induced TEK phosphorylation in hematopoietic cells [PMID:9723709]. Ang1-deficient mice show angiogenic deficits like Tie2-deficient mice, indicating a primary physiologic ligand [PMID:8980224]. Agonist.","molecular_requirements":"The first Ig-like loop plus EGF-like repeats of Tie-2 (amino acids 1-360) are necessary and sufficient to bind Ang-1 and Ang-2; the first 104 amino acids are essential but not sufficient [PMID:12427764]. Ang-1 and Ang-2 bind similarly with similar affinities in hematopoietic cells [PMID:9723709]. Single chain receptor (TEK).","affinity_potency":[],"species_and_systems":"Human ligand and receptor in recombinant/cell systems [PMID:12427764][PMID:8980223][PMID:9723709]; mouse knockout in vivo [PMID:8980224]; Tie-2 exon-2 knockout mice described [PMID:12427764]. Human PDB structure 4K0V contains both chains [DB:PDB 4K0V].","localisation_and_range":"ANGPT1 is flagged as secreted and TEK as transmembrane [flag]; ANGPT1 is described as a secreted ligand [PMID:8980223].","caveats":"All four shown papers were read as abstracts only and none gives a numeric affinity in our evidence. Ang-1 and Ang-2 share the same binding domain, so binding site alone does not explain their different effects [PMID:12427764]. One further row is review-only and one pending.","key_references":[{"PMID":"8980223","why":"Identification of Ang-1 as secreted TIE2 ligand inducing phosphorylation"},{"PMID":"12427764","why":"Maps the Tie-2 region (aa 1-360) needed for Ang-1 binding"},{"PMID":"8980224","why":"Ang-1 knockout mice phenocopy Tie2 deficiency"}],"covers":["LR000055","LR003605"]},"LR003610":{"pair":"Angptl1 -> Tek","headline":"No evidence in this dossier concerns Angptl1; both papers describe Ang-3/Ang4 binding or activating Tie-2.","interaction_type":"database-asserted only","direction_and_effect":"The papers describe Ang-3 binding Tie-2 [PMID:15280392] and Ang3 and Ang4 as Tie2 agonists [PMID:15284220]; Angptl1 is not mentioned in their evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse pair only, projected from human evidence. The cited work used Ang-3 or recombinant Ang3/Ang4 in endothelial cells and mice [PMID:15284220].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Both papers were read as abstracts. The listed evidence does not test ANGPTL1 and appears to be assigned to the wrong ligand. Two further papers were abstract_insufficient. Treat this pair as unsupported by our evidence.","key_references":[],"covers":["LR003610"]},"LR002107":{"pair":"ANGPTL2 -> LILRB3","headline":"ANGPTL2 bound LILRB3-overexpressing cells with lower affinity than LILRB2; one paper, cell-binding assay only.","interaction_type":"direct binding","direction_and_effect":"Angptl2 bound LILRB3-overexpressing cells [PMID:22660330]. Effect on receptor signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor expressed in 293T cells [PMID:22660330].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Binding to LILRB3 was described as of lower affinity than to LILRB2-expressing cells; the values are in a supplementary table not shown [PMID:22660330]. The paper's purified-protein co-IP and SPR were for LILRB2, not LILRB3. No affinity in our evidence.","key_references":[{"PMID":"22660330","why":"Angptl2 binds LILRB3-expressing cells, weaker than LILRB2"}],"covers":["LR002107"]},"LR002116":{"pair":"ANGPTL4 -> LEPR","headline":"ANGPTL4 is reported to bind the leptin receptor by SPR and co-IP in one mouse heterotopic-ossification study.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4, induced from brown fat after tenotomy, binds LepR on PRRX1+ mesenchymal cells and promotes chondrogenesis and heterotopic ossification; curator labels it agonist [PMID:38147550]. LepR disruption in PRRX1+ cells or ANGPTL4 deletion impedes this [PMID:38147550].","molecular_requirements":"Co-IP shows full-length LepR and the N-terminal fragment pull down ANGPTL4, while the fragment lacking the N-terminus does not; docking suggests the C-terminus of ANGPTL4 is the contact site [PMID:38147550].","affinity_potency":[{"value":"ABS (tr_KD) = 21.924","assay":"SPR, ANGPTL4 with LepR; units not given","system":"as reported; leptin comparator ABS (tr_KD) = 8.103","cite":"PMID:38147550"}],"species_and_systems":"Mouse tenotomy model, HEK293 co-IP with GST-ANGPTL4; AlphaFold mouse IDs used for docking [PMID:38147550]. The curator fields say human, which looks inconsistent. Human pair is ortholog-inferred.","localisation_and_range":"ANGPTL4 is flagged secreted; LEPR transmembrane [flag]; serum factor acting on cells at the injury site [PMID:38147550].","caveats":"Abstract plus full-text excerpts. The affinity figure has no units and is described as higher than leptin, so treat the number cautiously. Signalling through LepR by ANGPTL4 is not directly shown in the excerpts.","key_references":[{"PMID":"38147550","why":"ANGPTL4 binds LepR and drives heterotopic ossification"}],"covers":["LR002116","LR005438"]},"LR002125":{"pair":"ANGPTL7 -> LAIR1","headline":"ANGPTL7 binds LAIR1-overexpressing cells; binding is described as relatively weak.","interaction_type":"functional only","direction_and_effect":"Angptl1 and Angptl7 bound LAIR1-overexpressing 293T cells [PMID:22660330]. Their binding to LAIR1+ human cord blood cells was relatively weak [PMID:22660330]. Signalling effect is not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human LAIR1 on 293T cells and human cord blood cells [PMID:22660330]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL7 flagged secreted; LAIR1 transmembrane [flag].","caveats":"Weak binding; the study then focused on ANGPTL2 and ANGPTL5 with LILRB2, not on ANGPTL7-LAIR1 [PMID:22660330].","key_references":[{"PMID":"22660330","why":"Angptl7 binds LAIR1 cells, weakly"}],"covers":["LR002125","LR005444"]},"LR005041":{"pair":"ANPEP -> SELE","headline":"CD13 (ANPEP) is reported as an E-selectin ligand through sLeX glycans, from a glycoproteomics screen.","interaction_type":"direct binding","direction_and_effect":"A glycoproteomics screen of E-selectin-binding glycoproteins from a human breast cancer cell line identified CD44 (HCELL) and CD13 as key E-selectin ligands [PMID:29777742]. Both display sLeX, which is the E-selectin ligand glycan [PMID:29777742].","molecular_requirements":"Binding is via the sLeX glycan on CD13, so the glycoform matters, not the protein core alone [PMID:29777742].","affinity_potency":[],"species_and_systems":"Human breast cancer cell line CF1_T and clinical tissue [PMID:29777742]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANPEP flagged secreted; SELE transmembrane [flag]; cell-surface adhesion.","caveats":"Abstract only; validation is by flow cytometry, Western blot, IHC and PLA, not a purified binding assay; no affinity.","key_references":[{"PMID":"29777742","why":"CD13 and CD44 identified as sLeX-bearing E-selectin ligands"}],"covers":["LR001654","LR005041"]},"LR000064":{"pair":"ANXA1 -> FPR2","headline":"Direct binding and agonism of FPR2 by ANXA1, with full-length protein FPR2-selective; several supporting papers read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"ANXA1 acts as an agonist of FPR2 (FPRL1/ALX). Full-length ANXA1 bound FPRL-1/ALX only (not FPR) in transfected HEK-293 cells and caused ERK activation only in FPRL-1/ALX-transfected cells; blocking FPRL-1/ALX with a neutralising antibody abolished its effect on neutrophil adhesion under flow [PMID:16278303]. Chimeric-receptor work places the FPR2/ALX N-terminal region and extracellular loop II as the domain needed for AnxA1 signalling [PMID:22610094]. GtoPdb lists the interaction as full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain, no co-receptor reported in our evidence. The N-terminal peptide Ac2-26 is less selective: it bound and activated both FPR and FPRL-1/ALX [PMID:16278303], and an annexin 1 N-terminal peptide activated all three FPR family members at similar concentrations [PMID:15187149]. The pKd value below came from ANXA1-derived peptides, not intact ANXA1 [PMID:12368905].","affinity_potency":[{"value":"pKd 6.5","assay":"radioligand binding, ANXA1-derived peptide (curator note: not intact ANXA1)","system":"recombinant human ALXR/FPRL1","cite":"PMID:12368905"}],"species_and_systems":"Human receptor and human cells throughout: transfected HEK-293 cells, human neutrophils [PMID:16278303, PMID:22610094, PMID:12368905]. The mouse pair is projected from human evidence (ortholog inferred), not tested here.","localisation_and_range":"ANXA1 is flagged as secreted and FPR2 as transmembrane [flag]; this suggests paracrine signalling to cell-surface FPR2.","caveats":"Four papers were shown and all were read as abstracts (plus excerpts); three further judged papers were abstract-insufficient. FPR2 is also bound by a lipid mediator (aspirin-triggered lipoxin A4), so it is not peptide-exclusive [PMID:12368905]. Peptide fragments and intact ANXA1 differ in receptor selectivity, so peptide data should not be assigned to full-length ANXA1.","key_references":[{"PMID":"16278303","why":"Full-length ANXA1 binds FPR2 but not FPR; peptide Ac2-26 binds both."},{"PMID":"12368905","why":"Radioligand binding with ANXA1-derived peptides on recombinant ALXR."},{"PMID":"22610094","why":"Chimeras map the FPR2 domains needed for AnxA1 signalling."}],"covers":["LR000064","LR003614"]},"LR012160":{"pair":"APCDD1 -> FZD8:LRP5","headline":"APCDD1 binds LRP5 (not shown for the Frizzled chain) and inhibits Wnt signalling; evidence is one paper, so the FZD8 complex is inferred.","interaction_type":"direct binding","direction_and_effect":"APCDD1 acts as an inhibitor of Wnt/beta-catenin signalling: it reduced WNT3A-induced TOP/FOP reporter activity ~2-fold, including with LRP5/Fzd2, in HEK293T cells, and reduced Wnt activity in chick neural tube and Xenopus embryos [PMID:20393562]. The authors suggest it may prevent formation of the Wnt receptor complex [PMID:20393562].","molecular_requirements":"The extracellular domain of APCDD1 co-precipitated with tagged LRP5 and WNT3A [PMID:20393562]. No FZD8 binding was tested in this paper; the paper reports no interaction with Fzd2, Fzd8 and Dkk4 (data not shown) [PMID:20393562]. So the LRP5 chain carries the evidence and the Frizzled chain of this complex is not supported by it. Fzd8 specifically showed no interaction [PMID:20393562].","affinity_potency":[],"species_and_systems":"Human APCDD1 and LRP5 constructs, recombinant tagged proteins in HEK293T cells (GST pulldown / co-precipitation); functional tests in HEK293T, chick neural tube and Xenopus embryos [PMID:20393562]. Human pair only.","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein; its extracellular domain was used for binding [PMID:20393562]. Acts at the cell surface, likely cell-autonomously [PMID:20393562].","caveats":"Single paper, interaction shown in vitro only [PMID:20393562]. Binding was to LRP5 and WNT3A, not to the full receptor complex. Our record is listed as the combined complex; IntAct and UniProt entries cite the same paper [DB:IntAct] [DB:UniProt].","key_references":[{"PMID":"20393562","why":"Shows APCDD1 co-precipitates LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012160"]},"LR002134":{"pair":"APOA1 -> ABCA1","headline":"Well supported: apoA-I directly cross-links to ABCA1's first extracellular domain, and the interaction supports lipid efflux. ABCA1 is a transporter.","interaction_type":"direct binding","direction_and_effect":"ApoA-I binds ABCA1 and drives cholesterol efflux; efflux is lost in mutants with reduced apoA-I cross-linking [PMID:12084722]. ApoA-I binding promotes lipid efflux and inhibits calpain degradation of ABCA1, raising ABCA1 levels [PMID:12511593]. Endogenous apoA-I stabilizes ABCA1 in macrophages [PMID:22271762].","molecular_requirements":"Binding maps to the N-terminal half of ABCA1, with the first extracellular domain as the apoA-I site [PMID:30458687]; critical residues lie in two extracellular loops [PMID:12084722]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ABCA1 in 293 cells with cross-linking [PMID:12084722]; ABCA1-expressing cells with photo-crosslinking [PMID:30458687]; human macrophages [PMID:22271762]. ApoA-I infusion raised ABCA1 in vivo (species not stated) [PMID:12511593].","localisation_and_range":"ApoA-I is flagged secreted; ABCA1 carries transmembrane and receptor flags [flag]. Secreted ligand acting on a membrane protein.","caveats":"The W590S mutant retains full apoA-I cross-linking yet cannot support efflux, so binding is necessary but not sufficient [PMID:12084722]. All four papers were read as abstracts only. ABCA1 is a lipid transporter, not a classical signalling receptor.","key_references":[{"PMID":"12084722","why":"Cross-linking with Tangier mutants"},{"PMID":"30458687","why":"Photo-crosslinking maps apoA-I to the first extracellular domain"},{"PMID":"12511593","why":"Positive feedback: apoA-I stabilizes ABCA1"}],"covers":["LR002134","LR005451"]},"LR007102":{"pair":"APOB -> APOBR","headline":"Supported only by a name match (APOBR is named 'apolipoprotein B receptor'); no experimental evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. The only record is the HGNC name, where APOBR is 'apolipoprotein B receptor' [DB:HGNC approved name].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"APOBR carries transmembrane and receptor flags; APOB is flagged secreted [flag].","caveats":"Two papers were judged abstract_insufficient. A gene name is not evidence of binding.","key_references":[],"covers":["LR007102"]},"LR002143":{"pair":"APOC3 -> LDLR","headline":"Mouse genetics show APOC3 inhibits triglyceride-rich lipoprotein clearance through LDLR; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"An APOC3-targeting antisense oligonucleotide lowered fasting triglycerides in a manner dependent on LDLR and LRP1; the effect was lost only in mice lacking both [PMID:27400128]. The authors conclude APOC3 inhibits clearance of triglyceride-rich lipoproteins (antagonist-like) through the hepatic LDLR/LRP1 axis [PMID:27400128].","molecular_requirements":"Redundant: either LDLR or LRP1 alone suffices for the effect; both knocked out abolishes it [PMID:27400128].","affinity_potency":[],"species_and_systems":"Mouse, in vivo with knockout lines and injections of lipoproteins [PMID:27400128]. Human pair is ortholog-inferred.","localisation_and_range":"APOC3 flagged secreted; the receptor carries a receptor flag [flag]. Mainly hepatic clearance [PMID:27400128].","caveats":"Indirect genetic evidence; no binding assay in our evidence. Abstract only. Single paper, same for both receptors.","key_references":[{"PMID":"27400128","why":"ASO and receptor knockouts show LDLR/LRP1-dependent effect"}],"covers":["LR002143","LR005460"]},"LR000073":{"pair":"APOE -> LRP1","headline":"Well supported across human and mouse: binding in liver membranes, proximity ligation in pericytes, and brain co-IP.","interaction_type":"direct binding","direction_and_effect":"ApoE liposomes bound specifically to HepG2 cell surfaces and human liver membranes, with a binding protein indistinguishable from LRP; authors concluded LRP might function as an apoE receptor [PMID:2779654]. Proximity ligation showed APOE3 and murine Apoe binding LRP1 with high affinity in pericytes, whereas APOE4-LRP1 was barely detectable [PMID:22622580]. Endogenous APOE pulled down LRP1 from E14.5 mouse brain lysate [PMID:31677479].","molecular_requirements":"Isoform matters: APOE4 binds LRP1 poorly in pericytes [PMID:22622580]. Subunits not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells (HepG2, liver membranes) [PMID:2779654]; mouse pericytes and embryonic brain [PMID:22622580] [PMID:31677479]. Human and mouse pairs both have direct evidence.","localisation_and_range":"APOE flagged secreted [flag]; embryonic brain APOE was widely distributed, consistent with a secreted protein [PMID:31677479].","caveats":"Most papers abstract-level; 22622580 text is listed as abstract only although full-text reading is noted. One paper is pending and one abstract-insufficient. 1989 crosslinking is suggestive, not conclusive.","key_references":[{"PMID":"2779654","why":"apoE liposome crosslinking to LRP"},{"PMID":"22622580","why":"APOE3 vs APOE4 LRP1 proximity ligation in pericytes"},{"PMID":"31677479","why":"APOE-LRP1 pull-down in E14.5 brain"}],"covers":["LR000073","LR003622"]},"LR000082":{"pair":"APP -> GPC1","headline":"Glypican-1 binds fibrillar amyloid-beta via heparan sulfate chains; this is not evidence that APP itself is a GPC1 ligand.","interaction_type":"direct binding","direction_and_effect":"Glypican-1 binds fibrillar Abeta, mainly through its heparan sulfate chains [PMID:15084524]. Co-overexpression of glypican-1 and APP in SH-SY5Y cells reduced viability and increased susceptibility to thapsigargin stress and Abeta toxicity [PMID:15084524].","molecular_requirements":"Binding is mainly mediated by the HS chains, so a glycosaminoglycan rather than the core protein [PMID:15084524]. No signalling partners reported.","affinity_potency":[],"species_and_systems":"Human brain tissue, detergent-insoluble glycosphingolipid-enriched (DIG) membrane fractions and SH-SY5Y cells [PMID:15084524]. Mouse pair is ortholog-inferred.","localisation_and_range":"Glypican-1 is localised in DIG domains and in primitive and classic plaques [PMID:15084524]; GPC1 is flagged secreted and receptor [flag].","caveats":"One paper, abstract only. The ligand tested is fibrillar Abeta, not APP. IntAct lists a surface plasmon resonance array record for APP-GPC1 [DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"15084524","why":"Glypican-1 binds fibrillar Abeta via HS chains"}],"covers":["LR000082","LR003631"]},"LR002161":{"pair":"APP -> LRP2","headline":"No supporting paper; only a BioGRID reconstituted-complex record supports this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the BioGRID record [DB:BioGRID].","localisation_and_range":"Not reported in our evidence; flags mark LRP2 as a receptor [flag].","caveats":"All 8 judged papers were rated as concerning a different entity, so none confirm the pair. The only support is a BioGRID reconstituted-complex record [DB:BioGRID]. Treat as unverified.","key_references":[],"covers":["LR002161","LR005476"]},"LR002170":{"pair":"ASGR1 -> LDLR","headline":"ASGR1 is reported to target LDLR for degradation, independently of PCSK9; supported by one cell-and-mouse paper, with direct binding inferred.","interaction_type":"functional only","direction_and_effect":"ASGR1, like PCSK9, targets LDLR; both independently interact with and enhance degradation of the receptor, with no cooperativity seen in livers of wild-type and Pcsk9-/- mice [PMID:34508778]. ASGR1 knockdown raised LDLR (curator summary: about 1.2-fold total, about 4-fold cell-surface in HepG2-naive cells) [PMID:34508778]. Effect is LDLR-lowering (antagonist-like).","molecular_requirements":"The curator's reading of the abstract is that ASGR1 binds LDLR both sugar-dependently and sugar-independently, based on a carbohydrate-binding-deficient mutant; furin cleaves ASGR1 into a secreted form likely losing LDLR-degrading function [PMID:34508778]. ASGR2 is overexpressed together in some experiments [PMID:34508778].","affinity_potency":[],"species_and_systems":"Human HepG2 cells (naive and PCSK9-knockout) and mouse livers; both partners recorded as human [PMID:34508778].","localisation_and_range":"ASGR1 is flagged secreted and receptor, LDLR as receptor [flag]. The paper describes a cleaved secreted ASGR1 form [PMID:34508778]. Cell-surface and cellular interaction, range not reported in our evidence.","caveats":"Single paper; evidence is Western blot, immunofluorescence and knockdown, so no purified-protein binding or affinity is shown in the excerpts. ASGR1 is a receptor itself, so this is a receptor-receptor regulatory interaction, not a classical ligand-receptor pair.","key_references":[{"PMID":"34508778","why":"ASGR1 targets LDLR for degradation independently of PCSK9"}],"covers":["LR002170","LR005484"]},"LR000091":{"pair":"ASIP -> MC3R","headline":"ASIP inhibits agonist-stimulated cAMP at human MC3R in one 1997 paper (abstract only); a relatively weak antagonist here, no affinity number in our evidence.","interaction_type":"functional only","direction_and_effect":"ASIP is an antagonist: purified recombinant ASIP inhibited agonist-stimulated cAMP generation (alpha-MSH, or ACTH for hMC2R) and also inhibited radiolabeled-melanocortin binding to hMCR1-5. At MC3R it is a relatively weak inhibitor (surmountable antagonism) [PMID:9058374].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence. Degree and mechanism of inhibition vary significantly among the five melanocortin receptor subtypes [PMID:9058374].","affinity_potency":[],"species_and_systems":"Human ASIP and human MC3R stably expressed in L cells [PMID:9058374]. Recombinant cell assays, not in vivo.","localisation_and_range":"ASIP is flagged secreted and the receptor as a transmembrane receptor [flag]; the paper calls agouti protein a paracrine signalling molecule (stated for mouse agouti) [PMID:9058374]. ","caveats":"Single paper, read as abstract only. No Kd, Ki or IC50 in our evidence, so potency is qualitative. Schild-analysis details are not available beyond the abstract-level curator note. The same paper covers all five melanocortin receptors, so this is one study counted in five pairs.","key_references":[{"PMID":"9058374","why":"Pharmacology of human ASIP at hMC1R-hMC5R: cAMP and binding inhibition"}],"covers":["LR000091"]},"LR012061":{"pair":"BAMBI -> ACVR2A:BMPR1A","headline":"BAMBI to ACVR2A:BMPR1A has no verified paper; support is limited to one BioGRID record that names a different receptor chain pair.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are ACVR2A and BMPR1A; the BioGRID record concerns BMPR1B only, which is not a member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012061"]},"LR000109":{"pair":"BMP10 -> BMPR2","headline":"Well supported: BMP10 binds the type II receptor BMPR2 with high affinity by SPR, with structural and functional support.","interaction_type":"direct binding","direction_and_effect":"BMPR2 is a high-affinity growth-factor receptor for BMP10 [PMID:35643319]. BMPRII shRNA suppressed BMP10 signalling in MC3T3 cells [PMID:16049014]. GtoPdb lists BMP10 as an agonist [DB:GtoPdb].","molecular_requirements":"BMPR2-Fc bound BMP10 with a slow dissociation rate [PMID:35643319]; BMP10 does not discriminate among ACVR2A, ACVR2B and BMPR2 [PMID:22718755]. PDB 7PPA/7PPB/7PPC give structures with BMP10 [DB:PDB 7PPA].","affinity_potency":[{"value":"KD 2.1E-09 M (SD 2.8E-10)","assay":"SPR, BMP10 over captured BMPRII-Fc","system":"recombinant proteins","cite":"PMID:35643319"}],"species_and_systems":"Recombinant Fc-fusion SPR [PMID:35643319]; MC3T3 cell line shRNA [PMID:16049014]. Curators annotate human. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"Abstract read; the KD comes from a table in the full-text excerpts. The binding KD is from a single-curve fit average of two injections.","key_references":[{"PMID":"35643319","why":"SPR: BMP10 binds BMPR2 with high affinity"},{"PMID":"22718755","why":"BMP10 does not discriminate among type II receptors"},{"PMID":"16049014","why":"BMPRII shRNA suppresses BMP10 signalling"}],"covers":["LR000109","LR003658"]},"LR007111":{"pair":"BMP2 -> ACVR2A:BMPR1B","headline":"Database-listed pair, but the one paper judged reports BMPR1B was not required for BMP-2/4 signalling in primary human MSCs.","interaction_type":"conflicting","direction_and_effect":"Records show BMP2 as agonist at ACVR2A and at BMPR1B separately [DB:GtoPdb]. In the verified negative, siRNA knockdown in primary human MSCs found BMPR1B was not found to play a significant role in signalling by BMP-2, -4, -6 or -7 [PMID:18436533].","molecular_requirements":"Not reported for this heteromer in our evidence. In the same screen ACVR2A and BMPR1A, not BMPR1B, were the receptors for osteoinductive BMP-2/4 activity [PMID:18436533].","affinity_potency":[],"species_and_systems":"Negative result from human primary mesenchymal stem cells [PMID:18436533]. BioGRID BMP2-BMPR1B reconstituted-complex records exist [DB:BioGRID]; their species and conditions are not reported in our evidence.","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor complex is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"BMPR1B was expressed at low levels in those cells, so the negative may reflect expression rather than inability to bind [PMID:18436533]. Abstract-only read. No positive paper for this pair; support is from databases (BioGRID, GtoPdb, IntAct, Reactome) [DB:BioGRID][DB:GtoPdb].","key_references":[{"PMID":"18436533","why":"explicit negative for BMPR1B in hMSC"}],"covers":["LR007111"]},"LR000118":{"pair":"BMP2 -> ACVR2B","headline":"Direct binding shown by SPR/Bio-Layer Interferometry with recombinant human proteins, plus mouse-cell receptor complex labelling and a crystal structure record.","interaction_type":"direct binding","direction_and_effect":"rhBMP2 bound ACVR2B and activated SMAD signalling and osteoblast markers in C3H10T1/2 cells; effect recorded as agonist [PMID:21702718]. GtoPdb lists BMP2 as agonist [DB:GtoPdb]. In mouse P19 cells, [125I]BMP2 formed heteromeric complexes with ActRII and ActRIIB [PMID:9748228].","molecular_requirements":"Type II receptor; BMP2 also bound type I ALK3 and ALK6 with similar affinity and ALK2 far more weakly [PMID:21702718]. Complex formation with type I receptors was seen in P19 cells [PMID:9748228]. PDB 2H62 has a chain of BMP2 (P12643) and of ACVR2B (Q13705) [DB:PDB 2H62].","affinity_potency":[{"value":"KD (kin) 8.0 nM","assay":"surface plasmon resonance, 1:1 Langmuir fit (read from Table III column order)","system":"recombinant human BMP2 and ACVR2B","cite":"PMID:21702718"}],"species_and_systems":"Human recombinant ligand and receptor for binding [PMID:21702718]; mouse P19 cells for the labelling experiment [PMID:9748228]. Human and mouse pairs both present.","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor complex is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"The 21702718 abstract was the curated read, with binding values taken from full-text excerpts; the dossier mentions both SPR and Bio-Layer Interferometry. The 9748228 quote is browser-read and unverifiable, spot-check pending. The abstract of 9748228 concerns BMP7 and activin, not BMP2 as main subject. Binding affinity alone did not predict outcome [PMID:21702718]. Three further papers are pending.","key_references":[{"PMID":"21702718","why":"measured BMP2 binding to ACVR2B and other BMPRs"},{"PMID":"9748228","why":"BMP2 heteromeric complexes with ActRIIB in P19 cells"}],"covers":["LR000118","LR003667"]},"LR000127":{"pair":"BMP4 -> ACVR2A","headline":"No curator-verified paper; support rests on BioGRID and GtoPdb records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists the interaction as Agonist [DB:GtoPdb]. BioGRID records a reconstituted complex between ACVR2A and BMP4 [DB:BioGRID 2469097].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; BioGRID reconstituted complex suggests an in vitro system.","localisation_and_range":"BMP4 is flagged secreted and ACVR2A a transmembrane receptor [flag].","caveats":"No paper was confirmed (8 abstract_insufficient, 1 review_only), so no binding or functional result was verified; database records only.","key_references":[],"covers":["LR000127","LR003676"]},"LR007120":{"pair":"BMP4 -> BMPR1A:BMPR2","headline":"BMP4 binds BMPR1A and BMPR2 in separate binding papers and both were required in hMSC; complex formation itself is not shown directly.","interaction_type":"direct binding","direction_and_effect":"BMP-4 bound ALK-3 (BMPR1A) in nontransfected cells [PMID:8006002]; BMP-4 bound BMPR-II less efficiently than BMP-7 in COS-1 cells [PMID:7644468]. Knockdown in primary hMSC showed both BMPR1A and BMPR2 contribute to osteoinductive BMP-2/4 activity, with BMP-2/4 relying more on BMPR2 than BMP-6/7 [PMID:18436533]. UniProt lists BMP4 initiating signalling via BMPR1A and BMPR2 [DB:UniProt].","molecular_requirements":"BMPR-II bound ligand only weakly alone; binding was facilitated by co-present type I receptors, so both chains are needed [PMID:7644468]. BMPR1A and BMPR2 were both required in hMSC [PMID:18436533].","affinity_potency":[],"species_and_systems":"COS-1 and COS transfectants, MC3T3-E1 and human foreskin fibroblasts [PMID:8006002; PMID:7644468]; primary human MSC [PMID:18436533].","localisation_and_range":"BMP4 flagged secreted; BMPR1A transmembrane [flag].","caveats":"All papers abstract only. The 1994 binding paper used C. elegans DAF-4 as type II partner, not human BMPR2 [PMID:8006002]. No affinity values. Curator notes that PMID 11241215 is weak here.","key_references":[{"PMID":"8006002","why":"BMP-4 binds ALK-3 (BMPR1A)"},{"PMID":"7644468","why":"BMP-4 binds BMPR-II, facilitated by type I receptors"},{"PMID":"18436533","why":"Both chains needed in primary hMSC"}],"covers":["LR007120"]},"LR000136":{"pair":"BMP6 -> BMPR1A","headline":"Weak direct binding of BMP-6 to BMPR-IA in one full-text paper; database agonist and UniProt notes agree.","interaction_type":"direct binding","direction_and_effect":"BMP-6 weakly bound BMPR-IA (ALK-3), to which BMP-2 also bound; curated effect is agonist [PMID:10504300]. GtoPdb lists BMP6 as agonist at BMPR1A [DB:GtoPdb]. UniProt says BMP6 may promote HAMP expression via BMPR1A/ALK3 [DB:UniProt].","molecular_requirements":"Binding was assayed with type I and type II receptors co-expressed; the paper reports binding by BMPR-IA in MC3T3-E1 and C2C12 cells [PMID:10504300]. Whether BMPR-IA alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Affinity cross-linking and co-immunoprecipitation of 125I-BMP-6 (recombinant human) with transfected COS-7 cells; endogenous binding in mouse MC3T3-E1 and C2C12 cell lines [PMID:10504300]. The human pair is not ortholog-inferred; the mouse pair is.","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Binding was described as weak, in contrast to strong binding to ALK-2. Only one verified paper; no affinity value reported.","key_references":[{"PMID":"10504300","why":"Direct binding of BMP-6 to BMPR-IA, weak, cross-linking in COS-7 and mouse cell lines"}],"covers":["LR000136","LR003685"]},"LR005500":{"pair":"BMP6 -> RGMB","headline":"Direct SPR binding of BMP6 to RGMB, Kd 28 nM, in one 2012 paper; intermediate affinity of the three RGMs.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance measured binding of RGMB to BMP6 with K(D) 28 nM; curated effect is agonist [PMID:23029472].","molecular_requirements":"RGM proteins are described as BMP co-receptors; the paper measured RGM protein binding to BMP ligands, and receptor chains needed for signalling are not reported in our evidence [PMID:23029472].","affinity_potency":[{"value":"Kd 28 nM","assay":"surface plasmon resonance","system":"recombinant RGM proteins with BMP ligands","cite":"PMID:23029472"}],"species_and_systems":"Recombinant human proteins per curator; abstract-level curation with full-text excerpts describing SPR (mean of 4-9 experiments) [PMID:23029472]. Mouse pair is ortholog-inferred.","localisation_and_range":"The receptor is not flagged as secreted [flag]; localisation is otherwise not reported in our evidence.","caveats":"Affinity data are from an in vitro SPR matrix; no cellular signalling result for this pair is reported in our evidence. Compared with other RGMs: HJV 8.1, RGMB 28, RGMA 55 nM for BMP6 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGM proteins for BMP ligands"}],"covers":["LR002186","LR005500"]},"LR000145":{"pair":"BMP7 -> ENG","headline":"Endoglin associates with BMP7 only via activin type II receptors; endoglin cannot bind the ligand alone.","interaction_type":"direct binding","direction_and_effect":"Endoglin interacts with BMP-7 but requires coexpression of the respective ligand-binding kinase receptor; it cannot bind ligands on its own [PMID:9872992]. It interacts with activin-A and BMP-7 via activin type II receptors ActRII and ActRIIB, regardless of the type I partner, and did not interact with BMP-7 through complexes containing the BMP type II receptor [PMID:9872992]. Effect on signalling: endoglin did not alter heteromeric complex formation, though it coprecipitated [PMID:9872992].","molecular_requirements":"ActRII or ActRIIB is required; endoglin is described as an accessory protein of multiple TGF-beta superfamily kinase receptor complexes [PMID:9872992]. Not a stand-alone receptor.","affinity_potency":[],"species_and_systems":"Human, cell-based affinity labelling and coprecipitation [PMID:9872992]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Single paper read as abstract only; this is accessory-receptor association, not direct ligand binding, and the interaction class for this row is Ligand-Receptor without a stated effect.","key_references":[{"PMID":"9872992","why":"Endoglin associates with BMP-7 through ActRII/ActRIIB"}],"covers":["LR000145","LR003694"]},"LR005050":{"pair":"BMP7 -> HJV","headline":"BMP7 binds HJV directly by SPR (Kd 20 nM); single abstract-level paper with full-text support, human proteins.","interaction_type":"direct binding","direction_and_effect":"Curators record the effect as agonist; the paper's abstract describes RGM proteins as co-receptors that enhance cellular responses to BMP ligands, but this paper measured binding only [PMID:23029472].","molecular_requirements":"Binding was measured for the RGM protein alone; type I/II BMP receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 20 nM","assay":"surface plasmon resonance","system":"recombinant human proteins (curator-annotated species)","cite":"PMID:23029472"}],"species_and_systems":"SPR with recombinant proteins; curators annotate both partners as human, mouse pair is ortholog-inferred [PMID:23029472].","localisation_and_range":"BMP7 is flagged secreted and HJV is flagged secreted [flag]; range of action not reported in our evidence.","caveats":"HJV had the highest affinity for BMP7 among the three RGMs [PMID:23029472]. BMP7 had the lowest relative affinity of the BMPs tested for the RGMs, and BMP7-RGM data needed CM4 sensor chips because fitting on CM5 chips was poor [PMID:23029472]. Curator read depth is abstract-only. Only one paper.","key_references":[{"PMID":"23029472","why":"SPR kinetics of all RGM-BMP pairs including BMP7"}],"covers":["LR001664","LR005050"]},"LR011206":{"pair":"BMP8B -> BMPR2","headline":"BMP8B -> BMPR2 rests only on a GtoPdb agonist record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B-BMPR2 as Type=Agonist, Action=Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"BMPR2 is the single chain listed; whether a type I partner is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence (human entities).","localisation_and_range":"Receptor flagged as a receptor [flag]; range not reported in our evidence.","caveats":"No verified paper; candidate papers were abstract-insufficient or about a different entity. The GtoPdb record is a database assertion only.","key_references":[],"covers":["LR011206"]},"LR003700":{"pair":"C1qa -> Cd93","headline":"One 2026 mouse stroke study reports C1q binding to CD93 on endothelial cells; abstract-level, in vivo.","interaction_type":"functional only","direction_and_effect":"Microglia-derived C1q is reported to bind CD93 on endothelial cells, upregulating VCAM-1 and disrupting the blood-brain barrier in the ipsilateral ventral posterior nucleus after dMCAO [PMID:42010605].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse dMCAO model, thalamic endothelial cells [PMID:42010605].","localisation_and_range":"C1q annotated secreted [flag]; paracrine from microglia to endothelium per the paper.","caveats":"Abstract only; binding assay not described in our evidence. One other judged row was classed different_entity.","key_references":[{"PMID":"42010605","why":"mouse in vivo C1q-CD93 axis in BBB disruption"}],"covers":["LR003700"]},"LR002215":{"pair":"C1QL2 -> ADGRB3","headline":"C1QL2 binds ADGRB3 (BAI3) thrombospondin-repeat domain with high affinity; abstract-level paper plus BioGRID and UniProt.","interaction_type":"direct binding","direction_and_effect":"C1ql proteins bind BAI3 and, at submicromolar levels, decrease synapse density in cultured neurons; the BAI3 thrombospondin-repeat fragment prevented this [PMID:21262840]. Effect direction for C1QL2 alone is not reported in our evidence.","molecular_requirements":"Binding is to the BAI3 extracellular thrombospondin-repeat domain, mediated by the globular C1q domain of the ligand [PMID:21262840].","affinity_potency":[],"species_and_systems":"Species and cell system not stated in the abstract and not labelled by the curator; the human and mouse interactions are both ortholog-inferred. BioGRID lists Affinity Capture-MS [DB:BioGRID] and UniProt lists the interaction [DB:UniProt].","localisation_and_range":"C1QL2 secreted and ADGRB3 transmembrane per flags [flag].","caveats":"Abstract only; the paper covers all four C1ql proteins collectively; no affinity number.","key_references":[{"PMID":"21262840","why":"All four C1ql proteins bind the BAI3 thrombospondin-repeat domain with high affinity via the gC1q domain"}],"covers":["LR002215","LR005528"]},"LR000154":{"pair":"C1QTNF5 -> MFRP","headline":"Binding of CTRP5 to MFRP rests on database records (co-IP, pull-down); the curated paper treats it as background.","interaction_type":"database-asserted only","direction_and_effect":"Direction not reported. In Mfrp(174delG) mutant mice, CTRP5 mRNA and protein were upregulated while MFRP was undetectable by Western blot [PMID:21810984].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (Mfrp(174delG) mutant) in the paper [PMID:21810984]. IntAct lists co-immunoprecipitation and pull-down records (PMIDs 17122143, 24531000, 16600989) [DB:IntAct]; UniProt says CTRP5 interacts with MFRP [DB:UniProt]. Human pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; MFRP flagged as receptor, topology not stated.","caveats":"The curated paper characterises a mouse mutant and describes the binding as established, not tested; the upregulation despite MFRP loss suggests regulation is not co-dependent. Abstract only. No affinity.","key_references":[{"PMID":"21810984","why":"Mouse Mfrp null model; CTRP5 upregulated (binding mentioned as background)"}],"covers":["LR000154","LR003703"]},"LR000163":{"pair":"C4A -> CR1","headline":"C4b from C4A binds CR1; two abstract-only papers and Reactome support.","interaction_type":"direct binding","direction_and_effect":"125I-sCR1 bound ammonia-treated C4A and C4B, with up to twice as much on C4A [PMID:8422437]. C4b additively supported CR1-mediated erythrocyte adhesion with C1q, with BIAcore binding to immobilized CR1 [PMID:10528211]. Reactome records CR1:C4b [DB:Reactome].","molecular_requirements":"C4b binds independently of C1q and C3b sites [PMID:10528211]. Binding depended on pH and ionic strength [PMID:8422437].","affinity_potency":[],"species_and_systems":"Human proteins: soluble recombinant CR1 in microtitre plates [PMID:8422437]; erythrocyte adhesion and BIAcore [PMID:10528211].","localisation_and_range":"CR1 is a membrane receptor; contact-dependent (annotation).","caveats":"Both papers abstract only. Ligands are C4b or ammonia-treated C4, not intact C4A.","key_references":[{"PMID":"8422437","why":"sCR1 binding to C4A versus C4B"},{"PMID":"10528211","why":"C4b binding to CR1 by BIAcore"}],"covers":["LR000163"]},"LR002224":{"pair":"C4A -> F2RL3","headline":"C4a acts as an untethered agonist at PAR4 (F2RL3) with nanomolar activity; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"C4a was an agonist for both PAR1 and PAR4 with nanomolar activity, and ERK activation in human endothelial cells needed both receptors [PMID:28973891].","molecular_requirements":"C4a showed no activity toward known anaphylatoxin receptors [PMID:28973891]. Calcium response was via PAR1, not shown for PAR4.","affinity_potency":[],"species_and_systems":"Cell-based reporter screen and human endothelial cells [PMID:28973891].","localisation_and_range":"C4a flagged secreted, F2RL3 transmembrane [flag].","caveats":"Abstract only; shared PMID with the F2R pair; no numeric potency. Ligand is the C4a fragment, not full C4A.","key_references":[{"PMID":"28973891","why":"C4a as PAR1/PAR4 agonist"}],"covers":["LR002224"]},"LR002233":{"pair":"CADM3 -> CADM4","headline":"Direct CADM3-CADM4 binding by SPRi, plus axon-Schwann cell adhesion; no Kd in evidence.","interaction_type":"direct binding","direction_and_effect":"Axon-Schwann cell interaction is described as primarily mediated by axonal CADM3 binding CADM4 on myelinating Schwann cells [PMID:33889941]. SPRi detected heterophilic interactions of CADM3 and CADM4 with all CADM members [PMID:30131958]. A CADM3 variant (Tyr172Cys) was ER-retained, had reduced surface expression and reduced co-localisation with CADM4 at contacts [PMID:33889941].","molecular_requirements":"Not reported in our evidence beyond ectodomain-Fc binding.","affinity_potency":[],"species_and_systems":"SPRi with human-labelled Fc ectodomains [PMID:30131958]; human families and Cadm3Y170C mice in the variant study [PMID:33889941]. The binding statement there is background in the abstract.","localisation_and_range":"Both flagged membrane-bound [flag]; axon-Schwann cell contact [PMID:33889941].","caveats":"The second paper was read as abstract only and the CADM3-CADM4 binding is stated as background, not measured [PMID:33889941]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"30131958","why":"SPRi CADM-family binding"},{"PMID":"33889941","why":"CADM3-CADM4 axon-glia adhesion; disease variant reduces co-localisation"}],"covers":["LR002233","LR005543"]},"LR000172":{"pair":"CALCA -> RAMP1","headline":"alpha-CGRP acts on receptor complexes containing RAMP1 (with CALCRL or CALCR); RAMP1 is a subunit, not a stand-alone receptor. Multiple functional and binding studies.","interaction_type":"direct binding","direction_and_effect":"alpha-CGRP is an agonist at RAMP1-containing receptors: CRLR/RAMP1 gives a CGRP receptor [PMID:9620797], and [125I]halphaCGRP binding and cAMP signalling were seen with RAMP1/CRLR [PMID:11693189] and CTR2/RAMP1 [PMID:14722252]. In rat trigeminal neurons CGRP also acts through CTR/RAMP1 (AMY1) in addition to CLR/RAMP1 [PMID:26125036]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"RAMP1 works only as part of a heterodimer: CRLR/RAMP1 [PMID:12234182][PMID:9620797] or CTR/RAMP1 (AMY1) [PMID:26125036][PMID:14722252]. Shortening the RAMP1 transmembrane domain progressively impaired hCRLR association and abolished CGRP receptor function [PMID:12234182]. In CTRa assays the RAMP1 C-terminal domain increased CGRP potency [PMID:16531504]. Using CALCRL-RAMP1 for scoring is supported; RAMP1 alone is not a receptor.","affinity_potency":[{"value":"pEC50 8.9 to 11.3","assay":"GtoPdb agonist record (cAMP potency)","system":"database record, system not given in dossier","cite":"DB:GtoPdb"}],"species_and_systems":"Experiments used human clones in HEK-293 or COS-7 cells (recombinant) [PMID:14722252][PMID:16531504][PMID:12234182], human/porcine CRLR [PMID:11693189] and rat trigeminal ganglion neurons and tissue with human tissue expression [PMID:26125036]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; paracrine or endocrine action is implied by that flag only.","caveats":"All shown papers were read as abstracts except one full text [PMID:26125036]. The evidence concerns the receptor complex, not direct CGRP contact with RAMP1 itself; one curator note says the cross-linking is for the RAMP-GPCR complex [PMID:11023820]. Reference [PMID:30139742] is a structure of the AM2/IMD fragment on RAMP1-CLR, not CGRP. CGRP also signals via CTR/RAMP1, so a RAMP1 hit does not identify the CALCRL receptor [PMID:26125036].","key_references":[{"PMID":"9620797","why":"RAMP1 with CRLR defines the CGRP receptor"},{"PMID":"11693189","why":"[125I]halphaCGRP binding to RAMP1/CRLR"},{"PMID":"26125036","why":"CGRP acts via CALCRL/RAMP1 and CTR/RAMP1 in trigeminal neurons"}],"covers":["LR000172","LR003717"]},"LR011107":{"pair":"CALM1 -> ADCY8","headline":"Calmodulin-ADCY8 rests on one Reactome complex record.","interaction_type":"database-asserted only","direction_and_effect":"Reactome has a complex ADCY1,ADCY8:CALM1:4xCa2+ at the plasma membrane [DB:Reactome R-HSA-9617533]. Direction and effect are not reported in our evidence.","molecular_requirements":"Ca2+-bound calmodulin (4xCa2+) in the Reactome complex [DB:Reactome R-HSA-9617533].","affinity_potency":[],"species_and_systems":"Human, from a database record.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. Four rows were different_entity.","key_references":[],"covers":["LR011107"]},"LR002242":{"pair":"CBLN1 -> GRID2","headline":"CBLN1 and GRID2 interact in a trans-synaptic bridge; evidence here is an abstract-level statement of similar binding.","interaction_type":"direct binding","direction_and_effect":"Cbln1 and Cbln2 are reported to have similar binding activities to beta-neurexins and Grid2, and in cerebellum Cbln1 bridges presynaptic beta-neurexins to postsynaptic Grid2 on Purkinje neurons [PMID:22117778]. Effect is synaptic organising (agonist per curators).","molecular_requirements":"CBLN1 acts as a bridge between beta-neurexins and Grid2, so neurexin may be a required partner in the synapse [PMID:22117778]. A PDB structure holds one chain of each partner [DB:PDB 5KCA].","affinity_potency":[],"species_and_systems":"Transgenic and null mice (cerebellum, striatum, thalamus); the species of the binding assays is not reported in our evidence, and the curators recorded human [PMID:22117778]. Human pair is ortholog-inferred, mouse is the direct one.","localisation_and_range":"CBLN1 is flagged secreted and GRID2 transmembrane [flag]; synaptic cleft action across neurons is described [PMID:22117778].","caveats":"The paper (full text available) is mainly about CBLN2 redundancy; the sentence on binding is a summary claim, and no affinity is reported. A second confirmed paper was not shown.","key_references":[{"PMID":"22117778","why":"Cbln1 and Cbln2 bind beta-neurexins and Grid2; redundancy in cerebellum"}],"covers":["LR002242","LR005552"]},"LR000181":{"pair":"CCK -> CCKBR","headline":"Well supported agonist-receptor pair: human CCK2 receptor binding (Kd ~20 nM for CCK8 conjugates) and signalling in several papers, plus GtoPdb, IntAct and PDB.","interaction_type":"direct binding","direction_and_effect":"CCK-8 stimulated phosphatidylinositol hydrolysis and Ca2+ mobilization in cells expressing the cloned receptor [PMID:7681836]; CCK-8 and gastrin I both bound and signalled [PMID:8349705]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Contact points: His207 with Asp8 of CCK [PMID:10438490]; Tyr189 and Asn358 with the C-terminal amide [PMID:12695525]. PDB 8IA7 has both chains [DB:PDB 8IA7].","affinity_potency":[{"value":"Kd approximately 20 nmol/L","assay":"saturation binding of 111In-DTPAGlu-G-CCK8","system":"NIH-3T3 and A431 cells overexpressing CCKBR","cite":"PMID:15001692"},{"value":"Kd 20-40 nM","assay":"binding of two labelled CCK8 derivatives","system":"A431 cells overexpressing CCK-BR","cite":"PMID:15068617"},{"value":"pIC50 8.8","assay":"binding","system":"human brain CCK-B receptor in CHO cells","cite":"PMID:8349705"},{"value":"pIC50 9.9-10.0","assay":"GtoPdb record","system":"database","cite":"PMID:7681836"}],"species_and_systems":"Human receptor in CHO, COS-7, NIH-3T3 and A431 cells; nude mouse xenografts for tracer imaging [PMID:15001692, PMID:15068617]. Mouse pair is projected.","localisation_and_range":"CCK flagged secreted, CCKBR transmembrane [flag].","caveats":"Affinity values for the Kd entries come from modified CCK8 conjugates, not native CCK. The receptor also binds gastrin [PMID:8349705]. All papers read as abstracts.","key_references":[{"PMID":"7681836","why":"Cloning of the human CCK-B/gastrin receptor with CCK-8 signalling"},{"PMID":"8349705","why":"Human brain CCK-B receptor binding and signalling in CHO cells"},{"PMID":"10438490","why":"His207-Asp8 direct contact point"}],"covers":["LR000181","LR003726"]},"LR002251":{"pair":"CCK -> GPR83","headline":"Reported for proCCK-derived peptides (ProCCK56-62/63) binding GPR83, not for the bioactive CCK peptide; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"ProCCK56-62 and ProCCK56-63 bind GPR83 with high affinity, activate second messenger pathways and induce receptor endocytosis; they couple to Gas at low and Gai at high concentrations [PMID:35605991].","molecular_requirements":"Signalling bias depends on peptide: PEN22 and PEN20 favour Gai, PEN18, PEN19 and ProCCK peptides favour Gas [PMID:35605991].","affinity_potency":[],"species_and_systems":"Peptides identified in mouse brain; curated species human/human [PMID:35605991]. Mouse pair is the non-inferred one.","localisation_and_range":"CCK flagged secreted [flag]; localisation of ProCCK peptides not reported.","caveats":"The abstract states ProCCK56-62 has no homology to the bioactive cholecystokinin domain [PMID:35605991]. No affinity values in our evidence. Abstract only.","key_references":[{"PMID":"35605991","why":"ProCCK peptides bind and activate GPR83"}],"covers":["LR002251","LR005561"]},"LR000190":{"pair":"CCL13 -> CCR2","headline":"CCL13 is reported to interact with CCR2 in monocytes and transfectants; support is mostly comparator or inferential data.","interaction_type":"direct binding","direction_and_effect":"MCP-4 displaced 125I-MCP-1 from monocyte binding sites, suggesting interaction with CCR2 [PMID:9195948]. CCL13 acted as a comparator CCR2 agonist in chemotaxis, less efficacious than vCCL4 [PMID:12554737]. GtoPdb and Reactome record CCL13 as a CCR2 agonist/binder [DB:GtoPdb][DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 2.1 +/- 1.4 nM","assay":"displacement of 125I-MCP-1","system":"human monocytes","cite":"PMID:9195948"}],"species_and_systems":"Human monocytes and murine L1.2 cells expressing CCR2 [PMID:9195948][PMID:12554737].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Another paper measured binding of MMP-cleaved truncated analogues, which are antagonists; processing state flips direction [PMID:12149192]. Abstract-only reads; the IC50 comes from a sentence about three chemokines.","key_references":[{"PMID":"9195948","why":"MCP-4 binds and signals through CCR2B"},{"PMID":"12554737","why":"CCL13 as comparator CCR2 agonist"},{"PMID":"12149192","why":"MMP-cleaved MCPs become CCR2 antagonists"}],"covers":["LR000190"]},"LR000208":{"pair":"CCL19 -> ACKR4","headline":"Well supported direct, high-affinity binding of CCL19 to the atypical receptor ACKR4, which acts as a scavenger rather than a classical signaller.","interaction_type":"direct binding","direction_and_effect":"ACKR4 internalises CCL19 as a decoy receptor and recruits beta-arrestins in response to CCL19 [PMID:23341447]; no classical Gi signalling, though a pertussis-toxin-insensitive CRE-reporter response was seen and required an intact DRY motif [PMID:23341447]. A systematic screen classed CCL19 as a beta-arrestin-recruiting agonist [PMID:32480426].","molecular_requirements":"Not reported in our evidence beyond ACKR4 alone in transfected systems.","affinity_potency":[{"value":"pKi 8.4","assay":"binding (as curated)","system":"human CCX-CKR/ACKR4","cite":"PMID:23341447"},{"value":"pEC50 8.5-9.1","assay":"GtoPdb agonist record","system":"not specified","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor in all papers [PMID:23341447][PMID:10706668][PMID:32480426]; radiolabelled competition binding with CCX CKR-expressing cells [PMID:10706668]. Mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"All three papers read as abstract only. The 2000 paper reports ELC (CCL19 by alias) as a high-affinity ligand with IC50 <15 nM [PMID:10706668]. Reactome and BioGRID also record the interaction [DB:Reactome][DB:BioGRID].","key_references":[{"PMID":"23341447","why":"Decoy function, beta-arrestin recruitment, pKi 8.4"},{"PMID":"10706668","why":"Radioligand binding, IC50 <15 nM"},{"PMID":"32480426","why":"beta-arrestin screen confirms CCL19 as ACKR4 agonist"}],"covers":["LR000208","LR003736"]},"LR000235":{"pair":"CCL2 -> CCR10","headline":"One abstract-read paper with a 1997 receptor named CCR10; identity with current CCR10 is doubtful.","interaction_type":"direct binding","direction_and_effect":"MCP-1 competed for MCP-3 binding to the cloned receptor with IC50 1.2 nM; the paper presents MCP-1 and MCP-3 as the highest-affinity ligands [PMID:9364936].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 1.2 nM","assay":"competition for MCP-3 binding","system":"cloned receptor","cite":"PMID:9364936"}],"species_and_systems":"Human ligand and receptor [PMID:9364936]; expressed mainly in placenta and fetal liver per the abstract [PMID:9364936]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Single abstract-only paper. The same PMID supports CCL2->ACKR2 in this batch, so the receptor may have been mapped to the wrong gene. No database records.","key_references":[{"PMID":"9364936","why":"Cloned receptor binds MCP-1 and MCP-3"}],"covers":["LR000235","LR003756"]},"LR000217":{"pair":"CCL21 -> CXCR3","headline":"Conflicting: murine CCL21 acts on mouse CXCR3, but human CCL21 is reported not to bind CXCR3, so the human pair is doubtful.","interaction_type":"conflicting","direction_and_effect":"In mouse CXCR3-transfected cells a screen identified CCL21 (6Ckine) as a ligand inducing calcium flux [PMID:9653165]. In mouse microglia, CCL21 triggered a Cl- current and chemotaxis that was absent in CXCR3-knockout but retained in CCR7-knockout cells [PMID:11907075]. Murine 6C-kine inhibited tumour growth in a human lung cancer SCID model [PMID:11225989].","molecular_requirements":"CXCR3 alone mediated the microglial response without CCR7 [PMID:11907075]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"All positive evidence uses murine CXCR3 or murine CCL21: lower-affinity binding of SLC to murine CXCR3 in L1.2 cells [PMID:10556837], mouse CXCR3 cells [PMID:9653165], mouse microglia [PMID:11907075], and murine 6C-kine in SCID mice [PMID:11225989]. No affinity value for CCL21 is given in the dossier.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor.","caveats":"The abstract of PMID:11225989 states that human 6C-kine, unlike murine 6C-kine, does not bind CXCR3 and had no anti-tumour effect; UniProt also records that human CCL21 does not bind CXCR3 [DB:UniProt]. The human row here is therefore projected from mouse and contradicted. CCL21 binding to murine CXCR3 was described as lower affinity than IP10, ITAC and Mig [PMID:10556837]. Abstract-only reads.","key_references":[{"PMID":"9653165","why":"CCL21 identified as mouse CXCR3 ligand"},{"PMID":"11907075","why":"CXCR3 knockout abolishes CCL21 response in microglia"},{"PMID":"11225989","why":"states human CCL21 does not bind CXCR3"}],"covers":["LR000217"]},"LR002260":{"pair":"CCL22 -> ACKR4","headline":"One systematic abstract-read screen shows CCL22 as a potent partial agonist of ACKR4 in a beta-arrestin recruitment assay.","interaction_type":"functional only","direction_and_effect":"CCL22 acted as a potent partial agonist of ACKR4 in a beta-arrestin recruitment screen of 43 human chemokines [PMID:32480426]. ACKR4 is described as a regulator or scavenger of chemokines [PMID:32480426].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chemokines and human ACKR4 in a beta-arrestin recruitment assay [PMID:32480426]. The mouse pair is projected from human. No database record.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor.","caveats":"Single paper, abstract only; no affinity or potency value quoted. CCL22 is described as a CCR4 and ACKR2 ligand elsewhere in the abstract [PMID:32480426].","key_references":[{"PMID":"32480426","why":"systematic screen identifying CCL22 as ACKR4 partial agonist"}],"covers":["LR002260","LR005563"]},"LR000226":{"pair":"CCL26 -> CCR2","headline":"CCL26 (eotaxin-3) antagonises CCR2, confirmed in a human CHO cell line study.","interaction_type":"direct binding","direction_and_effect":"Antagonist: eotaxin-3 acts as an antagonist of CCR2 [PMID:15207250]; GtoPdb also lists an antagonist [DB:GtoPdb].","molecular_requirements":"CCR2 alone in a CHO line [PMID:15207250].","affinity_potency":[{"value":"pIC50 8.5","assay":"curated binding/inhibition value","system":"CHO cell line expressing CCR2","cite":"PMID:15207250"}],"species_and_systems":"Human ligand and receptor in engineered CHO cells [PMID:15207250].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"One paper, abstract only. A prior report of the antagonism is cited by the paper itself, not shown as judged here.","key_references":[{"PMID":"15207250","why":"CHO lines confirm eotaxin-3 antagonism of CCR2"}],"covers":["LR000226"]},"LR000244":{"pair":"CCL3L3 -> CCR5","headline":"LD78beta binds CCR5 with about 6-fold higher affinity than LD78alpha and is more potent after CD26 processing; two abstract-read papers.","interaction_type":"direct binding","direction_and_effect":"LD78beta has enhanced receptor binding affinity to CCR5, approximately 6-fold over LD78alpha [PMID:10364178]. LD78beta(3-70) competed tenfold more efficiently than LD78beta(1-70) with [125I]RANTES for CCR5 and CCR1 [PMID:11449371].","molecular_requirements":"The CD26-processed (3-70) form is the more potent form at CCR5 [PMID:11449371]. Other requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins [PMID:10364178][PMID:11449371]. BioGRID lists CCL3L1 - CCR5 records [DB:BioGRID].","localisation_and_range":"CCL3L3 is flagged as secreted and CCR5 as transmembrane [flag].","caveats":"Both papers were read as abstracts only; no absolute affinity values in our evidence. BioGRID attributes records to CCL3L1, so the CCL3L3 assignment rests on curators' mapping.","key_references":[{"PMID":"10364178","why":"LD78beta has about 6-fold enhanced CCR5 affinity"},{"PMID":"11449371","why":"CD26-processed LD78beta is tenfold more potent at CCR5"}],"covers":["LR000244"]},"LR000253":{"pair":"CCL4 -> CCR5","headline":"Well supported: CCL4 (MIP-1 beta) binds CCR5 with sub-nanomolar Kd and acts as a full agonist, backed by several databases.","interaction_type":"direct binding","direction_and_effect":"CCL4 is a CCR5 ligand: transfected cells bind it with high affinity and signal (inositol phosphates) [PMID:8663314]; GtoPdb lists it as a full agonist [DB:GtoPdb]. Its N-loop and 3(10) turn residues (Arg18, Lys19, Arg22, Pro21) contribute to CCR5 binding [PMID:12427015].","molecular_requirements":"UniProt notes glycosylation on Ser-6 of the receptor is required for efficient CCL4 binding [DB:UniProt]. Reactome lists a CCL4:CCR5,CCR1 complex [DB:Reactome R-HSA-8865354].","affinity_potency":[{"value":"Kd 0.23 nM","assay":"[125I]-MIP-1beta radioligand binding","system":"human recombinant CCR5","cite":"PMID:16298345"},{"value":"Kd 0.24 nM","assay":"[125I]-MIP-1beta radioligand binding","system":"macaque CCR5","cite":"PMID:16298345"},{"value":"pKi 9.4 to 9.6","assay":"GtoPdb interaction record","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor and ligand in recombinant systems [PMID:16298345, PMID:8663314]; the mutagenesis paper's species is not reported in our evidence [PMID:12427015].","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"All three papers were read as abstracts only. IntAct lists a scintillation proximity assay [DB:IntAct]. Also, the macaque Kd is a different species and is shown only for comparison.","key_references":[{"PMID":"16298345","why":"Kd 0.23 nM for human CCR5"},{"PMID":"8663314","why":"CCR5 cloning; binds MIP-1beta and signals"},{"PMID":"12427015","why":"Residues of MIP-1beta needed for CCR5 binding"}],"covers":["LR000253"]},"LR000262":{"pair":"CCL5 -> SDC1","headline":"One abstract-level paper reports RANTES co-immunoprecipitating with syndecan-1 on human macrophages; proteoglycan binding, not classical signalling.","interaction_type":"direct binding","direction_and_effect":"RANTES associated with syndecan-1 and syndecan-4 but not syndecan-2 or betaglycan in co-immunoprecipitation from human monocyte-derived macrophages [PMID:14637022]. Glycosaminidase pre-treatment strongly reduced RANTES binding to syndecan-1 and -4, implicating glycosaminoglycan chains [PMID:14637022]. BioGRID lists Affinity Capture-Western from the same paper [DB:BioGRID].","molecular_requirements":"Binding depends on glycosaminoglycans per the abstract; syndecan-1 acts as an attachment proteoglycan that may facilitate subsequent RANTES-CCR5 interaction [PMID:14637022]. No signalling through syndecan-1 is reported.","affinity_potency":[],"species_and_systems":"Human macrophages, endogenous proteins [PMID:14637022]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL5 is flagged secreted; the syndecan-1 entry is flagged both secreted and transmembrane [flag].","caveats":"Abstract only; co-IP shows association, not direct binding or affinity. The only support is this one paper plus the BioGRID record from it.","key_references":[{"PMID":"14637022","why":"RANTES co-IPs with syndecan-1/-4 on human macrophages"}],"covers":["LR000262","LR003772"]},"LR000271":{"pair":"CCL7 -> ACKR1","headline":"Human ACKR1 (DARC) binds CCL7 in two papers, one with Ki 6.6 nM; ACKR1 is an atypical receptor and signalling was not shown.","interaction_type":"direct binding","direction_and_effect":"DARC bound pro-inflammatory chemokines including CCL7 in competition binding, but not lymphoid chemokines [PMID:13679391]. CCL2 bound to DARC failed to induce a Ca2+ response in CCR2B cells, suggesting down-regulation of chemokine activity; this was shown for CCL2, not CCL7 [PMID:13679391]. No signalling by CCL7 via ACKR1 is reported.","molecular_requirements":"Not reported in our evidence. A PDB structure with chains of P80098 and Q16570 is recorded [DB:PDB 8JPS].","affinity_potency":[{"value":"Ki 6.6 nM","assay":"125I-CXCL8 displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes (PMID:15358176) and DARC-expressing cells; DARC-knockout mice showed no lymph node change [PMID:13679391]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; ACKR1 flagged transmembrane receptor [flag].","caveats":"13679391 read as abstract only. The abstract lists CCL7 as a binder but gives no CCL7 affinity. Decoy role is suggested by the abstract's CCL2 result, not shown for CCL7.","key_references":[{"PMID":"15358176","why":"CCL7 Ki 6.6 nM at Duffy on erythrocytes"},{"PMID":"13679391","why":"DARC binds CCL7 among inflammatory chemokines"}],"covers":["LR000271","LR003781"]},"LR000424":{"pair":"CCN1 -> ITGB5","headline":"CCN1 binds purified alphavbeta5 and drives fibroblast migration through it; one paper supports this pair.","interaction_type":"direct binding","direction_and_effect":"Fibroblast migration to CYR61 was mediated through integrin alpha(v)beta(5), and CYR61 bound directly to purified alpha(v)beta(5) in vitro [PMID:11287419]. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","molecular_requirements":"beta5 pairs with alphav; the effect did not need the carboxyl-terminal domain of CYR61 [PMID:11287419].","affinity_potency":[],"species_and_systems":"Human skin fibroblasts and purified integrin; CYR61 human. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Single paper, abstract only; the database record cites the same paper, so it is not independent. No affinity is reported.","key_references":[{"PMID":"11287419","why":"Direct alphavbeta5 binding and migration role"}],"covers":["LR000424","LR003921"]},"LR000280":{"pair":"CD14 -> ITGB1","headline":"Direct binding of CD14-Fc to integrin alpha4beta1 reported in one abstract-read paper; ITGB1 is the shared chain.","interaction_type":"direct binding","direction_and_effect":"CD14-Fc bound affinity-purified alpha4beta1 dose-dependently, and Jurkat adhesion to CD14-Fc was alpha4beta1-dependent [PMID:17274987].","molecular_requirements":"The evidence is for the alpha4beta1 heterodimer; K562 cells lacking alpha4 did not adhere until alpha4 was re-expressed, so beta1 alone is not shown to suffice [PMID:17274987].","affinity_potency":[],"species_and_systems":"Human cells and recombinant CD14-Fc; mouse pair is ortholog-inferred only [PMID:17274987].","localisation_and_range":"CD14 flagged secreted and receptor [flag]; tested as adhesion to immobilised protein [PMID:17274987].","caveats":"Single paper, abstract only; chain-level assignment to ITGB1 is inferred from the heterodimer; no database records.","key_references":[{"PMID":"17274987","why":"CD14-Fc binds alpha4beta1"}],"covers":["LR000280","LR003790"]},"LR001702":{"pair":"CD160 -> TNFRSF14","headline":"CD160 binds HVEM (TNFRSF14) directly with structural and SPR support; engagement is co-inhibitory in CD4+ T cells.","interaction_type":"direct binding","direction_and_effect":"CD160 engagement of HVEM acts as a bidirectional switch for T-cell activation; CD160 crosslinking inhibited CD3/CD28 activation of human CD4+ T cells [PMID:18193050]. UniProt notes CD160 interacts with TNFRSF14 and down-regulates CD28 costimulation [DB:UniProt].","molecular_requirements":"CD160 binds HVEM cysteine-rich domains 1-3 and competes with BTLA, while LIGHT binds a distinct site [PMID:21959263]. Deleting cysteine-rich domain 1 abolished inhibition [PMID:18193050]. The CD160 extracellular domain is mainly a monomer [PMID:21959263].","affinity_potency":[],"species_and_systems":"Human proteins and human CD4+ T cells; the mouse pair is also listed but its experiments are not described [PMID:18193050][PMID:21959263].","localisation_and_range":"CD160 is flagged secreted, receptor and transmembrane [flag]; the papers describe a GPI-anchored membrane protein engaging HVEM on a partner cell [PMID:18193050].","caveats":"Both papers were read as abstracts only. Inhibition by HVEM-transfected cells depended on both CD160 and BTLA, so effects are shared with BTLA [PMID:18193050]. Structures exist [DB:PDB 6NG3][DB:PDB 7MSG].","key_references":[{"PMID":"21959263","why":"SPR: CD160 binds HVEM CRD1-3, competes with BTLA"},{"PMID":"18193050","why":"HVEM as bidirectional switch; CD160 inhibits CD4+ T cells"}],"covers":["LR001702","LR005071"]},"LR001711":{"pair":"CD226 -> PVR","headline":"Well supported: PVR (CD155) binds CD226 (DNAM-1) by reciprocal Fc-chimera staining; the mouse pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"PVR-Fc stained DNAM-1-expressing COS-7 cells and DNAM-1-Fc stained PVR CHO-K transfectants; the DNAM-1/PVR interaction enhanced NK-mediated tumour lysis [PMID:15607800].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in COS-7 and CHO-K transfectants [PMID:15607800]; the mouse interaction was projected from human evidence.","localisation_and_range":"PVR is flagged secreted and transmembrane, CD226 transmembrane [flag]; contact between NK cell and target.","caveats":"Only one paper in our evidence (abstract only); no affinity reported. Database records exist (BioGRID, IntAct incl. SPR and others) [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"15607800","why":"Reciprocal Fc-chimera binding of PVR and DNAM-1"}],"covers":["LR001711","LR005078"]},"LR001720":{"pair":"CD47 -> SIRPA","headline":"CD47 binds SIRPA, well supported by binding, affinity, structure and database records.","interaction_type":"direct binding","direction_and_effect":"SIRPalpha binds CD47 through its IgV domain, and Gln67, Ala/Val at position 57 and Met102 determine this binding [PMID:17070842]. SIRP-Fc fusions supported cell adhesion that was blocked by antibody, with CD47 identified as the ligand [PMID:10572074]. Physical-interaction and structural records exist [DB:PDB 2JJS][DB:IntAct P78324-Q08722].","molecular_requirements":"Single-chain pair; the SIRPalpha IgV domain is the binding unit [PMID:17070842].","affinity_potency":[{"value":"Kd approximately 2 microM","assay":"soluble SIRP binding to CD47 (compared with SIRPgamma)","system":"human proteins","cite":"PMID:15294972"}],"species_and_systems":"Human proteins in all three papers per curators [PMID:17070842][PMID:15294972][PMID:10572074]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Both partners carry transmembrane flags, so signalling is by cell contact [flag]; CD47 also carries a secreted flag [flag].","caveats":"Papers are abstract-only. The Kd comes as a comparator in a SIRPgamma paper [PMID:15294972]. One abstract was insufficient and is not shown.","key_references":[{"PMID":"17070842","why":"SIRPalpha IgV residues governing CD47 binding"},{"PMID":"15294972","why":"SIRPalpha Kd approximately 2 microM"},{"PMID":"10572074","why":"CD47 identified as the ligand for SIRP in adhesion"}],"covers":["LR001720","LR005087"]},"LR002305":{"pair":"CDH10 -> CDH10","headline":"Homophilic type II cadherin pair; the one verified paper's evidence sentence does not clearly show CDH10 self-binding.","interaction_type":"direct binding","direction_and_effect":"Homophilic adhesion partner of itself; direction is a formality. The curated sentence reports cadherin-6 analyte binding strongest on cadherin-6, -9 or -10 surfaces, followed by cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 form one specificity group with similar binding profiles [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"The paper's excerpt states cadherin-10 analyte did not show binding above background on a cadherin-8 surface; homophilic cadherin-10 strength is not quantified in our evidence [PMID:29742438]. Human result is ortholog-projected. No affinity reported.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002305","LR005603"]},"LR002314":{"pair":"CDH4 -> CDH2","headline":"R- and N-cadherin interact weakly in mouse cell aggregation; one abstract-level paper plus a BioGRID record.","interaction_type":"functional only","direction_and_effect":"In L cell aggregation, mixing mouse R-cadherin and N-cadherin cells gave separate and chimeric aggregates, suggesting they can interact although each prefers its own type [PMID:8270638].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L cell aggregation assays [PMID:8270638]; the human pair is ortholog-inferred. BioGRID lists CDH4 - CDH2 Affinity Capture-Western [DB:BioGRID] [PMID:10662782].","localisation_and_range":"Membrane-bound adhesion molecules, contact-dependent [flag].","caveats":"Weak, preference-biased heterotypic binding; abstract-only read; direct binding not measured; four papers judged as different entity, three abstract-insufficient.","key_references":[{"PMID":"8270638","why":"Mouse R-/N-cadherin cell aggregation"}],"covers":["LR002314","LR005612"]},"LR002323":{"pair":"CEACAM1 -> CEACAM1","headline":"Homophilic CEACAM1 adhesion mapped to the N-terminal domain; supported by one abstract plus several IntAct records.","interaction_type":"direct binding","direction_and_effect":"Site-directed mutagenesis of soluble CEACAM1 showed the CC' loop is crucial for homophilic adhesion: V39A/D40A and GFCC'C'' face triple mutants abolished adhesion, and an R64D/D82R salt-bridge swap rescued it [PMID:11520797]. IntAct records several physical assays [DB:IntAct]; Reactome has a CEACAM heterodimer complex [DB:Reactome R-HSA-202716].","molecular_requirements":"N-terminal IgV domain residues are critical [PMID:11520797].","affinity_potency":[],"species_and_systems":"Human CEACAM1, soluble protein adhesion assays with mutants [PMID:11520797].","localisation_and_range":"Adhesion between CEACAM1 molecules, i.e. homophilic cell-contact binding; not stated beyond that in our evidence.","caveats":"Abstract only. Homophilic pair: the same entity is both ligand and receptor, so direction is not meaningful.","key_references":[{"PMID":"11520797","why":"Mutagenesis of CEACAM1 homophilic adhesion site"}],"covers":["LR002323"]},"LR002332":{"pair":"CEACAM6 -> SELE","headline":"Glycan-mediated: CD66 antigens present sialyl-Lewis x to E-selectin on endothelium; one old abstract-level paper.","interaction_type":"functional only","direction_and_effect":"CD66 antigens (NCA-160/NCA-90) function as presenter molecules of SLe(x) structures on neutrophils that bind to ELAM-1 on endothelial cells [PMID:1378450]. Soluble CEA-related antigens inhibited neutrophil adherence in a way blocked by anti-ELAM-1 antibody [PMID:1378450].","molecular_requirements":"GPI-linked forms matter: neutrophils lacking GPI-linked NCA-90/95 showed diminished adherence, and transmembrane NCA-160 only partly retained function [PMID:1378450].","affinity_potency":[],"species_and_systems":"Human neutrophils (including PNH cells) and IL-1beta-activated endothelium [PMID:1378450].","localisation_and_range":"Neutrophil-to-endothelium cell contact (adhesion) [PMID:1378450].","caveats":"Abstract only, 1992. The binding determinant is the carbohydrate, not the CEACAM6 protein surface; sialidase treatment abolished inhibition. NCA-160/NCA-90 naming is not mapped to CEACAM6 in the paper text we have.","key_references":[{"PMID":"1378450","why":"CD66 antigens present SLe(x) to ELAM-1"}],"covers":["LR002332"]},"LR002341":{"pair":"CGB5 -> LHCGR","headline":"hCG beta (CGB5) acts as an agonist at the human LH/CG receptor; support is hCG-level, not gene-specific.","interaction_type":"direct binding","direction_and_effect":"hCG activates LHCGR as an agonist; it and LH induce different signalling profiles [PMID:26441830]. Stimulation with hCG increased cAMP [PMID:12727981].","molecular_requirements":"Binding to the leucine-rich-repeat domain is similar for hCG and LH; differences localise to the hinge region, including a primate-specific exon 10 segment relevant only to LH signalling [PMID:26441830]. Exon 10 deletion does not impair hCG action [PMID:12727981]. PDB complexes 7FIG, 7FIH, 7FII listed [DB:PDB 7FIG].","affinity_potency":[],"species_and_systems":"Human proteins; stable COS-7 cells expressing LH receptor with or without exon 10 [PMID:12727981]; homology modelling and mutagenesis [PMID:26441830].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; the paper describes hCG as secreted by the placenta [PMID:26441830].","caveats":"Both papers were read as abstracts per read_depth; they concern hCG/LH generally, not CGB5 specifically. No affinity value reported in our evidence.","key_references":[{"PMID":"12727981","why":"Binding of LH and hCG to LHR with or without exon 10 is similar; hCG action unaffected"},{"PMID":"26441830","why":"hCG vs LH signalling at LHCGR hinge region"}],"covers":["LR002341"]},"LR005104":{"pair":"CIRBP -> TREM1","headline":"Extracellular CIRP binds TREM-1 by SPR and FRET and drives inflammation; two abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"eCIRP is a new biologically active ligand of TREM-1, fueling inflammation in sepsis; knockdown, the decoy peptide LP17 or TREM-1-/- mice reduced eCIRP-induced inflammation [PMID:32027618]. A 7-aa eCIRP-derived peptide, M3, blocked the TREM-1 and eCIRP interaction [PMID:32027618]. The eCIRP-TREM-1 axis was reported to promote ICAM-1-Rho-mediated NETosis in sepsis (title only; abstract truncated) [PMID:32506691].","molecular_requirements":"Not reported in our evidence beyond TREM-1 itself.","affinity_potency":[],"species_and_systems":"SPR, FRET in macrophages, siRNA and TREM-1-/- mice (mouse in vivo) [PMID:32027618]; CIRP peptide derived from human eCIRP.","localisation_and_range":"eCIRP is the extracellular form, flagged secreted [flag].","caveats":"SPR showed a 'strong binding affinity' but no value is reported in our evidence. PMID 32506691 is a functional paper with a truncated abstract. Both read as abstracts.","key_references":[{"PMID":"32027618","why":"SPR and FRET binding of eCIRP to TREM-1; blocking peptide"},{"PMID":"32506691","why":"eCIRP-TREM-1 axis and NETosis (functional)"}],"covers":["LR001744","LR005104"]},"LR000307":{"pair":"CNTF -> IL6ST","headline":"CNTF signals through a CNTFR/gp130/LIFR complex; gp130 is a shared signalling chain, so support is for the complex rather than direct CNTF-gp130 binding.","interaction_type":"functional only","direction_and_effect":"CNTF acts as an agonist; GtoPdb lists it as Agonist [DB:GtoPdb]. Signalling through the complex was shown in human receptor reconstitution and cell assays [PMID:10966616][PMID:16051226].","molecular_requirements":"CNTF signals through a receptor complex of CNTFR with gp130 (IL6ST) and LIFR [PMID:10966616][PMID:16051226]. gp130 is shared among CNTF, LIF and OSM signalling [PMID:16051226]. CNTFR is the non-signalling alpha chain [PMID:10966616]. UniProt states ligand binding to CNTFR induces dimerization of IL6ST/gp130 and LIFR [DB:UniProt]. A PDB structure holds chains of CNTFR and LIFR proteins, not gp130 [DB:PDB 8D74].","affinity_potency":[],"species_and_systems":"Human proteins in reconstituted receptor complex and cell signalling [PMID:10966616][PMID:16051226]. The mouse pair is inferred from human evidence.","localisation_and_range":"CNTF is flagged secreted and IL6ST a transmembrane receptor [flag].","caveats":"No direct CNTF-gp130 binding is shown; gp130 acts as a signalling chain within a complex and is shared across cytokines. Both confirmed papers were read as abstracts only. A user scoring this pair should require CNTFR and LIFR too.","key_references":[{"PMID":"16051226","why":"CNTF signalling needs LIFR N-terminal domain within gp130/LIFR complex"},{"PMID":"10966616","why":"Describes CNTFR with gp130 and LIFR complex"}],"covers":["LR000307","LR003813"]},"LR005113":{"pair":"CNTN6 -> NOTCH1","headline":"CNTN6 (NB-3) is reported to activate Notch signalling in oligodendrocyte lineage cells; functional evidence from one abstract, no binding data.","interaction_type":"functional only","direction_and_effect":"NB-3 (the curator's name for CNTN6) acts as a Notch ligand: it triggers nuclear translocation of the Notch intracellular domain, promotes oligodendrogliogenesis and differentiation via Deltex1, and raises myelin-associated glycoprotein transcripts [PMID:15082708]. Effect labelled agonist.","molecular_requirements":"Not reported in our evidence beyond Deltex1 acting downstream [PMID:15082708].","affinity_potency":[],"species_and_systems":"Progenitor and oligodendrocyte cultures; species labelled human by the curator, but the abstract does not name the species [PMID:15082708].","localisation_and_range":"CNTN6 is annotated non-secreted and NOTCH1 transmembrane [flag].","caveats":"Abstract-only; direct physical binding of CNTN6 to NOTCH1 is not shown in our evidence. This is a non-canonical Notch ligand claim from a single study [PMID:15082708]. The pair is ortholog-inferred in both species.","key_references":[{"PMID":"15082708","why":"NB-3 activating Notch signalling in oligodendrocyte generation"}],"covers":["LR001755","LR005113"]},"LR000316":{"pair":"COL14A1 -> CD44","headline":"A chondroitin/dermatan sulfate CD44 form was identified as a cell-surface receptor for collagen XIV by affinity chromatography and immunoprecipitation.","interaction_type":"direct binding","direction_and_effect":"Cell adhesion to collagen XIV was inhibited by heparin or decorin and by chondroitinase ABC or heparinase III pretreatment; affinity chromatography on collagen XIV-Sepharose yielded a chondroitin/dermatan sulfate proteoglycan identified as a CD44 family member by immunoprecipitation [PMID:8986622]. Effect labelled agonist.","molecular_requirements":"The receptor is a glycosaminoglycan-modified CD44 form of 97-105 kDa after chondroitinase ABC digestion; no detectable integrins in the eluates [PMID:8986622].","affinity_potency":[],"species_and_systems":"Human placental collagen XIV and fibroblast and other cell surface proteins; curator species human [PMID:8986622].","localisation_and_range":"COL14A1 is annotated secreted, CD44 secreted and transmembrane [flag].","caveats":"Abstract-only; the evidence is chromatographic, and the abstract does not report affinity. The BioGRID record is co-purification [DB:BioGRID][PMID:8986622].","key_references":[{"PMID":"8986622","why":"CD44 proteoglycan as cell receptor for collagen XIV"}],"covers":["LR000316","LR003822"]},"LR000325":{"pair":"COL1A1 -> ITGA1","headline":"Integrin alpha1 I domain binds type I collagen with sub-micromolar affinity in one full-text SPR study.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha1 I domain bound fibrillar collagen types I, II and III with similar affinities by surface plasmon resonance [PMID:16043429]. Effect on signalling: not reported in our evidence.","molecular_requirements":"Only the isolated alpha1 I domain was tested; the beta1 partner was not part of the assay [PMID:16043429]. Type I collagen was the assembled heterotrimer, not COL1A1 alone.","affinity_potency":[{"value":"KD1 ~0.15-0.32 uM","assay":"surface plasmon resonance (BIAcore), alpha1I binding to fibrillar collagens, high-affinity class","system":"recombinant integrin alpha1 I domain, purified fibrillar collagen","cite":"PMID:16043429"},{"value":"KD2 ~5.5-7.3 uM","assay":"surface plasmon resonance, lower-affinity class","system":"recombinant integrin alpha1 I domain, purified fibrillar collagen","cite":"PMID:16043429"}],"species_and_systems":"Human recombinant proteins [PMID:16043429].","localisation_and_range":"Receptor is a membrane integrin; collagen is matrix.","caveats":"Isolated I domain, not the full receptor. The paper's focus is a binding site in collagen III.","key_references":[{"PMID":"16043429","why":"SPR binding of integrin I-domains to collagens I-III"}],"covers":["LR000325","LR003831"]},"LR000334":{"pair":"COL1A2 -> ITGB1","headline":"Integrin alpha11beta1 binds collagen type I-Sepharose in one abstract-read paper; evidence is for the heterodimer and the collagen heterotrimer, not the single chains.","interaction_type":"direct binding","direction_and_effect":"The alpha(11)beta(1) integrin heterodimer bound collagen type I-Sepharose, and muscle cells localised alpha11beta1 into focal contacts on collagen I [PMID:10464311]. Direction is collagen to integrin; the dossier carries a 'Stimulatory' modulatory label [flag].","molecular_requirements":"The binder is the alpha11beta1 heterodimer and the ligand is the collagen I heterotrimer (2x COL1A1 + COL1A2), per the curator note; this resource records them by chain. ITGB1 alone, and COL1A2 alone, are not shown to be sufficient [PMID:10464311].","affinity_potency":[],"species_and_systems":"Human fetal muscle cells and cDNA cloning per the abstract; the binding result's species is not stated in our evidence. Both the human and mouse pair are ortholog-inferred (not directly tested) [PMID:10464311].","localisation_and_range":"ITGB1 is flagged not secreted [flag]; collagen is a secreted matrix ligand, so contact-dependent signalling (inferred from flags).","caveats":"Abstract read only. The paper's main subject is cloning of the alpha11 chain. Three further papers were abstract-insufficient and one is pending; only one confirmed paper is visible. Mouse rows are projected from human.","key_references":[{"PMID":"10464311","why":"alpha11beta1 binds collagen I-Sepharose"}],"covers":["LR000334","LR003840"]},"LR010612":{"pair":"COL2A1 -> MAG","headline":"Soluble MAG binds collagens including type II in a 1987 solid-phase assay; promiscuous matrix binding rather than a selective pair.","interaction_type":"direct binding","direction_and_effect":"Soluble MAG binds several collagens (types G, I, II, III, IV, V, VI, IX); binding of 125I-MAG to collagen G was inhibited by unlabeled MAG and collagen G but not heat-denatured collagen [PMID:2446864]. Effect not reported in our evidence.","molecular_requirements":"Both soluble and detergent-solubilised MAG forms bind heparin; blockers include heparan sulfate, heparin and dextran sulfate [PMID:2446864].","affinity_potency":[],"species_and_systems":"Adult mouse brain MAG with purified collagens [PMID:2446864]; the curator records ligand species as human.","localisation_and_range":"MAG is flagged secreted and receptor [flag]; binding is solid-phase.","caveats":"Abstract read only. Kd values (5.7 X 10(-8) M for type IX, 2.0 X 10(-7) for type IV) are not for type II. Whole-collagen assay cannot resolve the COL2A1 chain; MAG binds heparin and many collagens, so this looks like matrix binding. BioGRID: Reconstituted Complex [DB:BioGRID].","key_references":[{"PMID":"2446864","why":"MAG solid-phase binding to collagens"}],"covers":["LR010612"]},"LR000343":{"pair":"COL3A1 -> ITGB1","headline":"Support for collagen III with ITGB1 is indirect: alpha2beta1 loss in COL3A1-mutant fibroblasts; chain-only entity.","interaction_type":"functional only","direction_and_effect":"Fibroblasts from patients with COL3A1 mutations show defective matrix and high reduction of the alpha2beta1 integrin, named as the functional receptor; treating with COLLIII restored the control phenotype [PMID:14970208].","molecular_requirements":"The paper concerns the alpha2beta1 heterodimer; ITGB1 alone is not shown to be sufficient [PMID:14970208].","affinity_potency":[],"species_and_systems":"Human EDS dermal fibroblasts [PMID:14970208]; mouse pair projected.","localisation_and_range":"ITGB1 flagged not secreted [flag].","caveats":"Abstract read only. Patient genetics rather than binding; a second confirmed paper is counted but not shown.","key_references":[{"PMID":"14970208","why":"COL3A1-mutant fibroblasts lose alpha2beta1"}],"covers":["LR000343","LR003849"]},"LR002422":{"pair":"COL5A3 -> DDR1","headline":"COL5A3-DDR1 binding reported in one 2026 TNBC paper; the 1997 DDR paper does not test it.","interaction_type":"direct binding","direction_and_effect":"A direct binding between DDR1 and COL5A3 was reported in MDA-MB-231 cells, with a DDR1/FAK/PI3K/AKT pathway [PMID:42310796]. The 1997 paper never tests COL5A3 [PMID:9659900].","molecular_requirements":"Not reported in our evidence beyond DDR1 as the receptor.","affinity_potency":[],"species_and_systems":"Human triple-negative breast cancer cell line MDA-MB-231 [PMID:42310796].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Single cell-line paper; the 1997 judged row is pair_absent; another review-only row. No affinity reported.","key_references":[{"PMID":"42310796","why":"COL5A3 binds DDR1 in TNBC cells"}],"covers":["LR002422","LR005701"]},"LR000361":{"pair":"COL5A3 -> SDC3","headline":"Likely mis-assigned: syndecan-3 binds the alpha4(V) chain, not COL5A3.","interaction_type":"direct binding","direction_and_effect":"Syndecan-3 was isolated using the alpha4(V) N-terminal domain, supporting Schwann cell adhesion [PMID:11751872].","molecular_requirements":"Binding depends on a heparin-binding region of alpha4(V)-NTD not present in other type V collagen NTDs [PMID:11751872].","affinity_potency":[{"value":"IC50 ~30 ng/ml","assay":"heparin inhibition of Schwann cell adhesion","system":"rat Schwann cells on alpha4(V)-NTD","cite":"PMID:11751872"}],"species_and_systems":"Rat Schwann cells [PMID:11751872]; other species are projections.","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"The chain tested is alpha4(V), not COL5A3; abstract only.","key_references":[{"PMID":"11751872","why":"Schwann cell syndecan-3 binds alpha4(V) NTD"}],"covers":["LR000361","LR003867"]},"LR002431":{"pair":"COMP -> CD36","headline":"COMP acts through CD36 to drive liver cancer cell proliferation and metastasis; functional evidence only, no binding shown.","interaction_type":"functional only","direction_and_effect":"Recombinant COMP increased HCC cell proliferation, invasion and migration; CD36 knockdown attenuated these effects and abrogated rCOMP-induced P-ERK and P-AKT upregulation, so CD36 is essential for COMP-driven MEK/ERK and PI3K/AKT signalling (agonist-like effect) [PMID:30231922].","molecular_requirements":"No co-receptor or subunit requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HCC cell lines (Hep-3B, SMMC-7721), nude-mouse orthotopic tumour model and patient sera; hepatic stellate cell (LX2) COMP was knocked down to show a paracrine source [PMID:30231922].","localisation_and_range":"COMP carries a secreted flag [flag]; the paper reports COMP secreted by hepatic stellate cells acting on HCC cells (paracrine) [PMID:30231922].","caveats":"Evidence is CD36 knockdown, not binding; physical COMP-CD36 binding is not shown, and the authors say further studies are needed. One paper.","key_references":[{"PMID":"30231922","why":"CD36 knockdown blocks rCOMP effects in HCC cells and in vivo"}],"covers":["LR002431","LR005710"]},"LR000370":{"pair":"CORT -> SSTR4","headline":"Cortistatin binds SSTR4 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 9.67","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst4 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 8.600000381469727-8.800000190734863","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:9650799"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR4 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. BioGRID also lists the pair [DB:BioGRID].","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000370","LR003876"]},"LR002440":{"pair":"CRP -> CR1","headline":"CRP complexes bind erythrocyte CR1 in a complement-dependent manner; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Complement-mediated binding of CRP-containing complexes to human erythrocyte CR1 (CD35) was found, similar to IgG complexes [PMID:8906746].","molecular_requirements":"Binding required complement; C4A- or C4B-deficient serum also supported CRP/IgG complex binding [PMID:8906746]. Direct CRP-CR1 binding is not shown.","affinity_potency":[],"species_and_systems":"Human erythrocytes and PC-conjugated BSA complexes [PMID:8906746].","localisation_and_range":"CRP is flagged secreted and CR1 a receptor [flag].","caveats":"Single paper read as abstract only. Binding is complement-mediated, so CR1 likely engages complement fragments on the complex, not CRP directly.","key_references":[{"PMID":"8906746","why":"Complement-dependent binding of CRP complexes to CR1"}],"covers":["LR002440"]},"LR005122":{"pair":"CX3CL1 -> ITGAV","headline":"Direct, high-affinity binding of the CX3CL1 chemokine domain to integrin alphavbeta3, supported by two papers from one group plus database records.","interaction_type":"direct binding","direction_and_effect":"FKN-CD directly bound alpha(v)beta(3) at K(D) of 3.0 \u00d7 10(-10) M in 1 mM Mn(2+) [PMID:23125415]. FKN-CD activated recombinant soluble alphavbeta3 in cell-free conditions and on CX3CR1-negative K562 and CHO cells, whereas the integrin-binding-defective mutant K36E/R37E did not, so activation can occur without CX3CR1 [PMID:24789099]. UniProt lists ITGAV:ITGB3 as a co-receptor in CX3CR1-dependent signalling [DB:UniProt].","molecular_requirements":"The functional unit is alphav with beta3 (alphavbeta3). A ternary complex of integrin, FKN-CD and CX3CR1 is critical for CX3CR1 signalling and integrin activation; a docked second site (site 2) is proposed for CX3CR1-independent activation [PMID:24789099]. Mutations K36E/R37E reduce integrin binding while the CX3CR1-binding residue R47A did not [PMID:23125415].","affinity_potency":[{"value":"Kd 0.3 nM","assay":"direct binding, ELISA-type; reported as K(D) 3.0 \u00d7 10(-10) M, 1 mM Mn(2+)","system":"human FKN-CD with recombinant soluble alphavbeta3","cite":"PMID:23125415"}],"species_and_systems":"Human ligand and human receptor; recombinant proteins, K562 and CHO transfectants, U937 cells. Mouse pair ortholog-inferred. IntAct lists co-IP, ELISA and pull-down records [DB:IntAct].","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; paper reports membrane-bound fractalkine also bound alpha(v)beta(3) [PMID:23125415].","caveats":"Both papers come from the same research group and the key binding result rests on recombinant protein; docking models guide the site assignments. Authors say the result contradicts earlier work [PMID:23125415]. In one text passage, a blocking antibody and cyclic RGDfV did not effectively block adhesion (data not shown) [PMID:23125415].","key_references":[{"PMID":"23125415","why":"Direct binding with sub-nanomolar K(D) and co-receptor model"},{"PMID":"24789099","why":"CX3CR1-independent integrin activation by FKN-CD"}],"covers":["LR001764","LR005122"]},"LR000406":{"pair":"CXCL1 -> CXCR1","headline":"Conflicting evidence: CXCL1 binds CXCR1 with low affinity and weak potency in human transfectants, while some papers call CXCR1 selective for IL-8 only.","interaction_type":"conflicting","direction_and_effect":"GRO alpha bound CXCR1-transfected Jurkat cells with low affinity and induced chemotaxis, but IL-8 was 300 to 1,000-fold more potent than GRO alpha or NAP-2 at IL-8R1 [PMID:8137938]. In HEK293 cells GRO alpha and related chemokines competed only weakly at IL8RA [PMID:8702798]. A paper stating IL-8RA is selective only for IL-8 was recorded as an explicit negative [PMID:8550564].","molecular_requirements":"Not reported in our evidence beyond single-receptor transfectants.","affinity_potency":[{"value":"Kd approximately 450 nM","assay":"MGSA (GRO alpha) binding","system":"IL-8R-A in mammalian cells","cite":"PMID:1379593"},{"value":"Kd 200-500 nM","assay":"radioligand binding","system":"IL-8R1-transfected Jurkat cells","cite":"PMID:8137938"},{"value":"pKi>8","assay":"[125I]-IL-8 displacement; reported for GROalpha at CXCR1","system":"recombinant CHO cells","cite":"PMID:10188995"}],"species_and_systems":"Human ligand and human receptor throughout, in transfected HEK293, Jurkat and CHO cells.","localisation_and_range":"CXCL1 secreted chemokine and CXCR1 transmembrane receptor [flag].","caveats":"Affinity values disagree across papers: CHO study gives pKi>8 for GROalpha at CXCR1 but Kd values of about 450 nM and 200-500 nM are reported elsewhere. One curated row stores 350.0 nM, which does not appear in the abstract. All papers read as abstract only. A CXCR1 selectivity-for-IL-8 negative also exists [PMID:8550564]. Several judged rows (abstract-insufficient, review-only, pending) are not shown.","key_references":[{"PMID":"1379593","why":"Early Kd comparison of CXCR1 vs CXCR2 for MGSA"},{"PMID":"8137938","why":"Low-affinity binding plus chemotaxis at IL-8R1"},{"PMID":"10188995","why":"pKi at CXCR1 in CHO cells"}],"covers":["LR000406"]},"LR000415":{"pair":"CXCL5 -> ACKR1","headline":"Direct binding of CXCL5 to the atypical receptor ACKR1/DARC in competition assays; scavenger-type binding, not signalling.","interaction_type":"direct binding","direction_and_effect":"DARC selectively bound pro-inflammatory chemokines including CXCL5 but not lymphoid chemokines; bound CCL2 failed to raise calcium, suggesting DARC down-regulates chemokine activity (scavenger/decoy-type) [PMID:13679391].","molecular_requirements":"ACKR1 alone was used; no co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"Ki 28.8 nM","assay":"125I-CXCL8 competition displacement","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human ligand and receptor; competition binding with 20 chemokines [PMID:13679391]; human erythrocytes [PMID:15358176]. Knockout mice showed no lymph node changes [PMID:13679391].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"The Ki value is attributed to this pair by the curator from the paper's Table 1, which is not in the excerpts shown. ACKR1 does not signal, so it should not be scored as a signalling receptor. Ortholog mouse pair is projected, not tested.","key_references":[{"PMID":"13679391","why":"CXCL5 binds DARC in competitive binding"},{"PMID":"15358176","why":"Ki for CXCL5 at Duffy antigen"}],"covers":["LR000415","LR005745"]},"LR005131":{"pair":"DCN -> TLR2","headline":"Decorin acts as a TLR2/TLR4 ligand in macrophages in one paper; functional evidence with a pull-down in HEK cells.","interaction_type":"functional only","direction_and_effect":"Decorin activated MAPKs p44/p42 and p38 and increased TNFalpha and IL-12p70 release in a TLR2- and TLR4-dependent manner in macrophages [PMID:22087031].","molecular_requirements":"TLR2 and TLR4 both implicated; dependence on co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse macrophages (Dcn+/+ and Il10-/- backgrounds), septic and tumour mouse models; HEK cells stably expressing TLR2 or TLR4 for binding [PMID:22087031].","localisation_and_range":"Decorin flagged secreted; TLR2 flagged receptor [flag]. Soluble paracrine ligand.","caveats":"Single paper, abstract plus excerpts; the excerpt on pull-down is truncated and no affinity is reported. The same paper supports TLR4 [PMID:22087031].","key_references":[{"PMID":"22087031","why":"Decorin as endogenous TLR2/TLR4 ligand"}],"covers":["LR001774","LR005131"]},"LR000433":{"pair":"DEFB4A -> TLR4","headline":"Weak: one abstract showing murine beta-defensin 2 acts as a TLR4 ligand; human pair is projected from mouse.","interaction_type":"functional only","direction_and_effect":"Murine beta-defensin 2 acted directly on immature dendritic cells as an endogenous TLR4 ligand and induced costimulatory-molecule upregulation and maturation [PMID:12411706].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments were in mouse (mouse ligand, mouse dendritic cells); the human pair is inferred by orthology [PMID:12411706].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Abstract only, no binding data. Human relevance is not tested in our evidence. A contested area (LPS contamination) is not addressed in the dossier.","key_references":[{"PMID":"12411706","why":"Murine beta-defensin 2 as TLR4 ligand"}],"covers":["LR000433"]},"LR000442":{"pair":"DKK1 -> LRP5","headline":"No curator-verified paper; support is database records and UniProt statements only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states LRP5 interacts via beta-propeller regions 3 and 4 with DKK1, and DKK1 interacts via its C-terminal Cys-rich domain with LRP5 [DB:UniProt]. BioGRID records co-localization and IntAct records coimmunoprecipitation and tandem affinity purification [DB:BioGRID] [DB:IntAct].","molecular_requirements":"UniProt notes LRP5 complexed with KREMEN2 increases DKK1 effects [DB:UniProt]; other details not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"DKK1 flagged secreted; LRP5 flagged receptor and transmembrane [flag].","caveats":"Judged papers were two different-entity rows, two review-only and one abstract-insufficient; none confirms the pair. Co-localization is a weak assay.","key_references":[],"covers":["LR000442","LR003934"]},"LR008110":{"pair":"DKK4 -> KREMEN2:LRP6","headline":"Krm2 co-operates with Dkk4 to inhibit Wnt/LRP6 signalling in one abstract-read paper.","interaction_type":"functional only","direction_and_effect":"Krm2 co-operates with Dkk4 to inhibit Wnt signalling in human 293 fibroblasts in the Wnt/LRP6 context; Dkk3 does not [PMID:12527209].","molecular_requirements":"Complex of Dkk4 with Krm2 and LRP6 is not directly shown; Krm2 binds Dkks via the second cysteine-rich domain [PMID:12527209].","affinity_potency":[],"species_and_systems":"Human 293 fibroblasts [PMID:12527209].","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only read; functional co-operation only, no binding or stoichiometry data. Single paper.","key_references":[{"PMID":"12527209","why":"Krm2 co-operates with Dkk4 in Wnt inhibition"}],"covers":["LR008110"]},"LR000451":{"pair":"DLL4 -> NOTCH1","headline":"Well-supported membrane-bound agonist pair with several functional papers and Reactome complexes; no binding affinity in our evidence.","interaction_type":"functional only","direction_and_effect":"DLL4 acts as an agonist of NOTCH1: Dll4 overexpression in human endothelial cells induces HEY2 and is reversed by a gamma-secretase inhibitor [PMID:16219802]. DLL4 preferentially activates NOTCH1 over NOTCH2 [PMID:30289388]; without Fringes, DLL4-NOTCH1 activation was more than twice that of DLL4-NOTCH2 [PMID:32820046].","molecular_requirements":"Ectodomain selectivity lies in the region between the N-terminus and EGF repeat three [PMID:30289388]. Fringe enzymes modulate activity ligand-specifically [PMID:32820046]. Reactome lists a DLL4:NOTCH1 plasma-membrane complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human cell assays (HUVECs, co-culture) [PMID:16219802][PMID:32820046]; mouse retroviral bone-marrow model [PMID:11739188]; both human and mouse records exist.","localisation_and_range":"Both partners are annotated transmembrane and DLL4 not secreted [flag], consistent with contact-dependent signalling.","caveats":"All papers read as abstracts. The mouse leukaemia paper only hedges that Dll4-Notch1 interaction 'may provide key signals' and shows an overexpression phenotype, so it is weak for this pair [PMID:11739188]. Downstream effect in endothelium can be inhibitory for VEGF-A responses [PMID:16219802].","key_references":[{"PMID":"30289388","why":"DLL4 vs DLL1 selectivity for NOTCH1/NOTCH2"},{"PMID":"32820046","why":"DLL/JAG x NOTCH1/NOTCH2 and Fringe effects"},{"PMID":"16219802","why":"Dll4 as Notch ligand in human endothelial cells"}],"covers":["LR000451","LR003943"]},"LR005140":{"pair":"DSC1 -> DSG2","headline":"Heterophilic DSC1-DSG2 binding supported by a family-wide study and database records.","interaction_type":"direct binding","direction_and_effect":"Dsg and Dsc ectodomains form heterophilic adhesive dimers across the family, with affinities characteristic of each pair, including DSC1:DSG2 [PMID:27298358]. BioGRID lists reconstituted complex and affinity capture-Western for DSC1-DSG2 [DB:BioGRID]; IntAct lists a solid phase assay [DB:IntAct].","molecular_requirements":"Strand-swap binding; Dsg2 and Dsc1 crystal structures were solved separately [PMID:27298358].","affinity_potency":[],"species_and_systems":"Human ectodomains; mouse record is ortholog-inferred [PMID:27298358].","localisation_and_range":"Both annotated transmembrane [flag]; trans-cellular adhesion [PMID:27298358].","caveats":"Abstract read only; no pair-specific affinity in our evidence. One of 25 companion rows from a single paper.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc binding and structures"}],"covers":["LR001784","LR005140"]},"LR002503":{"pair":"DSG3 -> DSC1","headline":"DSG3 -> DSC1: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358].","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR002503","LR005771"]},"LR000460":{"pair":"EDN1 -> EDNRA","headline":"Well supported: ET-1 binds and activates ETA (EDNRA), shown by binding, displacement and functional assays.","interaction_type":"direct binding","direction_and_effect":"ET-1 acts as agonist at ETA: radioligand binding in human cells [PMID:10770212], 125I-ET-1 displacement on cloned ETAR in COS cells [PMID:8440682], constriction in human vessels [PMID:7647976], and secretion in rat adrenal [PMID:9082970].","molecular_requirements":"ET-1 binds both ETA and ETB, whereas ET-3 prefers ETB; ETA is blocked by BQ-123 [PMID:9082970][PMID:8440682]. A single receptor chain is involved.","affinity_potency":[{"value":"EC50 5.7 nM","assay":"vessel constriction dose-response (stated for ET-2 as equipotent with ET-1)","system":"human coronary artery","cite":"PMID:7647976"},{"value":"pIC50 7.8-8.5","assay":"GtoPdb affinity","system":"not reported","cite":"DB:GtoPdb"}],"species_and_systems":"Human cells and vessels; cloned receptor in COS cells; the adrenal study used rat tissue; the mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond ET-1 being a ligand for GPCRs [DB:UniProt].","caveats":"All papers abstract only. ETA site density 16,500 sites/cell in FNC-B4 cells [PMID:10770212]; the EC50 is given for ET-2 in comparison with ET-1.","key_references":[{"PMID":"10770212","why":"Radioligand binding to ETA in human cells"},{"PMID":"8440682","why":"125I-ET-1 displacement on cloned ETAR"},{"PMID":"7647976","why":"Human vessel pharmacology via ETA"}],"covers":["LR000460","LR003951"]},"LR009001":{"pair":"EFEMP2 -> PLSCR4","headline":"Database-only: a two-hybrid pooling physical association; no ligand-receptor evidence.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper evidence. The only record is an IntAct physical association by two hybrid pooling (EBI-753682) [DB:IntAct]. Direction and effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human yeast two-hybrid pooling record [PMID:16189514] via [DB:IntAct]; no other system reported.","localisation_and_range":"Not reported in our evidence; no localisation flags for the ligand.","caveats":"Rests on one high-throughput two-hybrid record, which does not establish that PLSCR4 is a receptor for EFEMP2. No papers were judged for this pair.","key_references":[],"covers":["LR009001"]},"LR002521":{"pair":"EFNA5 -> ADAM10","headline":"ADAM10 cleaves ephrin-A5 within an ephrin-A5/EphA3 complex; a protease-substrate relation, not a classic ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"ADAM10 constitutively associates with EphA3; the functional EphA3/ephrin-A5 complex creates a new recognition motif for the ADAM10 cysteine-rich domain, enabling ephrin-A5 cleavage in trans [PMID:16239146]. UniProt describes a ternary EFNA5-EPHA3-ADAM10 complex mediating shedding [DB:UniProt].","molecular_requirements":"Needs EphA3 bound to ephrin-A5; ADAM10 disintegrin and cysteine-rich domains are the recognition module [PMID:16239146].","affinity_potency":[],"species_and_systems":"Mouse system per the curator record [PMID:16239146]; human pair listed, mouse is ortholog-inferred.","localisation_and_range":"EFNA5 flagged membrane-bound; ADAM10 flagged receptor but not secreted [flag]. Cleavage occurs in trans across opposing cells [PMID:16239146].","caveats":"Interaction is mediated through EphA3, not a direct EFNA5-ADAM10 binding result in our evidence. Three other judged rows were a different entity. Read as an abstract only.","key_references":[{"PMID":"16239146","why":"ADAM10 recognises the ephrin-A5/EphA3 complex and cleaves ephrin-A5"}],"covers":["LR002521","LR005789"]},"LR000505":{"pair":"EFNA5 -> EPHA7","headline":"Ephrin-A5 binds EphA7 in rat striatum and by ELISA; direct binding evidence.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A2, ephrin-A3 and ephrin-A5 bind EphA7 but not EphA4 in rat striatal tissue [PMID:10366629]. Ephrin-A5 Fc binds most EphA receptors with high apparent affinity [PMID:22568954].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat striatal lysates [PMID:10366629]; ELISA, species unspecified [PMID:22568954]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA5 flagged membrane-bound; EPHA7 flagged secreted and transmembrane [flag].","caveats":"10366629 was an abstract-only read; 22568954 a browser read with unverifiable quote. BioGRID and IntAct records exist [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"10366629","why":"Ephrin-A5 binds EphA7 in rat striatum"},{"PMID":"22568954","why":"ELISA across EphA receptors"}],"covers":["LR000505","LR003996"]},"LR000514":{"pair":"EFNB1 -> ERBB2","headline":"Co-immunoprecipitation shows EphrinB1 and ErbB2 in a complex in breast cancer cells; this is not ligand-receptor binding evidence.","interaction_type":"functional only","direction_and_effect":"EphrinB1 interacts with ErbB2 by co-immunoprecipitation and colocalisation; the oncogenic V660E ErbB2 mutation enhances this, and Src mediates EphrinB1 phosphorylation [PMID:22279592]. No activating or inhibiting effect on ErbB2 was reported.","molecular_requirements":"Part of an ErbB2-Src-EphrinB1 complex regulated by PTPN13 [PMID:22279592].","affinity_potency":[],"species_and_systems":"Breast cancer cells; species not reported in our evidence [PMID:22279592]. IntAct has anti-bait co-IP records [DB:IntAct].","localisation_and_range":"EphrinB1 is annotated non-secreted, transmembrane [flag]; ErbB2 is a transmembrane receptor [flag].","caveats":"Co-IP does not show direct binding or ligand function. Abstract only; the full-text excerpts concern a gene-expression dataset and do not bear on this pair [PMID:22279592].","key_references":[{"PMID":"22279592","why":"EphrinB1-ErbB2 co-IP in breast cancer cells"}],"covers":["LR000514","LR004005"]},"LR004006":{"pair":"EFNB2 -> EPHA3","headline":"Old cloning paper reports LERK-5 (ephrin-B2) as a ligand for hek and elk with receptor phosphorylation; BioGRID lists reconstituted complexes.","interaction_type":"direct binding","direction_and_effect":"LERK-5 is a ligand for both elk and hek and induces receptor phosphorylation [PMID:8559144]. Annotated stimulatory.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and murine LERK-5 cDNAs were isolated (97% amino acid identity) [PMID:8559144]. Pair listed for human and mouse, both ortholog-inferred. BioGRID: reconstituted complex [DB:BioGRID].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine). The receptor is also flagged secreted [flag].","caveats":"Abstract only; no affinity. The hek/elk to EPHA3/EPHB1 mapping is curator-made; the same sentence supports two pairs. Another judged paper was abstract_insufficient.","key_references":[{"PMID":"8559144","why":"LERK-5 cloned as ligand for hek and elk"}],"covers":["LR000515","LR004006"]},"LR004015":{"pair":"Efnb2 -> Grm5","headline":"Weak: co-IP with mGlu5 in striatum only; the functional effect was not mGlu5-dependent and no physical interaction was found.","interaction_type":"conflicting","direction_and_effect":"Co-immunoprecipitation of ephrinB2 with mGlu1a (all brain regions tested) and with mGlu5 (corpus striatum) in brain tissue [PMID:15745950]. Clustered EphB1 acting on ephrinB2 amplified mGlu-receptor-stimulated PI hydrolysis in striatal slices [PMID:15745950]. The effect was not affected by pharmacological blockade of mGlu5 receptors [PMID:15745950].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse brain (corpus striatum co-IP), HEK293 for FRET [PMID:15745950]. Pair is ortholog-inferred in mouse.","localisation_and_range":"Ephrin-B2 is annotated non-secreted [flag]; range is cell-local.","caveats":"FRET and coclustering excluded a physical interaction between ephrinB2 and mGlu5 [PMID:15745950]. Abstract only; same paper as Grm1 pair.","key_references":[{"PMID":"15745950","why":"Co-IP of ephrinB2 with mGlu5 but no direct interaction"}],"covers":["LR004015"]},"LR000532":{"pair":"EGF -> ERBB2","headline":"No direct EGF-ERBB2 interaction is supported by curated papers; the only paper examined argues against it for native EGF.","interaction_type":"conflicting","direction_and_effect":"Wild-type EGF gains affinity for ErbB-2/ErbB-3 heterodimers only after its N-terminal linear region is replaced by NRG-1 or TGF-alpha sequences [PMID:12093292].","molecular_requirements":"Not reported in our evidence beyond engineered variants.","affinity_potency":[],"species_and_systems":"Human cells and phage-display variants [PMID:12093292]. PDB 8HGO (EM) shows an EGF-bound EGFR/HER2 ectodomain complex [DB:PDB 8HGO]. Reactome lists EGF:EGFR:ERBB2 complexes [DB:Reactome].","localisation_and_range":"EGF is secreted and ERBB2 is transmembrane [flag].","caveats":"Both judged rows are pair_absent. Database support (BioGRID reconstituted complex, PDB, Reactome) concerns receptor heterodimers with EGFR and does not show EGF binding ERBB2 itself in our evidence [DB:BioGRID].","key_references":[{"PMID":"12093292","why":"Evidence against native EGF binding ErbB-2/ErbB-3"}],"covers":["LR000532","LR004023"]},"LR004024":{"pair":"EGF -> ERBB3","headline":"Native EGF does not bind ERBB3 alone in our evidence; the paper judged is evidence against.","interaction_type":"conflicting","direction_and_effect":"EGF gains high affinity for ErbB-2/ErbB-3 only after N-terminal replacement by NRG-1 or TGF-alpha sequences, and such chimeras weakly bind ErbB-3 alone [PMID:12093292].","molecular_requirements":"ErbB-3 alone is not enough for wild-type EGF; ErbB-2/ErbB-3 heterodimers are involved only with engineered variants [PMID:12093292].","affinity_potency":[],"species_and_systems":"Human cells and phage-display variants [PMID:12093292].","localisation_and_range":"EGF is secreted and ERBB3 is transmembrane [flag].","caveats":"Two pair_absent rows, plus 4 abstract_insufficient and 2 review_only rows not shown. The BioGRID record rests on the same paper that curators judged as negative [DB:BioGRID].","key_references":[{"PMID":"12093292","why":"Native EGF does not bind ErbB-3; engineered variants do"}],"covers":["LR000533","LR004024"]},"LR001801":{"pair":"ENAM -> CD63","headline":"Enamelin binds the CD63 extracellular region (residues 103-205) in one abstract-only paper; direct binding, thinly supported.","interaction_type":"direct binding","direction_and_effect":"Enamelin interacts with the CD63 region of residues 103-205, as do amelogenin and ameloblastin; the paper proposes this mediates endocytosis of secreted enamel matrix proteins [PMID:17708745]. Agonist/antagonist effect: not reported in our evidence.","molecular_requirements":"CD63 residues 103-205 (predicted within the EC2 domain) are the binding region [PMID:17708745]. Co-receptors or subunits: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor are recorded as the experiment species [PMID:17708745]; the mouse pair is ortholog-inferred. The abstract does not state the assay system.","localisation_and_range":"ENAM is flagged secreted and CD63 as a receptor [flag]; the paper describes secreted matrix proteins meeting membrane-bound CD63 at ameloblast secretory surfaces [PMID:17708745].","caveats":"One paper, read as abstract only; the abstract is mostly about amelogenin and mentions enamelin briefly. No affinity data. CD63 is a membrane protein with an endocytic role rather than a classical signalling receptor.","key_references":[{"PMID":"17708745","why":"Maps CD63 103-205 interaction with enamel matrix proteins including enamelin"}],"covers":["LR001801","LR005157"]},"LR002530":{"pair":"EPHA1 -> EFNA1","headline":"EPHA1-EFNA1 rests on UniProt statements only; no curator-verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA1 binds EPHA1 with high affinity and calls it the probable cognate ligand, while EFNA1 'also binds with low affinity to EPHA1' in another entry [DB:UniProt]. These two UniProt statements disagree on affinity.","molecular_requirements":"Subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"EPHA1 is flagged non-secreted transmembrane; EFNA1 is flagged both secreted and transmembrane [flag], which is inconsistent. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows, no verified primary paper. Affinity claims conflict within UniProt.","key_references":[],"covers":["LR002530","LR005798"]},"LR002602":{"pair":"EPHB6 -> EPHA2","headline":"Receptor-receptor heterodimerisation of EPHB6 with EPHA2 in breast cancer cells, abstract only; not a classical ligand-receptor binding.","interaction_type":"functional only","direction_and_effect":"The paper reports that EPHB6, a kinase-deficient receptor, interacts with EPHA2 in mammalian cells (first A-type/B-type Eph heterodimer reported), and proposes that EPHB6 suppresses tumour invasiveness by sequestering kinase-sufficient oncogenic EPH receptors [PMID:21737611]. The curator labels this antagonist. EPHB6 does not interact with EPHA10 [PMID:21737611].","molecular_requirements":"Not reported beyond the two partners; EPHB6 is described as kinase-deficient [PMID:21737611].","affinity_potency":[],"species_and_systems":"Human breast carcinoma cell lines, mammalian cell co-expression; abstract only [PMID:21737611].","localisation_and_range":"EPHB6 carries secreted and transmembrane flags; EPHA2 is transmembrane-flagged [flag]. Heterodimerisation is within the membrane (cis or on the same cell); range is not reported.","caveats":"Abstract-only reading. This is a receptor-receptor association, so a ligand-to-receptor direction is not shown. The BioGRID record is Affinity Capture-Western [DB:BioGRID 3496524]. Direct physical binding is not distinguished from complex formation in our evidence.","key_references":[{"PMID":"21737611","why":"EPHB6 heterodimerises with EPHA2 in breast carcinoma cell lines."}],"covers":["LR002602","LR005870"]},"LR000541":{"pair":"F13A1 -> ITGA4","headline":"Factor XIII supports alpha4beta1-mediated MOLT-3 cell adhesion; functional evidence only.","interaction_type":"functional only","direction_and_effect":"MOLT-3 cell adhesion to FXIII was mediated by alpha4beta1 and blocked by anti-alpha4 antibody [PMID:10816592].","molecular_requirements":"Evidence is for alpha4beta1 (ITGA4 with ITGB1); alpha4 alone not tested separately in our evidence.","affinity_potency":[],"species_and_systems":"Human cells; MOLT-3 lymphocyte-like leukemia [PMID:10816592].","localisation_and_range":"FXIII flagged secreted; adhesion to substrate-bound protein [flag].","caveats":"Cell-adhesion plus blocking antibody, not purified binding. No affinity.","key_references":[{"PMID":"10816592","why":"FXIII is an alpha4beta1 and alpha9beta1 ligand in adhesion assays"}],"covers":["LR000541","LR004032"]},"LR004033":{"pair":"F13A1 -> ITGA9","headline":"Factor XIII A subunit supports alpha9beta1-mediated cell adhesion in transfected SW480 cells; functional evidence.","interaction_type":"functional only","direction_and_effect":"SW480 cells expressing alpha9beta1, but not mock cells, adhered to FXIII [PMID:10816592]; the authors identify FXIII as a shared ligand for alpha9beta1 and alpha4beta1 [PMID:10816592].","molecular_requirements":"Integrin alpha9beta1 pair is needed; alpha9 alone not tested separately.","affinity_potency":[],"species_and_systems":"Human SW480 transfectants and G-361 melanoma cells [PMID:10816592].","localisation_and_range":"FXIII flagged secreted [flag].","caveats":"Adhesion assay only; no purified binding or affinity.","key_references":[{"PMID":"10816592","why":"FXIII adhesion via alpha9beta1"}],"covers":["LR000542","LR004033"]},"LR000550":{"pair":"F8 -> ASGR2","headline":"Factor VIII binds ASGPR (Kd about 2 nM); ASGR2 specifically is supported by a heterodimer-level SPR paper and a genetics abstract.","interaction_type":"direct binding","direction_and_effect":"FVIII bound ASGPR dose-dependently with high affinity [PMID:15946216]. A second paper states ASGPR binds FVIII with high affinity and links ASGR2 5'UTR haplotypes to FVIII distribution in haemophilia A patients; its abstract is truncated [PMID:34407556].","molecular_requirements":"Only the FVIII heavy chain bound, via B-domain elements, with calcium dependence and glycan dependence [PMID:15946216]. ASGR2 is described as the minor subunit of ASGPR in curator notes, so ASGR1 may also be needed.","affinity_potency":[{"value":"Kd approximately 2 nM","assay":"surface plasmon resonance","system":"FVIII with ASGPR","cite":"PMID:15946216"}],"species_and_systems":"SPR and mouse clearance [PMID:15946216]; patient pharmacokinetic study [PMID:34407556].","localisation_and_range":"Localisation: not reported in our evidence.","caveats":"Both papers are abstract-only; the 2022 abstract is truncated and gives no binding data of its own. Neither isolates ASGR2 from the heterodimer.","key_references":[{"PMID":"15946216","why":"SPR binding of FVIII to ASGPR, Kd about 2 nM"},{"PMID":"34407556","why":"ASGR2 genetic variation and FVIII pharmacokinetics"}],"covers":["LR000550","LR004041"]},"LR004042":{"pair":"F8 -> LDLR","headline":"The LDLR ligand-binding domain binds FVIII in vitro and LDLR contributes to FVIII clearance in mice.","interaction_type":"direct binding","direction_and_effect":"The extracellular ligand-binding domain of LDLR interacted with FVIII in vitro and binding was inhibited by RAP; in the absence of hepatic LRP, LDLR played a dominant role in FVIII clearance, and adenovirus-mediated LDLR transfer accelerated clearance [PMID:15840700]. This is an endocytic clearance receptor role.","molecular_requirements":"Only the extracellular ligand-binding domain was tested; no co-receptor requirement is reported. The authors propose LDLR acts with LRP [PMID:15840700].","affinity_potency":[],"species_and_systems":"In vitro binding plus mouse models (LDLR and hepatic LRP deficiency) [PMID:15840700].","localisation_and_range":"Endocytic receptor per the abstract; secretion flags: F8 secreted [flag].","caveats":"Single abstract-only paper; no affinity reported. RAP inhibition is not specific to LDLR.","key_references":[{"PMID":"15840700","why":"LDLR binds FVIII in vitro and affects FVIII clearance in mice"}],"covers":["LR000551","LR004042"]},"LR002611":{"pair":"FAM3B -> FGFR3","headline":"FAM3B is reported as an FGFR ligand in one Xenopus paper; FGFR3-specific evidence is thin.","interaction_type":"functional only","direction_and_effect":"The paper shows FAM3B as an FGFR ligand in Xenopus, with ERK activation via FGFR1 [PMID:33975953]. Purified human FAM3B was incubated with Fc-tagged human FGFR1-4 ectodomains, with FGFR3-Ecto-Fc one of the panels; the excerpts do not show the FGFR3 result itself [PMID:33975953].","molecular_requirements":"FGFR1 kinase-inactive mutant with intact ectodomain still bound FAM3B; no co-receptor requirement reported [PMID:33975953]. Whether FGFR3 acts alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus embryos, HEK293T cells and recombinant human FAM3B; curation row labels species human [PMID:33975953].","localisation_and_range":"FAM3B is secreted [flag] and detected in HEK293T medium [PMID:33975953].","caveats":"Single paper. The abstract does not say which of FGFR1-4 binds; all four rows rest on a family-level claim, and the main system is Xenopus [PMID:33975953]. No affinity reported. FGF family paralog overlap is possible.","key_references":[{"PMID":"33975953","why":"FAM3B binds FGFR ectodomain and activates ERK in Xenopus/HEK293T"}],"covers":["LR002611","LR005878"]},"LR004051":{"pair":"FBN1 -> ITGB1","headline":"Fibrillin-1 acts through beta1 integrins (alpha5 beta1) in endothelial cells; one abstract-level functional paper.","interaction_type":"functional only","direction_and_effect":"Microfibrils and fibrillin-1 fragments induced integrin-mediated signaling in HUVECs; PF14 action was mediated by alpha v beta 3 and alpha 5 beta 1 integrins, and PF14 enhanced proliferation and migration [PMID:20686071]. UniProt says ITGA5:ITGB1 acts as a fibrillin-1 receptor [DB:UniProt].","molecular_requirements":"ITGB1 acts as part of alpha 5 beta 1, not alone [PMID:20686071] [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human umbilical venous endothelial cells, with bovine aortic endothelial cells as confirmation; the mouse pair is ortholog-inferred [PMID:20686071].","localisation_and_range":"FBN1 is flagged secreted, not transmembrane [flag]; microfibrils are extracellular [PMID:20686071].","caveats":"Single paper, abstract only; pathway/inhibition evidence, no direct binding. Affinity not reported in our evidence.","key_references":[{"PMID":"20686071","why":"Fibrillin-1 signaling in endothelial cells via beta1 and beta3 integrins."}],"covers":["LR000560","LR004051"]},"LR001810":{"pair":"FCER2 -> CR2","headline":"Well-supported direct CD23-CD21 (CR2) binding with structural and SPR data and a mapped interaction site.","interaction_type":"direct binding","direction_and_effect":"CD23 binds CD21/CR2 and, through it and IgE, regulates IgE synthesis [PMID:16172256]. Earlier work reported CD23 as a functional ligand for CD21, mapping its site on CD21 [PMID:7515913]; effect labelled agonist by the curator [PMID:7515913]. Soluble CD23 enhances IgE synthesis on binding CD21 (reported as background in full text) [PMID:16172256].","molecular_requirements":"On CR2, the CD23 site lies in SCRs 5-8 with contribution of SCRs 1 and 2, requires N-linked sugar (Asn 370 and 295, not Asn 492) [PMID:7515913]. On CD23, NMR chemical shifts map the CD21 site; CD23 can bind IgE and CD21 simultaneously, and none of the interactions need calcium [PMID:16172256]. UniProt lists CD23 C-terminus binding CR2 Sushi domains 1 and 2 [DB:UniProt].","affinity_potency":[{"value":"KD 0.87 +/- 0.09 x 10-6 M","assay":"surface plasmon resonance, CD21(D1-2) over immobilised derCD23 at low density","system":"recombinant human proteins","cite":"PMID:16172256"}],"species_and_systems":"Human proteins throughout: recombinant CD23 lectin domain and CD21 fragments (SPR, NMR), CD23 liposomes with CD21-transfected K562 cells.","localisation_and_range":"CD23 is flagged secreted and transmembrane; CR2 transmembrane [flag]. Both membrane and soluble CD23 forms are discussed [PMID:16172256].","caveats":"Papers read as abstracts, with excerpts for two. One pending row is not shown. PMID 16785534 only mentions CD23 as a known CR2 ligand and adds no data for this pair. BioGRID and IntAct also list the pair [DB:BioGRID 280615] [DB:IntAct P20023-P06734].","key_references":[{"PMID":"16172256","why":"NMR and SPR: CD23-CD21 binding, KD, simultaneous IgE binding"},{"PMID":"7515913","why":"Mapping of CD23 site on CD21 SCRs 5-8, glycan dependence"}],"covers":["LR001810"]},"LR002620":{"pair":"FCER2 -> ITGB3","headline":"Human CD23 RKC peptides bind alphaVbeta3 by SPR; ITGB3 is one chain of the receptor.","interaction_type":"direct binding","direction_and_effect":"CD23 peptides bind alphaVbeta3 and alphaVbeta5 and stimulate pre-B cell growth and monocyte cytokine release [PMID:22560905]. Labelled agonist.","molecular_requirements":"RKC motif from arg172 required [PMID:22560905]. The evidence is for the alphaVbeta3 heterodimer; beta3 alone is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Human CD23 peptides, purified integrin, human cell lines.","localisation_and_range":"CD23 flagged secreted and transmembrane [flag].","caveats":"Single paper; peptide-based; no affinity reported; chain-level assignment of an alphaVbeta3 result.","key_references":[{"PMID":"22560905","why":"SPR of CD23 RKC peptides with alphaVbeta3"}],"covers":["LR002620"]},"LR008011":{"pair":"FGA:FGB:FGG -> TLR4","headline":"Fibrinogen is proposed as an endogenous TLR4 ligand; functional evidence in pre-eclamptic monocytes plus Reactome and IntAct records.","interaction_type":"functional only","direction_and_effect":"Fibrinogen increased inflammatory cytokine production in monocytes from pre-eclamptic patients; not seen with normotensive monocytes [PMID:24661950].","molecular_requirements":"Not reported in our evidence. Reactome lists cleaved fibrinogen products binding TLR4:LY96 [DB:Reactome]; IntAct has an ELISA record (PMID 29150600) [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human patient monocytes [PMID:24661950].","localisation_and_range":"Ligand complex flagged not secreted [flag]; plasma fibrinogen levels are measured in the paper [PMID:24661950].","caveats":"Abstract only; direct binding is not shown in the paper; TLR4 role is inferred. Fibronectin and heparan sulphate were not elevated.","key_references":[{"PMID":"24661950","why":"fibrinogen-TLR4 axis in PE monocytes"}],"covers":["LR008011"]},"LR004060":{"pair":"FGF16 -> FGFR1","headline":"FGF16 activates FGFR1c-expressing BaF3 cells with high activity; functional evidence from one panel study.","interaction_type":"functional only","direction_and_effect":"FGF9, FGF16 and FGF20 activated FGFRc isoforms and FGFR4 with high activity [PMID:16597617]. Agonist.","molecular_requirements":"Activity is on the c splice form; isoform-specific, so FGFR1c rather than FGFR1b is the relevant receptor [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF16 flagged secreted; FGFR1 a membrane receptor [flag].","caveats":"Single functional paper, read as full text in a browser (quote unverified); activity is mitogenesis in BaF3 cells, not binding. Two other judged rows were review-only.","key_references":[{"PMID":"16597617","why":"BaF3 FGF-FGFR specificity panel"}],"covers":["LR000576","LR004060"]},"LR000613":{"pair":"FGF2 -> GPC4","headline":"Recombinant glypican-4 binds FGF2 through heparan sulfate chains and dampens FGF2 mitogenesis; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant glypican-4 binds FGF2 and suppressed the mitogenic effect of FGF2 on E13 cortical precursor cells, so it acts as an inhibitory modulator rather than a signal-transducing receptor [PMID:11066092]. A BioGRID reconstituted-complex record cites the same paper [DB:BioGRID].","molecular_requirements":"Binding is via glypican-4's heparan sulfate chains [PMID:11066092]. Whether the core protein contributes, or whether FGF receptors are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"FGF2 and glypican-4 expression were studied in rat E13 cortical precursor cultures and developing mouse brain [PMID:11066092]. Human and mouse pairs are ortholog-inferred, not tested directly.","localisation_and_range":"Glypican-4 is described as a GPI-anchored cell-surface proteoglycan, so it is membrane-tethered (juxtacrine/contact) [PMID:11066092]; the entity flags list it as secreted [flag].","caveats":"Single paper, read as abstract only. Its effect is inhibitory, so this is a modulator/co-receptor-type pair, not classical agonism. Affinity not reported.","key_references":[{"PMID":"11066092","why":"Recombinant GPC4 binds FGF2 via HS chains and suppresses FGF2 mitogenic effect"}],"covers":["LR000613","LR004097"]},"LR007201":{"pair":"FGF21 -> FGFR4:KLB","headline":"Database-asserted only: complex record supported by KLB-FGF21 structure and interaction records, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"No papers were judged for this pair; the evidence is database records only. A PDB structure shows beta-Klotho with FGF21 C-terminal region [DB:PDB 5VAQ]. UniProt states that KLB interacts via its C-terminus with FGF21 [DB:UniProt].","molecular_requirements":"Receptor is a complex of FGFR4 and KLB [flag]. The structure involves KLB and FGF21CT, not FGFR4 [DB:PDB 5VAQ]. FGFR4 contribution is not shown in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a surface plasmon resonance record between the KLB and FGF21 proteins [DB:IntAct]; species not reported in our evidence.","localisation_and_range":"Complex flagged transmembrane [flag]; localisation otherwise not reported.","caveats":"Supported by databases only; the records concern KLB-FGF21, so they do not by themselves show ligand binding to the FGFR4:KLB complex. One review-only row is not shown.","key_references":[],"covers":["LR007201"]},"LR000604":{"pair":"FGF23 -> FGFR2","headline":"FGF23 binds FGFR2c in several studies (SPR, mitogenesis, cell binding); functional and binding evidence.","interaction_type":"direct binding","direction_and_effect":"FGF23 binds and activates c isoforms of FGFR1-3 and FGFR4 but not b isoforms [PMID:16081635, PMID:16597617]. A separate study reports FGF-23 binding FGFR-2c but not FGFR-1c (data not shown) [PMID:12032146].","molecular_requirements":"c splice forms required; highly sulfated GAGs promote activity [PMID:16081635].","affinity_potency":[],"species_and_systems":"Human reagents per curators [PMID:16081635]; the 2002 binding result is a receptor extracellular domain assay with species not stated [PMID:12032146].","localisation_and_range":"Not reported beyond flags; FGF23 secreted [flag].","caveats":"The FGFR2 binding sentence in PMID 12032146 is 'data not shown'; it also contradicts FGFR1c binding reported elsewhere [PMID:12032146, PMID:16081635]. PMID 16081635 read as abstract only.","key_references":[{"PMID":"16081635","why":"SPR and mitogenesis for FGF23 on c isoforms"},{"PMID":"12032146","why":"FGF-23 binds FGFR-2c"},{"PMID":"16597617","why":"BaF3 screen"}],"covers":["LR000604","LR004088"]},"LR004105":{"pair":"FGF4 -> FGFR1","headline":"FGF4 binds and activates FGFR1 IIIc, not IIIb; evidence includes crystal structure of FGF4 and database records.","interaction_type":"direct binding","direction_and_effect":"FGF4 binds and activates the IIIc splice forms of FGFR1-3 with little activity toward IIIb forms or FGFR4 [PMID:11486033].","molecular_requirements":"IIIc isoform required; heparin contacts are involved in a modelled ternary FGF4-FGFR1-heparin complex [PMID:11486033].","affinity_potency":[],"species_and_systems":"Human FGF4 crystal structure at 1.8 A with mutagenesis [PMID:11486033]. BioGRID lists a reconstituted complex and IntAct an SPR record [DB:BioGRID, DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The ternary complex is modelled, not solved. Abstract-only reading. Several other rows not shown.","key_references":[{"PMID":"11486033","why":"FGF4 structure and FGFR IIIc specificity"}],"covers":["LR000621","LR004105"]},"LR000622":{"pair":"FGF4 -> FGFR2","headline":"FGF4 activates FGFR2 IIIc, not IIIb, in mitogenic screens; structural and functional evidence.","interaction_type":"functional only","direction_and_effect":"FGF4 binds and activates IIIc forms of FGFR1-3 [PMID:11486033]; FGFs 4, 5, 6 and 8 specifically activate c receptor splice forms in BaF3 cells [PMID:8663044]. Stimulatory.","molecular_requirements":"IIIc isoform; heparin as cofactor [PMID:11486033].","affinity_potency":[],"species_and_systems":"Human FGF4 structure [PMID:11486033]; BaF3 species unspecified [PMID:8663044]. IntAct lists an SPR record [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The structural paper's FGFR2-specific assignment is medium confidence per curators [PMID:11486033]. Abstract-only readings.","key_references":[{"PMID":"11486033","why":"FGF4 structure"},{"PMID":"8663044","why":"BaF3 mitogenic screen"}],"covers":["LR000622","LR004106"]},"LR004114":{"pair":"FGF6 -> FGFR1","headline":"Supported mainly by BaF3 survey and database records; no direct binding paper in our evidence.","interaction_type":"functional only","direction_and_effect":"The BaF3 survey states FGFs 4, 5, 6 and 8 specifically activate c receptor splice forms [PMID:8663044].","molecular_requirements":"c splice-form selectivity is described [PMID:8663044]. UniProt-listed FGFR1 interactions include FGF6 in vitro [DB:UniProt]; IntAct records a surface plasmon resonance interaction [DB:IntAct]; BioGRID has a protein-peptide record [DB:BioGRID].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Only one paper (abstract only; browser-read quote pending spot-check) and the quoted sentence does not name FGFR1. Database records rest on assays whose details are not in our dossier.","key_references":[{"PMID":"8663044","why":"BaF3 survey, FGF6 activates c splice forms"}],"covers":["LR000630","LR004114"]},"LR000631":{"pair":"FGF6 -> FGFR2","headline":"Weakly supported by one BaF3 survey and database records; FGFR2-specific data are not shown.","interaction_type":"functional only","direction_and_effect":"The pair is annotated stimulatory. The BaF3 survey states FGFs 4, 5, 6 and 8 specifically activate c receptor splice forms [PMID:8663044].","molecular_requirements":"c splice-form selectivity is described [PMID:8663044]. Reactome and BioGRID records exist [DB:Reactome][DB:BioGRID]; the Reactome example concerns FGFR2b mutants binding an expanded ligand range, not FGF6 specifically [DB:Reactome].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"One abstract-only paper with browser-read quote pending spot-check; no direct binding data; database records are generic.","key_references":[{"PMID":"8663044","why":"BaF3 survey, FGF6 activates c splice forms"}],"covers":["LR000631","LR004115"]},"LR004123":{"pair":"FGF8 -> FGFR3","headline":"FGF8 binds FGFR3 well in a soluble-receptor assay and activates FGFR3c in BaF3 cells.","interaction_type":"direct binding","direction_and_effect":"Soluble FGFR3 bound FGF8 and FGF9 well but FGF2 poorly [PMID:10574949]. FGF8 subfamily members activated FGFRs 1c, 2c and 3c in BaF3 cells [PMID:16597617].","molecular_requirements":"A broad region spanning Ig domain II and N-terminal sequences determines FGF8/FGF9 binding specificity to chimeric receptors [PMID:10574949]. c splice form is responsive [PMID:16597617].","affinity_potency":[],"species_and_systems":"Soluble human FGFR3 binding domain with chimeric receptors, abstract only [PMID:10574949]; BaF3 cells with unspecified species [PMID:16597617][PMID:8663044]. BioGRID affinity capture-Western and IntAct surface plasmon resonance records exist [DB:BioGRID][DB:IntAct]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"No affinity value is reported. In the same study, soluble FGFR1 bound FGF8 poorly [PMID:10574949], showing receptor-specific differences. BaF3 quotes are browser-read and pending spot-check.","key_references":[{"PMID":"10574949","why":"FGFR3 binds FGF8 well; chimeric mapping"},{"PMID":"16597617","why":"FGF8 subfamily activates FGFR3c"}],"covers":["LR000639","LR004123"]},"LR000640":{"pair":"FGF8 -> FGFR4","headline":"FGF8 binds immobilised FGFR4 ectodomain and activates FGFR4 (4\u0394) in BaF3; binding not seen in solution.","interaction_type":"direct binding","direction_and_effect":"Immobilised recombinant human FGFR4 extracellular domain bound FGF-8 [PMID:10736564]. FGF8 subfamily members activated the two Ig-like domain form of FGFR4 (4\u0394) in BaF3 cells [PMID:16597617].","molecular_requirements":"FGFR4 shows strong dependence on heparin-like material for activation [PMID:10736564]. A two Ig-like domain form of FGFR4 was the responsive form [PMID:16597617].","affinity_potency":[],"species_and_systems":"Insect-cell-expressed human FGFR4 ectodomain on a biosensor chip, abstract only [PMID:10736564]; BaF3 cells with unspecified species [PMID:16597617][PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"FGF-8 binding was seen only with immobilised receptor, not in solution [PMID:10736564]. No affinity is reported. The PMID:8663044 sentence concerns c splice forms and does not name FGFR4.","key_references":[{"PMID":"10736564","why":"FGF-8 binds immobilised FGFR4 ectodomain"},{"PMID":"16597617","why":"FGF8 subfamily activates FGFR4 (4\u0394)"}],"covers":["LR000640","LR004124"]},"LR007210":{"pair":"FLRT3:TENM4 -> ADGRL1","headline":"Only a by-similarity UniProt statement supports this pair; no papers or structures, and nothing about TENM4.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states the FLRT3 entry interacts via its extracellular domain with ADGRL1/LPHN1 and LPHN2 via their olfactomedin-like domain, by similarity [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"The ligand is the FLRT3:TENM4 complex; the only record concerns FLRT3 and ADGRL1 and says nothing of TENM4 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt statement is explicitly by similarity [DB:UniProt].","localisation_and_range":"FLRT3 is flagged secreted and transmembrane, TENM4 transmembrane [flag].","caveats":"No curated paper (2 pending). The single database record is inferred by similarity and does not involve TENM4.","key_references":[{"PMID":"26235030","why":"cited by UniProt for the FLRT3-latrophilin olfactomedin interaction (not read as a curated paper)"}],"covers":["LR007210"]},"LR004141":{"pair":"FN1 -> ITGA2B","headline":"Fibronectin binding to the alphaIIb integrin subunit is supported by two papers, but evidence concerns the alphaIIbbeta3 heterodimer.","interaction_type":"direct binding","direction_and_effect":"A fibronectin C-terminal heparin-binding peptide (residues Ala1704-Glu1718) bound directly to alphaIIbbeta3 and inhibited fibronectin fragment binding to thrombin-stimulated platelets [PMID:8663002]. In mouse trophoblast, adhesion to fibronectin was inhibited by a function-blocking anti-alphaIIb antibody [PMID:15031111]. Agonist/adhesion.","molecular_requirements":"Both papers concern the alphaIIbbeta3 heterodimer; alphaIIb alone is not tested separately in our evidence. RGDS peptide did not inhibit binding of the 29-kDa fragment [PMID:8663002].","affinity_potency":[],"species_and_systems":"Human platelets and human fibronectin fragment [PMID:8663002]; mouse blastocyst trophoblast with human FN substrates [PMID:15031111]; mouse pair is orthology-inferred.","localisation_and_range":"FN1 flagged secreted, ITGA2B flagged receptor [flag]; matrix-to-cell contact.","caveats":"The 1996 paper is listed as abstract-level; BioGRID and Reactome records support alphaIIbbeta3 binding fibronectin [DB:BioGRID] [DB:Reactome]. 3 further papers were abstract-insufficient.","key_references":[{"PMID":"8663002","why":"non-RGD fibronectin site binds alphaIIbbeta3"},{"PMID":"15031111","why":"alphaIIb function-blocking antibody inhibits trophoblast adhesion to FN"}],"covers":["LR000657","LR004141"]},"LR004150":{"pair":"FN1 -> ITGB6","headline":"Fibronectin binds integrin alphavbeta6 in one affinity-chromatography study.","interaction_type":"direct binding","direction_and_effect":"alphavbeta6 from human carcinoma cell lysates bound immobilized fibronectin but not vitronectin or collagen I, and was eluted by an RGD peptide, so it acts as an RGD-dependent fibronectin receptor [PMID:1532572].","molecular_requirements":"The binding entity is the alphav-beta6 heterodimer [PMID:1532572].","affinity_potency":[],"species_and_systems":"Human pancreatic carcinoma FG-2 cell lysates [PMID:1532572]. Mouse pair is projected by orthology.","localisation_and_range":"Fibronectin is flagged secreted [flag]; matrix ligand for a cell-surface integrin (inferred).","caveats":"Single paper read as abstract only; affinity not reported in our evidence. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","key_references":[{"PMID":"1532572","why":"alphavbeta6 as RGD-dependent fibronectin-binding protein"}],"covers":["LR000666","LR004150"]},"LR012115":{"pair":"FST -> INHA:INHBB","headline":"Database-level only: follistatin and INHBB (activin B subunit); inhibin-complex role not shown.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records follistatin binding activin [DB:Reactome R-HSA-2473184]; UniProt notes INHBB interacts with FST and FSTL3 [DB:UniProt]. Inhibitory flag [flag].","molecular_requirements":"A structure PDB 9Z3T pairs a chain of P19883 (FST) with P09529 (INHBB) [DB:PDB 9Z3T]. INHA contribution not reported in our evidence.","affinity_potency":[],"species_and_systems":"not reported in our evidence.","localisation_and_range":"Receptor-side flagged secreted [flag].","caveats":"No verified papers (two pending). Evidence is for INHBB-containing activin, not INHA:INHBB inhibin B.","key_references":[],"covers":["LR012115"]},"LR011215":{"pair":"GDF10 -> BMPR1B","headline":"Database-asserted only: GtoPdb agonist record; no confirming paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF10 as agonist of BMPR1B [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"No judged papers; screened rows were different-entity or abstract-insufficient. Another paper in this dossier family excludes ALK-2/-3/-6 as mediators of BMP-3b, but does not test this pair directly in our evidence.","key_references":[],"covers":["LR011215"]},"LR000703":{"pair":"GDF6 -> BMPR1B","headline":"GDF6 binds BMPR1B (ALK6) with high affinity and ALK6 confers GDF6 signalling; three concordant papers, two abstract-only.","interaction_type":"direct binding","direction_and_effect":"rhBMP13 (GDF6 alias) bound ALK6 [PMID:21702718]. ALK6 overexpression in COS7 cells conferred GDF6 signalling [PMID:16049014]. CDMP-2 had affinity for BMPR-IB and BMPR-II [PMID:9525338]. Effect is stimulatory (Smad1/5/8).","molecular_requirements":"ALK3 or ALK6 suffices as type I receptor in COS7 [PMID:16049014]; BMPR-IB transduced a signal in the presence of BMPR-II [PMID:9525338].","affinity_potency":[{"value":"KD (kin) 0.5 nM","assay":"Bio-Layer Interferometry, immobilised ALK6-Fc, rhBMP13 (GDF6 alias)","system":"recombinant proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant proteins and C3H10T1/2 cells [PMID:21702718]; COS7 and MC3T3 cells [PMID:16049014]; ATDC5, ROB-C26, MC3T3-E1 [PMID:9525338]. Human pair listed directly; mouse ortholog-inferred. BioGRID reconstituted-complex record [DB:BioGRID].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; range beyond that is not reported in our evidence.","caveats":"PMID:16049014 and PMID:9525338 were read as abstracts only; ligand identity relies on alias names (BMP13, CDMP-2).","key_references":[{"PMID":"21702718","why":"BLI affinity of GDF6 (BMP13) for ALK6"},{"PMID":"16049014","why":"ALK6 overexpression confers GDF6 signalling"},{"PMID":"9525338","why":"CDMP-2 binds BMPR-IB"}],"covers":["LR000703","LR004187"]},"LR011224":{"pair":"GDF9 -> ACVR2B","headline":"GDF9 -> ACVR2B rests on a GtoPdb agonist record alone; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records the interaction as Agonist, action Agonist, with no affinity units [DB:GtoPdb]. No curator-verified paper supports it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Support is a database assertion only. Two papers were abstract-insufficient and one was a different entity.","key_references":[],"covers":["LR011224"]},"LR000712":{"pair":"GDNF -> RET","headline":"Well established, but RET binds GDNF only as a GDNF-GFRA1 complex; low or no affinity for GDNF alone.","interaction_type":"direct binding","direction_and_effect":"GDNF with GFRalpha1 activates RET: Neuro-2a cells expressing GDNFR-alpha showed rapid Ret autophosphorylation [PMID:8674117]; GDNF signalling through Ret was also seen with TrnR2 [PMID:9182803]. UniProt, Reactome and PDB record the interaction [DB:UniProt][DB:Reactome][DB:PDB 4UX8].","molecular_requirements":"GFR alpha co-receptor is required: RETECD has low or no detectable affinity for GDNF or GFR alpha1 alone, and contacts both in the complex via cadherin-like domains 1-3 [PMID:14514671]. GFRA2 can substitute [PMID:9182803]. Score with GFRA1 (or GFRA2) as well as RET.","affinity_potency":[],"species_and_systems":"Human RET mutagenesis in [PMID:14514671]; Neuro-2a cells and rat spinal cord motor neurons in [PMID:8674117]; fibroblasts in [PMID:9182803]. Mouse pair ortholog-inferred.","localisation_and_range":"GDNF is flagged secreted [flag]; RET is the transmembrane signalling receptor.","caveats":"A gene-level GDNF -> RET row hides the co-receptor requirement. No affinity value in our evidence; all papers were read as abstracts except partial full text in [PMID:9182803].","key_references":[{"PMID":"8674117","why":"GDNF with GDNFR-alpha activates Ret"},{"PMID":"14514671","why":"RET ectodomain binds GDNF-GFRa1 complex only"},{"PMID":"9182803","why":"GFRA2 alternative co-receptor for Ret"}],"covers":["LR000712","LR004196"]},"LR007030":{"pair":"GJA3 -> GJA1","headline":"GJA3 - GJA1 rests on database records only; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists an affinity capture-Western record [DB:BioGRID][PMID:11739633]. Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both partners are flagged transmembrane (gap-junction class) [flag].","caveats":"Three papers judged different_entity and one abstract_insufficient; none confirmed.","key_references":[],"covers":["LR007030"]},"LR000721":{"pair":"GNRH2 -> GNRHR","headline":"GnRH II binds and activates the human GnRH receptor, with lower affinity than GnRH I; two abstract-read binding papers confirm.","interaction_type":"direct binding","direction_and_effect":"Agonist, stimulatory [flag]. Human receptor has lower affinity for GnRH II than GnRH I, and GnRH II acts as a partial agonist [PMID:17452338]. Mutating Asn(7.45) converts GnRH II to a full agonist [PMID:17452338]. Mutating Arg38(1.35) to alanine reduced affinity 989-fold for GnRH I and 1268-fold for GnRH II, with decreased inositol phosphate potency [PMID:17942747]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor; Arg38(1.35) at the extracellular end of TM1 is required for high-affinity binding of both endogenous GnRHs [PMID:17942747].","affinity_potency":[],"species_and_systems":"Human receptor and human ligand [PMID:17452338][PMID:17942747]; the exact cells are not reported in our evidence.","localisation_and_range":"GnRH II is annotated as secreted and the receptor as transmembrane [flag].","caveats":"Both papers read as abstracts only. Wild-type affinity values for GnRH II are not given in our abstracts. Conflict in effect: papers say partial agonist [PMID:17452338] while GtoPdb says full agonist [DB:GtoPdb].","key_references":[{"PMID":"17452338","why":"Human receptor: GnRH II lower affinity, partial agonist"},{"PMID":"17942747","why":"Arg38(1.35) mutagenesis and binding of both endogenous GnRHs"}],"covers":["LR000721"]},"LR004204":{"pair":"GPC3 -> CD81","headline":"GPC3 binds CD81 (yeast two-hybrid, co-IP) in liver; two abstract-read papers, with GPC3 binding reducing CD81-Hhex binding.","interaction_type":"direct binding","direction_and_effect":"Antagonist (curator label): GPC3 binding to CD81 lowers CD81-Hhex binding, giving nuclear translocation of Hhex and transcriptional repression [PMID:23665349]. GPC3 interacts with CD81 in yeast two-hybrid, and co-immunoprecipitation validated it [PMID:19574424]. GPC3-CD81 binding decreased at the peak of hepatocyte proliferation [PMID:23665349].","molecular_requirements":"Not reported in our evidence beyond the two partners; Hhex competes for CD81 [PMID:23665349].","affinity_potency":[],"species_and_systems":"Mouse liver regeneration and hepatocytes (partial hepatectomy, GPC3 transgenic mice) [PMID:23665349][PMID:19574424]; curators recorded 'human' for one and 'unspecified' for the other. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"GPC3 is GPI-anchored to the cell surface [PMID:19574424]; GPC3 is annotated non-secreted [flag]. CD81 is a tetraspanin and co-localises with GPC3 in liver [PMID:19574424].","caveats":"Both papers read as abstracts only. Binding was shown by yeast two-hybrid and co-IP, which do not prove direct binding in a ligand-receptor sense. A fourth judged row was 'review_only'. No affinity reported in our evidence.","key_references":[{"PMID":"19574424","why":"Yeast two-hybrid and co-IP of GPC3 with CD81"},{"PMID":"23665349","why":"GPC3-CD81 binding controls Hhex release"}],"covers":["LR000722","LR004204"]},"LR002701":{"pair":"GPC5 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC5 evidence is class-level.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"Evidence is for 'glypican' as a class. GPC5 was detected in the LRRTM4-Fc sample but is not named in the abstract; direct cell-free binding was shown for GPC4 only [PMID:23911103].","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002701","LR005966"]},"LR011026":{"pair":"GREM2 -> BMP2","headline":"Only a UniProt subunit statement supports this pair; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt for BMP2 states it interacts with GREM2 [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; human pair.","localisation_and_range":"BMP2 is flagged as secreted and non-transmembrane [flag]; GREM2 secretion flag is not given in the dossier.","caveats":"No verified papers: the one judged row was a different entity. Rests on a single database record.","key_references":[],"covers":["LR011026"]},"LR000730":{"pair":"GUCA2A -> GUCY2C","headline":"Guanylin activates guanylate cyclase C; supported by original purification and bioassay and by human cell work.","interaction_type":"direct binding","direction_and_effect":"Guanylin stimulates cGMP in T84 cells and displaces heat-stable enterotoxin binding, so it is proposed to act through the same receptor-binding region [PMID:1346555]. In human kidney IHKE-1 cells, guanylin (10-100 nM) depolarised membrane voltage and raised cGMP; GC-C is 'probably the receptor' [PMID:11889121].","molecular_requirements":"Guanylin required disulfide bond formation (oxidation) for bioactivity [PMID:1346555]. Reactome describes a GUCY2C trimer complex with GUCA2A/B [DB:Reactome].","affinity_potency":[],"species_and_systems":"Guanylin was purified from rat jejunum and tested on human T84 cells [PMID:1346555]; human IHKE-1 cells [PMID:11889121]. Mouse pair is ortholog-inferred.","localisation_and_range":"GUCA2A is flagged secreted [flag].","caveats":"Receptor identity in IHKE-1 is inferred from cGMP and GC-C expression, with no knockout; the authors hedge. Both papers read as abstract only.","key_references":[{"PMID":"1346555","why":"Guanylin purification and activation of intestinal cyclase"},{"PMID":"11889121","why":"Guanylin effects in human proximal tubule cells"}],"covers":["LR000730","LR004212"]},"LR002710":{"pair":"HBEGF -> ERBB3","headline":"HB-EGF stimulated ErbB-3-associated PI kinase activity in T47D cells; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Only NDF, HB-EGF and BTC significantly stimulated association of phosphatidylinositol kinase activity with ErbB-3 [PMID:8626392]. All EGF-related factors except amphiregulin induced ErbB-2 tyrosine phosphorylation [PMID:8626392].","molecular_requirements":"Heterodimer formation with other ErbB receptors is likely but not reported in our evidence.","affinity_potency":[],"species_and_systems":"T47D human breast tumour cells [PMID:8626392]. Mouse pair ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond flags [flag].","caveats":"Abstract only; readout is downstream, not binding.","key_references":[{"PMID":"8626392","why":"HB-EGF activates ErbB-3-linked PI kinase in T47D"}],"covers":["LR002710","LR005975"]},"LR004222":{"pair":"HCRT -> HCRTR2","headline":"Orexin-A (HCRT) activates OX2 (HCRTR2); supported by many functional assays in recombinant human cells plus a structure record.","interaction_type":"direct binding","direction_and_effect":"Agonist. Orexin-A stimulates OX2 signalling in CHO and HEK-293 cells: phospholipases A2, C and D, calcium elevation and cAMP effects [PMID:26582739], ERK1/2 and p38 activation [PMID:18599270]. [125I]orexin-A binding was used in the CHO study [PMID:26582739]. Orexin-A and orexin-B are described as near-equipotent at OX2 [PMID:12606634][PMID:12208495]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor. Coupling is promiscuous: Gq/PLC/PKC, Gs and Gi routes contribute to ERK1/2 [PMID:18599270]; cAMP inhibition is pertussis-toxin sensitive [PMID:12890892]. Narcolepsy-associated OX2R mutants severely affect ERK1/2 activation [PMID:18599270]. A PDB entry (7L1U) has chains of O43612 and O43614 [DB:PDB 7L1U]; Reactome has the HCRTR2:HCRT(70-97) complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Recombinant human OX2 in CHO, HEK-293 and nerve-like cells [PMID:26582739][PMID:18599270][PMID:12890892]; the 1998 discovery work used rat brain tissue [PMID:9491897]. The mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag]; no tissue-range data beyond this in our evidence.","caveats":"No affinity value for the OX2 pair is reported in the shown papers. All papers were read as abstracts only. Potency of orexin-B versus orexin-A at OX2 varies by report: one HEK-293 study found orexin-B more potent [PMID:18599270].","key_references":[{"PMID":"9491897","why":"Discovery of orexins as ligands of both receptors"},{"PMID":"26582739","why":"OX2 signalling with orexin-A in CHO cells, including binding"},{"PMID":"12606634","why":"Compares orexin-A and orexin-B at OX1 and OX2"}],"covers":["LR000740","LR004222"]},"LR004231":{"pair":"HSP90B1 -> LRP1","headline":"gp96 (HSP90B1) binds CD91/LRP1 directly in antigen-presenting cells; consistent evidence across papers.","interaction_type":"direct binding","direction_and_effect":"CD91 binds gp96 directly, and alpha2-macroglobulin or anti-CD91 antibodies inhibit re-presentation of gp96-chaperoned peptides by macrophages [PMID:11248808]. The 2001 paper restates direct binding as the result of earlier work and extends CD91 as receptor to other heat shock proteins [PMID:11290339]. The annotated modulatory effect is stimulatory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Antigen-presenting cells and macrophages; species is recorded as human in this dossier, but the same 2001 paper is curated as mouse (RAW264.7 cells) elsewhere [PMID:11290339]. Human pair is ortholog-inferred.","localisation_and_range":"HSP90B1 carries no secreted flag [flag]; the papers treat gp96 as an external chaperone taken up by APCs [PMID:11248808].","caveats":"Direct-binding sentence in the 2001 paper cites earlier work, so the primary evidence is [PMID:11248808] (abstract only). No Kd reported.","key_references":[{"PMID":"11248808","why":"gp96 binds CD91 directly; alpha2-macroglobulin and anti-CD91 block"},{"PMID":"11290339","why":"CD91 as common receptor for gp96, hsp90, hsp70, calreticulin"}],"covers":["LR000772","LR004231"]},"LR004240":{"pair":"IBSP -> ITGAV","headline":"Bone sialoprotein signals through integrin alphaVbeta3 for migration in breast cancer cells; evidence is functional, from one abstract.","interaction_type":"functional only","direction_and_effect":"Integrin-blocking antibodies showed BSP-RGD-induced migration used alpha(v)beta3, whereas adhesion and proliferation were alpha(v)beta5-mediated; effect is stimulatory [PMID:9699501]. UniProt says ITGAV:ITGB3 is a receptor for IBSP promoting adhesion and migration [DB:UniProt]; Reactome lists the complex [DB:Reactome].","molecular_requirements":"The receptor is the ITGAV:ITGB3 heterodimer; ITGAV alone is not shown to bind. The RGD domain of BSP supplied most activity [PMID:9699501].","affinity_potency":[],"species_and_systems":"MDA-MB-231 human breast cancer cells with human BSP fragments and peptides [PMID:9699501]. Mouse pair is ortholog-inferred.","localisation_and_range":"IBSP is described as a secreted glycoprotein of bone matrix [PMID:9699501].","caveats":"Abstract read only. Antibody blocking shows involvement, not direct binding. Same paper also supports ITGB5, so subunit-level assignment is by the integrin pair.","key_references":[{"PMID":"9699501","why":"Blocking-antibody dissection of alphavbeta3 and alphavbeta5 use"}],"covers":["LR000782","LR004240"]},"LR006004":{"pair":"IBSP -> ITGB3","headline":"Integrin beta3 (alphaVbeta3) mediates BSP-RGD-induced migration of breast cancer cells; one abstract plus database records.","interaction_type":"functional only","direction_and_effect":"Blocking antibodies showed BSP-RGD-induced migration used the alpha(v)beta3 vitronectin receptor [PMID:9699501]. UniProt says ITGAV:ITGB3 is a receptor for IBSP promoting adhesion and migration [DB:UniProt].","molecular_requirements":"Receptor is the alphaV/beta3 heterodimer; ITGB3 alone is not shown.","affinity_potency":[],"species_and_systems":"Human MDA-MB-231 breast cancer cells [PMID:9699501]. Mouse pair is ortholog-inferred.","localisation_and_range":"IBSP is flagged secreted [flag].","caveats":"Abstract only; antibody blocking is indirect. One further row was review_only and one abstract_insufficient.","key_references":[{"PMID":"9699501","why":"alpha(v)beta3 used for BSP-RGD-induced migration"}],"covers":["LR002757","LR006004"]},"LR000802":{"pair":"ICAM4 -> ITGB3","headline":"One human transfectant study supports activated alphaIIbbeta3 binding to ICAM-4; human pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Activated alphaIIbbeta3 binds recombinant ICAM-4-Fc specifically and dose dependently, and cell-surface ICAM-4 interacts with cell-surface alphaVbeta3 [PMID:15355350]. UniProt describes ICAM4 as a ligand for ITGA2B:ITGB3 in erythrocyte-platelet adhesion [DB:UniProt].","molecular_requirements":"beta3 pairs with alphaIIb or alphaV; the beta3 binding sites span the first and second Ig-like domains of ICAM-4, with different contact sites per alpha chain [PMID:15355350]. Only the activated alphaIIbbeta3 bound.","affinity_potency":[],"species_and_systems":"Human ICAM-4 and integrin transfectants [PMID:15355350]; no mouse experiments.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"One paper, abstract only. Affinity not reported.","key_references":[{"PMID":"15355350","why":"beta3 integrin specificity and ICAM-4 binding residues"}],"covers":["LR000802","LR004256"]},"LR000811":{"pair":"IFNA17 -> IFNAR1","headline":"IFNA17 binds IFNAR1 only on class-wide evidence from one abstract; the chain is the weak-affinity subunit.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM [PMID:21856167]. GtoPdb lists IFNA17 as an agonist at IFNAR1 [DB:GtoPdb].","molecular_requirements":"IFNAR1 binds about 1000-fold more weakly than IFNAR2 per the curator's reading; IFNAR2 is the tighter chain [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA17. Binding is to the isolated chain, not the functional heterodimer.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000811"]},"LR000820":{"pair":"IFNA4 -> IFNAR2","headline":"IFNA4 binds IFNAR2 on class-wide evidence from one abstract; IFNAR2 is the high-affinity chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR2 at 0.4-5 nM, except IFN-alpha1 at 220 nM [PMID:21856167]. GtoPdb lists IFNA4 as an agonist at IFNAR2 [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tighter-binding chain; IFNAR1 binds at 0.5-5 \u03bcM [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA4. Binding is to the isolated chain.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000820"]},"LR006013":{"pair":"IGF1 -> ITGB3","headline":"Integrin alphavbeta3 directly binds IGF-1 in one verified study; ITGB3 is the beta chain.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 specifically and directly bound IGF-1 in cell adhesion, ELISA-type binding and surface plasmon resonance studies; the R36E/R37E mutant lost integrin binding but kept IGF1R binding, and wild-type IGF-1 mediated an alphavbeta3-IGF1R ternary complex [PMID:19578119].","molecular_requirements":"The alphavbeta3 heterodimer was tested; ITGB3 alone is not shown. UniProt records the ternary complex [DB:UniProt].","affinity_potency":[],"species_and_systems":"Cells and species other than Chinese hamster ovary cell proliferation are not reported in our evidence [PMID:19578119].","localisation_and_range":"IGF1 is flagged secreted [flag].","caveats":"Abstract-only read; no affinity value is reported in our evidence.","key_references":[{"PMID":"19578119","why":"Direct alphavbeta3-IGF-1 binding"}],"covers":["LR002767","LR006013"]},"LR006022":{"pair":"IGFBP7 -> CD93","headline":"A human CD93-IGFBP7 complex structure maps binding to CD93 EGF1 and the IGFBP7 IB domain (preprint abstract).","interaction_type":"direct binding","direction_and_effect":"CD93 acts as a receptor for IGFBP7 on endothelial cells, where the axis mediates angiogenesis and migration; curator effect: agonist [PMID:37333140]. UniProt also describes CD93 as a receptor for IGFBP7 [DB:UniProt].","molecular_requirements":"Binding is between the EGF 1 domain of CD93 and the IB domain of IGFBP7; mutagenesis confirmed the interactions [PMID:37333140]. A structure is deposited [DB:PDB 8IVD].","affinity_potency":[],"species_and_systems":"Human proteins; cellular and mouse tumour studies reported for physiological relevance [PMID:37333140].","localisation_and_range":"IGFBP7 is annotated as secreted and CD93 as transmembrane [flag]; the paper says CD93 protrudes from the cell surface [PMID:37333140].","caveats":"Abstract-only read of a bioRxiv preprint; no affinity reported. The 'agonist' label comes from the curator, and the abstract describes blockade of the axis as favourable.","key_references":[{"PMID":"37333140","why":"Human CD93-IGFBP7 complex structure and mutagenesis"}],"covers":["LR002776","LR006022"]},"LR005203":{"pair":"IGSF11 -> VSIR","headline":"VSIG-3 (IGSF11) binds VISTA (VSIR) in a binding screen and inhibits human T cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"VSIG-3 binds VISTA in a functional ELISA binding screen and not other known B7 family members; no significant VSIG-8-VISTA interaction was seen [PMID:30220083]. VSIG-3 inhibits human T-cell proliferation and reduces IFN-gamma, IL-2, IL-17, CCL5, CCL3 and CXCL11 production; anti-VISTA neutralising antibodies attenuate both the binding and the T-cell inhibition [PMID:30220083]. VISTA acts as a co-inhibitory receptor in this report.","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human T cells and recombinant proteins; ELISA screen [PMID:30220083]. The mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"IGSF11 is flagged non-secreted and VSIR a transmembrane receptor [flag], suggesting membrane-bound contact signalling; the paper does not state this.","caveats":"Abstract only; affinity not reported. A single paper supports this pair. Mouse pair is ortholog-inferred, not tested.","key_references":[{"PMID":"30220083","why":"VSIG-3 binds VISTA and inhibits human T-cell function"}],"covers":["LR001857","LR005203"]},"LR006031":{"pair":"IL17F -> IL17RC","headline":"IL-17F binds IL-17RC, the main IL-17F receptor chain per UniProt; support is one abstract-only SPR paper plus structures.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17F activity was inhibited by soluble IL-17RC [PMID:18684971]. UniProt calls IL17RC the cognate receptor for IL17F and notes IL17F homodimer binding triggers TRAF6 and NF-kappa-B signalling [DB:UniProt]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL17RC acts in a heterodimer with IL17RA, though UniProt notes it can act as cognate receptor for IL17F [DB:UniProt, PMID:18684971]. PDB 6HG4 and 6HG9 are human IL-17RC ECD with IL-17F [DB:PDB 6HG4].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells [PMID:18684971]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-17F annotated as secreted [flag]; IL-17RC as a receptor [flag].","caveats":"Single paper read as abstract only; no affinity values given in the abstract.","key_references":[{"PMID":"18684971","why":"SPR shows comparable binding of IL-17F to IL-17RC; soluble IL-17RC blocks IL-17F"}],"covers":["LR002788","LR006031"]},"LR004303":{"pair":"IL18 -> CD48","headline":"CD48 is reported to associate with the IL-18/IL-18Ralpha complex in human KG-1 cells; direct IL-18 binding to CD48 is not shown.","interaction_type":"functional only","direction_and_effect":"Co-receptor-like role. Anti-IL-18Ralpha antibody co-precipitated CD48 from IL-18-stimulated KG-1 cells, and soluble CD48 without GPI glycan bound IL-18Ralpha [PMID:15760905]. PI-PLC treatment inhibited tyrosine kinase phosphorylation and IL-18-dependent interferon-gamma production [PMID:15760905].","molecular_requirements":"The complex of IL-18, IL-18Ralpha and CD48 is proposed to involve both the CD48 peptide portion and its GPI glycan [PMID:15760905].","affinity_potency":[],"species_and_systems":"Human KG-1 cells and recombinant human CD48 [PMID:15760905]. Mouse pair is ortholog-inferred.","localisation_and_range":"CD48 is GPI-anchored, membrane-bound (annotated transmembrane receptor [flag]) in the paper's system [PMID:15760905].","caveats":"Abstract-only read. The binding shown is between CD48 and IL-18Ralpha, not IL-18 itself; the abstract text is truncated.","key_references":[{"PMID":"15760905","why":"CD48 associates with IL-18Ralpha via peptide and GPI glycan"}],"covers":["LR000873","LR004303"]},"LR007300":{"pair":"IL18 -> IL18R1:IL18RAP","headline":"IL-18 signals through the IL18R1:IL18RAP heterodimer; evidence is functional plus database complexes, with the accessory chain needed for signalling.","interaction_type":"functional only","direction_and_effect":"IL-18 acts as an agonist: both IL-1R-rp1 (IL18R1) and AcPL (IL18RAP) were required for NF-kappaB and JNK activation in response to IL-18, and a dominant negative AcPL inhibited signalling [PMID:9792649]. Reactome lists the IL18:IL18R1:IL18RAP complex [DB:Reactome].","molecular_requirements":"Both chains are needed: IL18R1 binds the cytokine, while AcPL alone did not bind IL-18 with any appreciable affinity [PMID:9792649]. AcPL was not involved in IL-1-induced NF-kappaB activation [PMID:9792649]. UniProt says IL18RAP does not mediate IL18 binding but is involved in signal transduction [DB:UniProt]. A complex-level structure paper is in the IL18/IL18RAP dossier, not here.","affinity_potency":[{"value":"Kd 18.5 nM","assay":"125I-IL-18 binding to IL-1Rrp (IL18R1) alone","system":"human L428 cells","cite":"PMID:9325300"}],"species_and_systems":"Human cDNA transfection and reporter assays in cell lines [PMID:9792649, PMID:9325300].","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers were read as abstracts only. The 1997 paper describes only IL18R1 (IL-1Rrp), not the accessory chain, so it supports the complex indirectly [PMID:9325300]. Three other judged rows were review-only or abstract-insufficient (not shown).","key_references":[{"PMID":"9792649","why":"Both chains required for IL-18 signalling; AcPL does not bind IL-18 alone"},{"PMID":"9325300","why":"IL-18 binding by IL18R1, Kd 18.5 nM"}],"covers":["LR007300"]},"LR004321":{"pair":"IL21 -> IL2RG","headline":"IL-21 directly contacts the common gamma chain by cross-linking; chain-level evidence from one abstract, signalling needs IL-21R too.","interaction_type":"direct binding","direction_and_effect":"Chemical cross-linking shows direct binding of IL-21 to gamma(c) in gamma(c)-transfected cells [PMID:11418623]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"gamma(c) is an indispensable subunit of the IL-21 receptor complex, but IL-21 does not signal in gamma(c)-deficient cells that express IL-21R, so IL2RG acts with IL-21R rather than alone [PMID:11418623].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, transfected cell lines [PMID:11418623]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-21 is flagged secreted [flag].","caveats":"Abstract-only, single paper. IL2RG is a shared chain for other cytokines per the abstract, so this row says little about IL-21 specificity [PMID:11418623]. BioGRID: Affinity Capture-Western [DB:BioGRID].","key_references":[{"PMID":"11418623","why":"cross-linking shows direct IL-21 binding to gamma(c)"}],"covers":["LR000891","LR004321"]},"LR006040":{"pair":"IL25 -> IL17RA","headline":"IL25 -> IL17RA rests only on database records; no verified paper supports it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL25-IL17RA as an agonist [DB:GtoPdb]. UniProt says IL-25 acts through a receptor composed of IL17RA and IL17RB, by similarity [DB:UniProt].","molecular_requirements":"Receptor is a two-chain assembly of IL17RA and IL17RB [DB:UniProt]; IL17RA alone is not shown sufficient.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagging not given beyond secretion absence; not reported in our evidence.","caveats":"No papers judged; two rows were different_entity. UniProt statement is by similarity.","key_references":[],"covers":["LR002797","LR006040"]},"LR004330":{"pair":"IL25 -> IL17RB","headline":"IL-25 is a ligand of IL17RB, supported by database records and one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"IL-17E was identified as a ligand for EVI27/IL-17BR (IL-17Rh1) and induced NF-kappaB activation and IL-8 production [PMID:11058597]. GtoPdb lists IL-25 as an agonist of IL17RB [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence for this single-chain pair beyond the Reactome complex IL25 dimer:IL17RA:IL17RB [DB:Reactome]; the other chain is not tested in this dossier.","affinity_potency":[],"species_and_systems":"Human experiment per the curator record [PMID:11058597]. The mouse interaction is projected from human evidence (ortholog-inferred). BioGRID records a reconstituted complex [DB:BioGRID]; PDB 7UWJ, 7UWK and 7UWL contain both partner chains [DB:PDB 7UWJ].","localisation_and_range":"IL-25 is flagged secreted and non-transmembrane [flag].","caveats":"The only verified paper was read as abstract only, and the abstract asserts ligand status without naming a binding assay or affinity [PMID:11058597]. No affinity is reported in our evidence.","key_references":[{"PMID":"11058597","why":"Identifies IL-17E (IL-25) as ligand for IL-17BR; NF-kappaB and IL-8 readouts."}],"covers":["LR000900","LR004330"]},"LR000901":{"pair":"IL26 -> IL20RA","headline":"IL20RA (IL-20R1) is the expression-limiting chain of the IL-26 receptor; evidence is complex-level and functional.","interaction_type":"functional only","direction_and_effect":"IL-26 signals through a heterodimer containing IL-20R1; STAT1 and STAT3 activation is blocked by neutralising antibody to IL-20R1 (agonist) [PMID:14764663].","molecular_requirements":"IL-20R1 requires IL-10R2 as partner. IL-10R2 is broadly expressed whereas few tissues express IL-20R1, so IL-26 responsiveness is restricted by IL-20R1 expression [PMID:14764663]. The evidence is for the heterodimer, not IL-20R1 alone.","affinity_potency":[],"species_and_systems":"Human [PMID:14764663].","localisation_and_range":"IL-26 is flagged secreted and non-transmembrane [flag].","caveats":"One paper, abstract only; no binding assay or affinity. The row inherits complex-level evidence (IL10RB:IL20RA) [PMID:14764663]. No database records for this exact pair in our evidence.","key_references":[{"PMID":"14764663","why":"IL-20R1 expression limits IL-26 responsiveness; antibody blockade."}],"covers":["LR000901"]},"LR000910":{"pair":"IL3 -> IL3RA","headline":"IL-3 binds the IL3RA chain, shown by SPR and heterodimerization work in abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"Native IL-3 and substitution variants were measured binding IL-3R alpha by SPR; E43N and F113Y showed >100-fold slower association, and the kinetic differences were reflected in STAT5 phosphorylation [PMID:11700046]. IL-3 induced IL-3R alpha/beta c heterodimerization (agonist) [PMID:8649415]. GtoPdb lists IL-3 as an agonist [DB:GtoPdb].","molecular_requirements":"IL3RA binds IL-3 alone in SPR [PMID:11700046]; the second chain beta c is needed for activation by the heterodimer [PMID:8649415]. UniProt describes a receptor of IL3RA plus a signal-transducing IL3RB subunit [DB:UniProt P08700].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; recombinant IL-3R alpha in SPR and human cells [PMID:11700046][PMID:8649415].","localisation_and_range":"IL-3 is flagged secreted and non-transmembrane [flag].","caveats":"Both papers were read as abstract only. No equilibrium Kd for IL-3 binding IL3RA is given in the abstracts for this pair, and the SPR data are variant kinetics. For CCC scoring the active receptor also needs the beta chain. One further paper was abstract_insufficient.","key_references":[{"PMID":"11700046","why":"SPR kinetics of IL-3 variants binding IL-3R alpha."},{"PMID":"8649415","why":"IL-3 induces alpha/beta c heterodimerization."}],"covers":["LR000910"]},"LR002800":{"pair":"IL33 -> IL1RAP","headline":"IL1RAP is the co-receptor of the IL-33/ST2 complex, not a stand-alone IL-33 receptor; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"IL33 binds a complex of ST2L and IL1RAcP (IL1RAP), and IL33 stimulated proliferation and migration of human pancreatic myofibroblasts [PMID:19996325]. GtoPdb lists IL33-IL1RAP as agonist [DB:GtoPdb].","molecular_requirements":"UniProt describes a 1:1:1 heterotrimeric complex of IL33 with its primary high-affinity receptor IL1RL1 and the coreceptor IL1RAP [DB:UniProt O95760], and IL1RAP interacts with IL-33-bound IL1RL1 [DB:UniProt Q9NPH3]. Reactome lists IL33:IL1RL1 binding IL1RAP [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human pancreatic myofibroblasts from chronic pancreatitis tissue [PMID:19996325].","localisation_and_range":"IL1RAP is flagged both secreted and transmembrane, and IL33 secreted [flag].","caveats":"Abstract only. IL1RAP is a co-receptor that engages after IL33 binds IL1RL1; no direct IL33-IL1RAP binding is shown in our evidence [PMID:19996325]. Treat the IL1RAP:IL1RL1 complex as the functional unit. One further paper was abstract_insufficient.","key_references":[{"PMID":"19996325","why":"IL33, ST2L and IL1RAcP expressed together in human pancreatic myofibroblasts; IL33 stimulates them."}],"covers":["LR002800","LR006042"]},"LR005212":{"pair":"JAG1 -> CD46","headline":"Jagged1 binds CD46 directly (NMR, SPR) and acts on human T cells; one full-text paper supports it.","interaction_type":"direct binding","direction_and_effect":"Jagged1 bound CD46 but not soluble CR1, and bound cell-surface CD46 on red blood cells from human-CD46 transgenic mice [PMID:23086448]. Disturbing CD46-Notch crosstalk impeded IFN-gamma induction and the switch to IL-10; CD4+ T cells from CD46-deficient and Alagille-syndrome (JAG1 hypomorph) patients failed to mount proper TH1 responses [PMID:23086448]. The curator labels the effect agonist [PMID:23086448].","molecular_requirements":"The two N-terminal CD46 domains were fully competent for Jagged1 binding; the Jagged1 DSL-EGF3 region was used [PMID:23086448]. It did not bind murine Crry [PMID:23086448].","affinity_potency":[{"value":"KD about 8 uM","assay":"SPR, J-1DSL-EGF3 to truncated CD46","system":"recombinant proteins","cite":"PMID:23086448"}],"species_and_systems":"Human recombinant proteins and human T cells; transgenic mouse red blood cells for cell-surface binding [PMID:23086448]. The mouse pair is ortholog-inferred.","localisation_and_range":"JAG1 is flagged as transmembrane, not secreted [flag]; IntAct also records NMR, SPR and solid-phase assays [DB:IntAct].","caveats":"Single primary paper; the curator row was read from the abstract, though full-text excerpts were available. Affinity is modest (micromolar).","key_references":[{"PMID":"23086448","why":"Binding, SPR/NMR and patient T-cell data"}],"covers":["LR001867","LR005212"]},"LR010702":{"pair":"KRTAP4-12 -> CLDN2","headline":"Only a yeast two-hybrid IntAct record; no evidence that this is a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a two-hybrid physical association from a large-scale screen; species and system not reported in our evidence [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The only judged paper was review_only, so no curator-verified evidence exists. A two-hybrid hit does not show a ligand-receptor relationship, and KRTAP4-12 is a keratin-associated protein, so this is likely a screening artefact.","key_references":[],"covers":["LR010702"]},"LR010801":{"pair":"LAMA1 -> ITGA9:ITGB1","headline":"No curator-confirmed paper; only a BioGRID ITGB1 record is linked to this complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Only a BioGRID reconstituted-complex record (LAMA1 with ITGB1) is available [DB:BioGRID].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Judged rows were abstract_insufficient or a different entity. The BioGRID record concerns ITGB1 only, via a paper whose abstract names alpha1beta1 and alpha2beta1 [DB:BioGRID 315221].","key_references":[],"covers":["LR010801"]},"LR004402":{"pair":"LAMA1 -> ITGB4","headline":"Alpha6beta4 is reported as a receptor for laminin isoforms including laminin 1; abstract-only, heterotrimer-level.","interaction_type":"direct binding","direction_and_effect":"Radioligand-binding and cell-adhesion assays showed alpha6beta4 is a receptor for several laminin isoforms including laminin 1 [PMID:7721947]. Alpha6beta4-positive cells attach to and roll on laminin under flow [PMID:7699012].","molecular_requirements":"The receptor is the alpha6beta4 heterodimer; laminin fragment E8 supported attachment [PMID:7699012].","affinity_potency":[],"species_and_systems":"804G bladder epithelial cells (the curator infers rat) with laminin of unstated origin [PMID:7721947]; cell lines in a flow assay [PMID:7699012].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand.","caveats":"Both papers are abstract-only and concern the laminin-1 heterotrimer rather than LAMA1; species is ambiguous. Two review-only rows and one abstract_insufficient row are not shown.","key_references":[{"PMID":"7721947","why":"Radioligand binding of alpha6beta4 to laminin 1"},{"PMID":"7699012","why":"Dynamic adhesion to laminin via alpha6beta4"}],"covers":["LR000981","LR004402"]},"LR011152":{"pair":"LAMA4 -> CD44","headline":"Only a computational inference from tumour scRNA-seq/spatial data; no binding or functional test of this pair.","interaction_type":"functional only","direction_and_effect":"A multiomics cell-communication analysis in colorectal cancer suggested fibroblast-to-tumour-cell signalling via a LAMA4-CD44 axis that could promote liver metastasis [PMID:40473111]. Interaction record lists a Stimulatory effect [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human colorectal cancer single-cell and spatial transcriptome data [PMID:40473111].","localisation_and_range":"LAMA4 flagged secreted; CD44 flagged transmembrane [flag].","caveats":"Computational prediction read from the abstract only, with no experimental validation of this pair in our evidence.","key_references":[{"PMID":"40473111","why":"Inferred LAMA4-CD44 axis in CRC liver metastasis"}],"covers":["LR011152"]},"LR004411":{"pair":"LAMA4 -> ITGAV","headline":"Recombinant laminin alpha4 G domain binds integrin alphavbeta3 with high affinity; abstract-level read.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 integrin bound with high affinity to recombinant G(919-1207) of laminin alpha4, and anti-alphavbeta3 antibodies inhibited endothelial attachment to it [PMID:12454288]. Stimulatory per interaction record [flag].","molecular_requirements":"Receptor tested is the alphavbeta3 heterodimer; ligand is a G-domain fragment [PMID:12454288].","affinity_potency":[{"value":"half-maximal at 1.4 nM","assay":"endothelial cell adhesion to G(919-1207) (adhesion, not Kd)","system":"endothelial cells","cite":"PMID:12454288"}],"species_and_systems":"Endothelial cells and recombinant protein; mouse-human chimeric angiogenesis model mentioned for the antibody [PMID:12454288].","localisation_and_range":"LAMA4 flagged secreted [flag]; vessel basement membrane component [PMID:12454288].","caveats":"Abstract only; no binding Kd given. One further paper was review-only.","key_references":[{"PMID":"12454288","why":"alphavbeta3 binds alpha4 G domain"}],"covers":["LR000992","LR004411"]},"LR004420":{"pair":"LAMB1 -> ITGA7","headline":"Laminin beta1-containing laminins bind integrin alpha7beta1; recombinant Kd 0.64 nM plus melanoma and myoblast studies.","interaction_type":"direct binding","direction_and_effect":"Laminin-211/221 bound recombinant alpha7X1beta1 [PMID:16413178]. Alpha7beta1 was purified from melanoma cells by laminin affinity chromatography and binds laminin with high affinity [PMID:1839357]. Alpha7beta1 is the major laminin-binding integrin of muscle and mediates myoblast migration on laminin-1 and -2 [PMID:11278916]. Annotated stimulatory.","molecular_requirements":"Heterotrimeric laminin and the alpha7beta1 heterodimer; the alpha7 splice variants differ in laminin preference [PMID:16413178]. Individual chains such as LAMB1 were not tested alone.","affinity_potency":[{"value":"Kd 0.64 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-211/221 vs alpha7X1beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; human and murine melanoma cells [PMID:1839357]; human-labelled myoblasts and HEK293 transfection [PMID:11278916]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA7 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Laminin-211/221 and laminin-1/-2 are tested, so LAMB1 is one of three chains. Two papers are abstract-only reads; the Kd is for the alpha7X1 variant with beta1.","key_references":[{"PMID":"16413178","why":"Kd of alpha7X1beta1 for laminin-211/221"},{"PMID":"1839357","why":"Alpha7beta1 purified from melanoma by laminin affinity"},{"PMID":"11278916","why":"Alpha7beta1 mediates myoblast migration on laminin"}],"covers":["LR001001","LR004420"]},"LR011125":{"pair":"LAMB2 -> ITGA6:ITGB4","headline":"Database structure record only for LAMB2 with the ITGA6:ITGB4 complex; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"Only a PDB structure record supports this pair; direction and effect are not reported in our evidence.","molecular_requirements":"The record shows a structure with chains of P11047 and P23229 [DB:PDB 7CEC]; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"Complex is flagged transmembrane and ligand secreted [flag]; range is not otherwise reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Three papers were judged abstract_insufficient. The PDB entry lists only a P11047 chain and a P23229 chain, not an ITGB4 chain.","key_references":[],"covers":["LR011125"]},"LR011080":{"pair":"LAMB2 -> ITGA9:ITGB1","headline":"No paper verifies LAMB2 with ITGA9:ITGB1; support is a PDB record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"PDB record shows a structure with chains of P11047 and P05556 [DB:PDB 7CEC]; subunit requirements are not reported.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Two papers were abstract_insufficient. The PDB entry lists no ITGA9 chain.","key_references":[],"covers":["LR011080"]},"LR006103":{"pair":"LAMB2 -> ITGB1","headline":"LAMB2 (in laminin-511/521) binds integrin beta1 (as alpha3beta1) at low nM Kd; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521, which contains LAMB2, bound recombinant integrin ectodomain in solid-phase saturation binding [PMID:16413178]. Annotated effect is Stimulatory [flag]. Direction: laminin to integrin.","molecular_requirements":"The beta1 chain was tested as part of an alpha-beta heterodimer (the 3.4 nM value is in the alpha3beta1 column of the table), not alone; the ligand is the whole heterotrimer [PMID:16413178]. PDB 7CEC lists chains of P11047 and P05556 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha3beta1 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain and with an alpha-beta heterodimer, so a beta1-chain-specific contribution is not separated.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-511/521"}],"covers":["LR002869","LR006103"]},"LR001009":{"pair":"LAMC1 -> ITGA3","headline":"LAMC1 (in laminin-10/11) is recognised by integrin alpha3beta1 in A549 cell adhesion; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"Adhesion to laminin-10/11 coated substrata was inhibited by antibodies to integrin alpha3 or beta1 but not alpha2 or alpha6, indicating recognition by alpha3beta1 [PMID:9624186]. Annotated effect is Stimulatory [flag].","molecular_requirements":"Ligand is the alpha5-containing laminin-10/11 heterotrimer, so LAMC1 acts as one chain; the receptor is the alpha3beta1 heterodimer [PMID:9624186].","affinity_potency":[],"species_and_systems":"Human A549 lung adenocarcinoma cells and purified laminin-10/11; mouse pair is projected from human [PMID:9624186].","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Only an abstract was read. Antibody blocking of adhesion is not direct binding, and LAMC1 cannot be separated from the other chains. One review_only paper is not shown.","key_references":[{"PMID":"9624186","why":"Antibody-blocked A549 adhesion to laminin-10/11, abstract only"}],"covers":["LR001009","LR004427"]},"LR001018":{"pair":"LCN1 -> LMBR1L","headline":"LCN1 was isolated as a binder of LMBR1L (LIMR) by phage display; supported by one abstract and database records.","interaction_type":"direct binding","direction_and_effect":"A phage-display screen of a human pituitary cDNA library against lipocalin-1 isolated the membrane protein LIMR; a recombinant N-terminal LIMR fragment also showed specific interaction with Lcn-1 [PMID:11287427]. UniProt says LMBR1L acts as a LCN1 receptor and can mediate its endocytosis [DB:UniProt]; BioGRID lists a reconstituted complex [DB:BioGRID 286558].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; human NT2 cells confirmed membrane location of LIMR [PMID:11287427].","localisation_and_range":"LIMR has nine putative transmembrane domains and a cell-membrane location [PMID:11287427]; LCN1 is flagged secreted [flag].","caveats":"Abstract only; no affinity; the abstract text was cut off, so the details of the recombinant-fragment result are not shown.","key_references":[{"PMID":"11287427","why":"Phage-display cloning of the Lcn-1 interacting membrane receptor"}],"covers":["LR001018"]},"LR006112":{"pair":"LEFTY2 -> ACVR2A","headline":"Lefty2 is proposed to antagonise Nodal by competing for ActRIIA; evidence is one abstract-only inference, not binding.","interaction_type":"functional only","direction_and_effect":"Antagonist: processed Lefty proteins inhibited Nodal signalling, and the inhibition was rescued by excess ActRIIA or ActRIIB, which the authors take to suggest competitive binding to the shared receptor [PMID:11952836].","molecular_requirements":"ActRIIA or ActRIIB can serve as the type II receptor for Nodal, with ALK4 as type I; both smaller and larger processed Lefty forms inhibited. Other requirements not reported in our evidence [PMID:11952836].","affinity_potency":[],"species_and_systems":"Frog animal-cap assay, mouse genetic interaction (lefty2 with ActRIIB), and chick embryos; curator lists mouse ligand and Xenopus receptor. The human pair is ortholog-inferred [PMID:11952836].","localisation_and_range":"Lefty2 is flagged as secreted and ACVR2A as transmembrane [flag]; range of action not otherwise reported in our evidence. GFP-Lefty2 diffused faster than GFP-Nodal in chick embryos [PMID:11952836].","caveats":"Hedged: the rescue is an epistasis argument and direct Lefty2 binding to ActRIIA is not shown. The paper was read as abstract only; no other papers or database records.","key_references":[{"PMID":"11952836","why":"Rescue of Lefty inhibition by excess ActRIIA/ActRIIB in frog caps"}],"covers":["LR002878","LR006112"]},"LR005221":{"pair":"LGALS1 -> PTPRC","headline":"Galectin-1 binds CD45 on Jurkat T cells and suppresses its phosphatase activity; supported by papers plus BioGRID/IntAct.","interaction_type":"direct binding","direction_and_effect":"Galectin-1 reduced membrane-associated PTPase activity and immunoprecipitated CD45 activity in Jurkat cells; CD45+ cells showed higher galectin-1-induced phosphatidylserine than CD45- cells, implicating CD45 ligation in apoptosis [PMID:10369126].","molecular_requirements":"CD45 isoforms were detected in the galectin-1-agarose bound fraction [PMID:10369126]. Binds N-acetyllactosamine glycans, so glycosylation is relevant [PMID:10369126].","affinity_potency":[],"species_and_systems":"Human Jurkat T cell membranes and cells; placental galectin-1 [PMID:10369126]. Mouse pair ortholog-inferred. BioGRID lists Affinity Capture-Western and IntAct an enzymatic study [DB:BioGRID][DB:IntAct].","localisation_and_range":"Galectin-1 flagged secreted; PTPRC flagged transmembrane [flag].","caveats":"Affinity chromatography on immobilised galectin-1 does not exclude indirect association; abstract-only read.","key_references":[{"PMID":"10369126","why":"Galectin-1 agarose pulls down CD45; inhibits PTPase activity"}],"covers":["LR001879","LR005221"]},"LR006121":{"pair":"LGALS3 -> MERTK","headline":"Galectin-3 acts as a MERTK ligand promoting Muller glia phagocytosis, with genetic support in mouse retina.","interaction_type":"functional only","direction_and_effect":"Galectin-3 promoted phagocytosis by wild-type but not MERTK-deficient primary Muller glia, and galectin-3/MERTK double-knockout mice showed more Muller cell activation and photoreceptor loss; galectin-3 restrained Muller glia activation [PMID:35711472].","molecular_requirements":"MERTK required for the galectin-3 effect; effects of galectin-3 and protein S were additive at sub-saturating concentrations [PMID:35711472].","affinity_potency":[],"species_and_systems":"Immortalised human MIO-M1 Muller cells, primary mouse Muller glia, and knockout mice including a sodium-iodate injury model [PMID:35711472].","localisation_and_range":"Extracellular galectin-3 acts on Muller glia; galectin-3 flagged secreted, MERTK transmembrane [flag].","caveats":"Direct binding to MERTK not shown in our excerpts; the paper says galectin-3 had been shown able to activate MERTK in earlier work, which is background. Abstract-only read.","key_references":[{"PMID":"35711472","why":"Galectin-3 promotes MERTK-dependent Muller glia phagocytosis"}],"covers":["LR002887","LR006121"]},"LR006130":{"pair":"LGALS8 -> ITGB1","headline":"Galectin-8 binds alpha3beta1 integrin from carcinoma and other cells and blocks cell adhesion, inducing apoptosis; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Galectin-8 inhibited adhesion of human 1299 carcinoma cells to plates coated with integrin ligands and induced apoptosis (antagonist of adhesion); effects were not mimicked by galectin-1 or galectin-3, and Mn2+ abolished the inhibition [PMID:10852818].","molecular_requirements":"The integrin identified is alpha3beta1, so both ITGA3 and ITGB1 chains are involved; whether one chain suffices is not reported in our evidence [PMID:10852818].","affinity_potency":[],"species_and_systems":"Human 1299 carcinoma cells; alpha3beta1 also from HeLa and human endothelial cells; mouse pair is ortholog-inferred [PMID:10852818].","localisation_and_range":"Galectin-8 is a secreted protein (secreted flag [flag]); endogenous galectin-8 secreted from 1299 cells forms complexes with surface alpha3beta1 integrin [PMID:10852818].","caveats":"Abstract only. Binding is sugar-dependent (a beta-galactoside lectin reading glycans) [PMID:10852818]. BioGRID lists Affinity Capture-Western and Reconstituted Complex records [DB:BioGRID]. No affinity reported. Human pair is ortholog-inferred in the interaction list.","key_references":[{"PMID":"10852818","why":"Galectin-8 binding to alpha3beta1 integrin inhibits adhesion and induces apoptosis"}],"covers":["LR002900","LR006130"]},"LR005230":{"pair":"LGI2 -> ADAM23","headline":"LGI2 co-precipitates with Adam23 from rat brain; one full-text paper, with Reactome support.","interaction_type":"direct binding","direction_and_effect":"Both Adam22 and Adam23 antibodies co-precipitated Lgi2 from rat brain [PMID:21829378]. The paper's section title states Lgi2 K518X truncation prevents LGI2 secretion and action on neuronal ADAM receptors [PMID:21829378]. Reactome lists LGI2 binding ADAM22,23 [DB:Reactome].","molecular_requirements":"Reactome lists a complex LGI2:ADAM22,23 at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Rat brain co-IP and cell-surface binding assay; excerpts include Lagotto Romagnolo dogs, so curator's human label does not match [PMID:21829378]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LGI family are neuronally secreted proteins [PMID:21829378]; Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"A co-IP shows association, not direct binding; effect direction and affinity are not reported in our evidence. Reactome is the only database.","key_references":[{"PMID":"21829378","why":"Lgi2 co-IPs with Adam22/23; truncation blocks secretion"}],"covers":["LR001888","LR005230"]},"LR001027":{"pair":"LIPC -> LRP1","headline":"Hepatic lipase binds purified LRP with Kd 52 nM and is internalised by LRP; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Hepatic lipase binds purified LRP, and this binding is inhibited by RAP and heparin; 125I-HL internalisation and degradation by HepG2 cells is largely blocked by RAP or anti-LRP IgG [PMID:7721852]. The dossier lists agonist, but the result concerns endocytic clearance.","molecular_requirements":"Cell-surface proteoglycans are required for efficient internalisation (curator note and title) [PMID:7721852].","affinity_potency":[{"value":"Kd 52 nM","assay":"in vitro binding to purified LRP","system":"purified LRP","cite":"PMID:7721852"}],"species_and_systems":"Human proteins; HepG2 cells and LRP-deficient mouse fibroblasts [PMID:7721852]. Human and mouse pairs are ortholog-inferred. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"LIPC is flagged secreted [flag]; endocytic receptor action at the cell surface, requiring proteoglycans.","caveats":"One paper, abstract only (1995). Two further papers were review-only or abstract-insufficient.","key_references":[{"PMID":"7721852","why":"HL binds purified LRP, Kd 52 nM, and is internalised via LRP"}],"covers":["LR001027","LR004444"]},"LR001036":{"pair":"LRPAP1 -> LRP1","headline":"RAP (LRPAP1) binds LRP1 with a KD of 14 nM and blocks ligand binding; well supported by papers, structure and databases.","interaction_type":"direct binding","direction_and_effect":"RAP binds two equivalent sites on alpha2MR/LRP and completely inhibits binding of 125I-activated alpha2M, so RAP occupancy sets receptor activity [PMID:1374383]. Recombinant 39-kDa RAP reversibly binds the 515-kDa subunit and inhibits uptake of apoE-enriched VLDL and activated alpha2M [PMID:1718973]. Curators label it an antagonist [PMID:1374383].","molecular_requirements":"RAP binds the 515-kDa subunit [PMID:1718973]. Each of three LDL receptor homology regions (sLRP2, sLRP3, sLRP4) bound human RAP, though not all ligand binding could be competed by RAP [PMID:14596620].","affinity_potency":[{"value":"KD 14 nM","assay":"titration and binding studies","system":"alpha2MR/LRP","cite":"PMID:1374383"},{"value":"Ki 23 nM","assay":"displacement of 125I-activated alpha2M","system":"human fibroblasts","cite":"PMID:1374383"},{"value":"Ki 26 nM","assay":"displacement of 125I-activated alpha2M","system":"purified LRP","cite":"PMID:1374383"}],"species_and_systems":"Human fibroblasts, purified receptor, and Pichia-expressed human receptor fragments [PMID:1374383] [PMID:14596620]. Databases: PDB structure [DB:PDB 2FYL], BioGRID [DB:BioGRID], IntAct [DB:IntAct], UniProt [DB:UniProt]. The mouse pair is ortholog-inferred.","localisation_and_range":"LRPAP1 is flagged secreted [flag]. The curators' note describes RAP as an intracellular chaperone that remains associated on the cell surface [PMID:1374383].","caveats":"RAP is a regulatory or chaperone ligand that blocks other ligands, not a conventional signalling ligand [PMID:1374383]. Papers were read as abstracts only.","key_references":[{"PMID":"1374383","why":"RAP binding to LRP, KD 14 nM, and ligand inhibition"},{"PMID":"1718973","why":"Original demonstration that recombinant RAP binds LRP and inhibits ligands"},{"PMID":"14596620","why":"RAP binds all three LRP LDL-receptor homology regions"}],"covers":["LR001036","LR004450"]},"LR001045":{"pair":"LTB -> TNFRSF1A","headline":"Weak support: TNFR1 recognises a minor LT alpha2/beta1 complex; LT-beta's own contribution is not isolated.","interaction_type":"functional only","direction_and_effect":"The minor, early surface form with LT-alpha2/beta1 stoichiometry is recognised by the p55-TNF receptor [PMID:7995952]. Curator labels agonist.","molecular_requirements":"Recognition is by the complex; the LT-beta chain's contribution is not separated from LT-alpha2, per curator notes [PMID:7995952]. The predominant LT-alpha1/beta2 form is recognised by LTBR instead [PMID:7995952].","affinity_potency":[],"species_and_systems":"PMA-activated II-23 human T cell hybridoma; CHO cells co-transfected with LT-alpha and LT-beta gave similar surface forms [PMID:7995952].","localisation_and_range":"Surface (membrane-bound) LT complexes, not secreted [PMID:7995952].","caveats":"Abstract read only; BioGRID lists a reconstituted complex from the same paper [DB:BioGRID]. Whether LTB itself binds TNFR1 is not shown.","key_references":[{"PMID":"7995952","why":"Minor LT-alpha2/beta1 form recognised by p55 receptor"}],"covers":["LR001045","LR004458"]},"LR001054":{"pair":"MBL2 -> CD93","headline":"Supported only by UniProt annotation; no curated paper evidence for this pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes CD93 as a receptor for defense collagens including C1q, SFTPA1 and mannose-binding lectin (MBL2), enhancing uptake of apoptotic cells and immune complexes [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human annotation; mouse pair is ortholog-inferred. No experimental system in our evidence.","localisation_and_range":"MBL2 is flagged secreted; CD93 flagged transmembrane receptor [flag].","caveats":"No paper confirmed the pair; two judged rows were classed as different entity. Support is a UniProt function statement only [PMID:7977768][DB:UniProt].","key_references":[],"covers":["LR001054","LR004467"]},"LR001900":{"pair":"MCAM -> MCAM","headline":"Possible homophilic MCAM binding, suggested by adhesion data in a single abstract-only paper.","interaction_type":"functional only","direction_and_effect":"MCAM-l-transfected NKL1 cells and activated CD4 T cells adhered to recombinant MCAM under shear stress, blocked by anti-MCAM antibody, 'suggesting' homophilic MCAM-l-MCAM-l interactions [PMID:17982057].","molecular_requirements":"The long cytoplasmic isoform (MCAM-l) is needed; MCAM short or mock transfection had no effect on adhesion [PMID:17982057].","affinity_potency":[],"species_and_systems":"Human NK cell line NKL1, CD4 T cells, recombinant MCAM, under shear stress [PMID:17982057]. Mouse pair is ortholog-inferred.","localisation_and_range":"Annotation flags give not secreted and not transmembrane [flag], which does not settle localisation; adhesion data imply cell surface contact.","caveats":"The abstract describes homophilic binding only as possible; the paper's clearer finding is MCAM promoting VCAM-1 rolling. Antibody inhibition does not prove direct self-binding. BioGRID lists a co-purification [PMID:29741757][DB:BioGRID].","key_references":[{"PMID":"17982057","why":"MCAM-l adhesion to recombinant MCAM under shear"}],"covers":["LR001900","LR005242"]},"LR001063":{"pair":"MDK -> SDC4","headline":"Midkine binds syndecan-4 (ryudocan) with a reported Kd of 0.30 nM through heparan sulfate chains; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Purified human ryudocan bound midkine in a solid-phase assay [PMID:8621465]. Midkine bound both HS and CS chains of syndecan-4, more strongly to its CS chains than those of syndecan-1 [PMID:15226297].","molecular_requirements":"In the human ryudocan study binding was via HS chains: heparitinase destroyed it, heparin and HS inhibited, chondroitin sulfate did not [PMID:8621465]. In murine syndecan-4 both HS and CS chains contributed [PMID:15226297]; the two papers differ on CS involvement.","affinity_potency":[{"value":"Kd 0.30 nM","assay":"solid-phase binding (apparent dissociation constant)","system":"purified human ryudocan from EAhy926 cells","cite":"PMID:8621465"}],"species_and_systems":"Human ryudocan from EAhy926 endothelium-like cells [PMID:8621465]; murine mammary epithelial cell syndecan-4 by BIAcore [PMID:15226297]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence; syndecan-4 is a transmembrane proteoglycan per paper titles/abstracts [PMID:15226297].","caveats":"Both papers read as abstract only. Discrepancy between HS-only and HS+CS binding. Binding is to glycosaminoglycan chains, not necessarily the core protein.","key_references":[{"PMID":"8621465","why":"Kd 0.30 nM for midkine binding to human ryudocan"},{"PMID":"15226297","why":"HS and CS chain binding of midkine to syndecan-4"}],"covers":["LR001063","LR004476"]},"LR001072":{"pair":"MMP12 -> PLAUR","headline":"This appears to be enzyme-substrate: MMP-12 cleaves uPAR rather than binding it as a ligand.","interaction_type":"functional only","direction_and_effect":"MMP-12 and other MMPs cleave uPAR at Thr86-Tyr87 in the D1-D2 linker, releasing domain 1, which prevents uPA and vitronectin binding. Murine uPAR is cleaved at Pro89-Gln90 [PMID:12195704].","molecular_requirements":"Not reported in our evidence as a ligand-receptor requirement.","affinity_potency":[],"species_and_systems":"Human uPAR cleavage by MMP-12 and other MMPs, with murine uPAR also cleaved; abstract only [PMID:12195704].","localisation_and_range":"MMP-12 carries a secreted flag; PLAUR carries secreted, receptor and transmembrane flags [flag].","caveats":"Evidence is proteolysis, not receptor engagement; no binding or affinity data. Single paper read as abstract [PMID:12195704].","key_references":[{"PMID":"12195704","why":"MMP-12 cleaves uPAR in the linker region"}],"covers":["LR001072","LR004484"]},"LR008002":{"pair":"MMP9:TIMP1 -> LRP1","headline":"The MMP-9.TIMP-1 complex binds LRP with high affinity and is internalised; same single abstract as MMP9 -> LRP1.","interaction_type":"direct binding","direction_and_effect":"The MMP-9.TIMP-1 complex bound LRP with high affinity; LRP-expressing cells internalised 125I-MMP-9.TIMP-1 while LRP-deficient lines did so poorly [PMID:11279011].","molecular_requirements":"The complex is the unit tested, and the binding determinant appears to lie on MMP-9, so TIMP-1 need not contact LRP [PMID:11279011].","affinity_potency":[],"species_and_systems":"Human proteins with mouse embryonic fibroblasts [PMID:11279011].","localisation_and_range":"Both complex members are flagged as secreted [flag]; LRP internalises the complex from outside the cell [PMID:11279011].","caveats":"Single paper, abstract only; no affinity value given. The TIMP1 side is complex-inherited, not a direct TIMP1-LRP interaction. LRP1 is a clearance receptor.","key_references":[{"PMID":"11279011","why":"MMP-9.TIMP-1 binding and internalisation by LRP"}],"covers":["LR008002"]},"LR001081":{"pair":"MUC7 -> SELL","headline":"Direct binding of L-selectin chimeras to purified MUC7 (MG2) shown in vitro; read from abstract only.","interaction_type":"direct binding","direction_and_effect":"L-selectin chimeras interacted with immobilised MG2 (MUC7 product) in an ELISA in a Ca2+-dependent manner and bound MG2 on nitrocellulose; the curator labels MUC7 as agonist [PMID:9538010].","molecular_requirements":"MG2 carries sialyl-Lewis-x and related oligosaccharides, which are the likely selectin-binding determinants; only abstract-level evidence [PMID:9538010].","affinity_potency":[],"species_and_systems":"Human MG2 purified from saliva with L-selectin chimeras (cell-free assays); the human SELL pair is ortholog-inferred [PMID:9538010].","localisation_and_range":"MUC7 is flagged secreted and SELL transmembrane [flag]; paper proposes a role in oral-cavity leukocyte interactions [PMID:9538010].","caveats":"Abstract only. Cell-free binding; no affinity and no functional signalling shown. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","key_references":[{"PMID":"9538010","why":"MG2/MUC7 bound by L-selectin chimeras, Ca2+-dependent"}],"covers":["LR001081"]},"LR006202":{"pair":"NCAM1 -> NCAM1","headline":"Homophilic NCAM-NCAM binding with force spectroscopy and signalling evidence.","interaction_type":"direct binding","direction_and_effect":"NCAM binds in two spatially distinct configurations by force measurements [PMID:15118102]. A homophilic-site peptide (P2) increased intracellular Ca2+ in primary hippocampal neurons through FGFR/PLCgamma and Src-family kinase pathways [PMID:16510522].","molecular_requirements":"The extracellular region has five Ig and two fibronectin domains; Ig-domain deletions mapped the domains for each bond, and a flexible hinge was found [PMID:15118102]. Reactome lists cis-homodimer and trans-homotetramer complexes [DB:Reactome R-HSA-190988, R-HSA-375103].","affinity_potency":[],"species_and_systems":"Both papers abstract-only; species recorded as human in curation fields. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are membrane-bound, so homophilic binding is cis or trans contact (adhesive) [flag].","caveats":"Self-interaction: the ligand and receptor are the same chain, which CCC tools score unusually. The Ca2+ paper used a mimetic peptide, not full NCAM [PMID:16510522].","key_references":[{"PMID":"15118102","why":"Force measurements of NCAM homophilic binding"},{"PMID":"16510522","why":"P2 peptide mimics homophilic NCAM signalling, Ca2+ rise"}],"covers":["LR002977","LR006202"]},"LR001090":{"pair":"NCAM1 -> ROBO3","headline":"Robo3 reported to bind NCAM heterophilically in a human-isoform paper; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind homophilically and heterophilically to Robo1 and NCAM; effect not reported in our evidence [PMID:16226035].","molecular_requirements":"Two Robo3 isoforms (Robo3A, Robo3B) differ by a 26-residue N-terminal insertion; which isoform binds NCAM is not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms, with mouse embryo orthologue expression; mouse pair is ortholog-inferred [PMID:16226035].","localisation_and_range":"Both partners membrane-bound per flags [flag].","caveats":"Only an abstract states that Robo3 binds heterophilically to NCAM; the abstract gives no assay, affinity or direction.","key_references":[{"PMID":"16226035","why":"Robo3 binds NCAM heterophilically"}],"covers":["LR001090","LR004501"]},"LR004501":{"pair":"NCAM1 -> ROBO3","headline":"Robo3 reported to bind NCAM heterophilically in a human-isoform paper; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind homophilically and heterophilically to Robo1 and NCAM; effect not reported in our evidence [PMID:16226035].","molecular_requirements":"Two Robo3 isoforms (Robo3A, Robo3B) differ by a 26-residue N-terminal insertion; which isoform binds NCAM is not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms, with mouse embryo orthologue expression; mouse pair is ortholog-inferred [PMID:16226035].","localisation_and_range":"Both partners membrane-bound per flags [flag].","caveats":"Only an abstract states that Robo3 binds heterophilically to NCAM; the abstract gives no assay, affinity or direction.","key_references":[{"PMID":"16226035","why":"Robo3 binds NCAM heterophilically"}],"covers":["LR001090","LR004501"]},"LR006211":{"pair":"NEGR1 -> NEGR1","headline":"NEGR1 homodimerises in trans through its first Ig domain; a self-interaction with structural and cell-aggregation support.","interaction_type":"direct binding","direction_and_effect":"IgLONs, including NEGR1, interact as homo- and heterodimers; NEGR1 oligomerised concentration-dependently by size-exclusion chromatography, and NTRI and NEGR1 homo- and heterodimerize in trans in cell aggregation assays [PMID:30956130]. Signalling direction is not reported.","molecular_requirements":"Dimerisation occurs through the first Ig domain of each monomer and is calcium-independent [PMID:30956130].","affinity_potency":[],"species_and_systems":"Recombinant proteins and cell aggregation assays; species not stated in our excerpts, curator recorded human [PMID:30956130]. Mouse pair is projected.","localisation_and_range":"Cell-surface protein by flag [flag]; trans interaction between cells [PMID:30956130].","caveats":"Abstract-level reading for curator fields. Homodimer, so ligand and receptor are the same molecule; dossier shows one of two confirmed papers. IntAct has a protein array record [DB:IntAct].","key_references":[{"PMID":"30956130","why":"IgLON homo/heterodimer structures and aggregation"}],"covers":["LR002986","LR006211"]},"LR004510":{"pair":"NID1 -> ITGB3","headline":"Entactin RGD recognised by alphaVbeta3 in attachment assays on recombinant and native entactin; abstract-level papers only.","interaction_type":"functional only","direction_and_effect":"The RGD sequence in entactin is recognised by alpha v beta 3 in attachment assays [PMID:7797588]; human mesangial cells use alpha v beta 3 and a beta 1-containing integrin for native entactin [PMID:9686320].","molecular_requirements":"Beta3 acts with alphaV; a second RGD-independent site is recognised by a beta 1 integrin [PMID:7797588].","affinity_potency":[],"species_and_systems":"Cell attachment assays with mutant recombinant entactin and cultured human kidney mesangial cells; both abstract only [PMID:7797588][PMID:9686320]. Human pair is listed and mouse pair is ortholog-inferred.","localisation_and_range":"Entactin is a basement-membrane glycoprotein; NID1 is annotated secreted [flag].","caveats":"Functional attachment and antibody inhibition, not purified binding. Three other papers were abstract-insufficient and one is pending.","key_references":[{"PMID":"7797588","why":"RGD deletion mutants show alpha v beta 3 recognition of entactin"},{"PMID":"9686320","why":"Antibody inhibition shows alpha v beta 3 use on mesangial cells"}],"covers":["LR001099","LR004510"]},"LR001108":{"pair":"NLGN3 -> NRXN1","headline":"Neuroligin-3 binding to neurexin-1beta is supported by rat full-text affinity chromatography and an SPR paper covering neuroligins 1-4.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind neurexin 1beta in a Ca2+-dependent manner [PMID:8576240]. Neuroligins 1-4 bind neurexin-1beta with affinities spanning more than 2 orders of magnitude [PMID:17042500]; the curator note says NL3 appears only via a review as lower affinity.","molecular_requirements":"Neuroligin extracellular domains sediment as dimers, beta-neurexins as monomers, with a 2:2 complex suggested; splice insert 4 modulates association [PMID:17042500].","affinity_potency":[],"species_and_systems":"Rat brain proteins [PMID:8576240]; species unspecified in 17042500 though ranking is said to be conserved across mammals. Mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex and an affinity capture-western record [DB:BioGRID].","caveats":"17042500 abstract covers neuroligins collectively without naming NL3; the 8576240 full-text quote is a browser read with spot-check pending. No NL3-specific affinity value. One paper unresolvable, others abstract-insufficient.","key_references":[{"PMID":"8576240","why":"Neuroligins bind neurexin 1beta, Ca2+ dependent"},{"PMID":"17042500","why":"SPR of neuroligins 1-4 against neurexin-1beta"}],"covers":["LR001108","LR004519"]},"LR001117":{"pair":"NODAL -> ACVR1B","headline":"Functional support for ALK4 (ACVR1B) as a Nodal type I receptor, but only with Cripto, and mainly from Xenopus and mouse experiments.","interaction_type":"functional only","direction_and_effect":"ALK4 mediates Nodal signalling in the presence of Cripto, and dominant-negative ALK4 blocks Nodal in frog animal caps [PMID:11485994][PMID:11952836]. Effect is signalling activation (agonist) [PMID:11952836].","molecular_requirements":"Type I receptor needs a type II partner (ActRIIA or ActRIIB) [PMID:11952836] and Cripto: membrane-bound Cripto is an obligatory co-receptor, while a soluble form binds Nodal but fails to signal [PMID:11952836]. Cripto interacts directly with ALK4 [PMID:11485994].","affinity_potency":[],"species_and_systems":"Mouse Nodal and Xenopus Nodal-related 1 in Xenopus embryos and cell reconstitution [PMID:11485994]; Xenopus animal caps [PMID:11952836]. The mouse pair is direct; the human pair is projected by orthology.","localisation_and_range":"Nodal flagged secreted [flag]; in the paper it signals via membrane-bound Cripto on receiving cells [PMID:11952836].","caveats":"Nodal-pathway rows differ by which type II receptor and co-receptor are included; CCC scoring by the weakest subunit makes the co-receptor requirement matter. Evidence is dominant-negative loss of function, not binding, for ALK4 [PMID:11952836]. Both papers read as abstract only. PMID:11485994 is mainly about ALK7, and dominant-negative ALK4 is not Nodal-specific.","key_references":[{"PMID":"11485994","why":"Reconstitution: ALK4 mediates Nodal signalling only with Cripto"},{"PMID":"11952836","why":"ALK4 and ActRIIA/B as Nodal receptors; membrane Cripto is obligatory"}],"covers":["LR001117","LR004528"]},"LR006220":{"pair":"NPFF -> MAS1","headline":"NPFF activates MAS (MAS1) in human cell assays with an atypical calcium-led profile; one functional paper.","interaction_type":"functional only","direction_and_effect":"NPFF activated MAS with a rapid calcium rise and very weak IP1 accumulation, unlike classical Gq-PLC signalling, and weakly stimulated Galpha12/Galphai pathways; agonist [PMID:25068582].","molecular_requirements":"MAS shows strong constitutive activity; NPFF and non-peptide ligands appear to bind overlapping regions by mutagenesis [PMID:25068582].","affinity_potency":[],"species_and_systems":"Human MAS in stable inducible cells; peptides tested in calcium, IP1, cAMP and luciferase assays [PMID:25068582]. Mouse pair ortholog-inferred.","localisation_and_range":"NPFF is flagged secreted [flag].","caveats":"No binding data or EC50 in our excerpts. Angiotensin fragments only weakly potentiate at >=100 microM [PMID:25068582]. No database support.","key_references":[{"PMID":"25068582","why":"NPFF signalling and desensitization at MAS"}],"covers":["LR002996","LR006220"]},"LR001126":{"pair":"NPNT -> ITGA8","headline":"Nephronectin binds integrin alpha8beta1 in an RGD-dependent manner; one mouse study with strong binding evidence.","interaction_type":"direct binding","direction_and_effect":"Soluble alpha8beta1-alkaline phosphatase probe binds nephronectin, and the two form a complex in vivo [PMID:11470831]. Binding was abolished by GRGDSP peptide but not GRGESP [PMID:11470831]. Effect on signalling is not reported in our evidence beyond the Stimulatory annotation.","molecular_requirements":"ITGA8 acts as the alpha8beta1 heterodimer with ITGB1 [PMID:11470831]; Reactome lists an NPNT:ITGA8:ITGB1 complex [DB:Reactome]. Binding maps to nephronectin residues 382-561, likely including the RGD, which the paper says was not proven by mutation [PMID:11470831].","affinity_potency":[],"species_and_systems":"Mouse (newborn kidney extracts, mouse nephronectin) with recombinant probe and fusion proteins [PMID:11470831]. The human pair is ortholog-inferred.","localisation_and_range":"Nephronectin is an extracellular matrix protein with a signal peptide and no transmembrane region [PMID:11470831]; ligand-expressing ureteric bud and receptor-expressing mesenchyme are adjacent [PMID:11470831].","caveats":"Single paper. Several other RGD-binding integrins also bind nephronectin [PMID:11470831], so the pair is not exclusive. BioGRID records come from the same paper [DB:BioGRID].","key_references":[{"PMID":"11470831","why":"Identifies nephronectin as alpha8beta1 ligand with RGD-dependent binding"}],"covers":["LR001126","LR004536"]},"LR001135":{"pair":"NPS -> NPSR1","headline":"Neuropeptide S activates NPSR1 as a full agonist with Ca2+ mobilisation; supported by functional papers and databases.","interaction_type":"functional only","direction_and_effect":"NPS activates NPSR and mobilises intracellular Ca2+ [PMID:15312648]; GtoPdb lists full agonist [DB:GtoPdb]. NPS-NPSR1 signalling increased expression of cholecystokinin, VIP, PYY and somatostatin in NPSR1-transfected HEK293 cells [PMID:19732772]. UniProt says NPSR1 signals via Gq/GNAQ-dependent phospholipase C [DB:UniProt].","molecular_requirements":"Receptor-only; no co-receptor reported.","affinity_potency":[{"value":"pEC50 8.0","assay":"Ca2+ mobilisation","system":"receptor-activation assay","cite":"PMID:15312648"}],"species_and_systems":"Ca2+ assay plus mouse and rat in vivo behaviour [PMID:15312648]; human NPSR1-transfected HEK293 cells [PMID:19732772]. Both pairs are ortholog-inferred.","localisation_and_range":"NPS annotated secreted and NPSR1 transmembrane [flag].","caveats":"Abstract-only reading. Effects in the physiology papers are downstream and do not measure binding.","key_references":[{"PMID":"15312648","why":"NPS activates NPSR; in vivo arousal and anxiety effects"},{"PMID":"19732772","why":"NPS-NPSR1 signalling in enteroendocrine context"}],"covers":["LR001135","LR004545"]},"LR001144":{"pair":"NPY -> NPY5R","headline":"NPY is a high-affinity agonist of NPY5R according to one cloning paper plus a family reference; abstract level.","interaction_type":"direct binding","direction_and_effect":"Rat and human Y5 have high affinity for feeding-eliciting peptides such as NPY and low affinity for non-stimulating ones [PMID:8824284]; NPY shows highest affinities at Y1, Y2 and Y5 [PMID:15966750]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor reported.","affinity_potency":[{"value":"pKi 9.1","assay":"curator-recorded affinity from cloning paper","system":"human Y5","cite":"PMID:8824284"}],"species_and_systems":"Receptor cloned from a rat hypothalamus library, human homologue at 88% identity; pharmacology on rat and human Y5 [PMID:8824284]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, NPY5R transmembrane [flag].","caveats":"Both papers are abstract only. The pKi is curator-recorded and not in the abstract. The chimera paper gives only a qualitative statement [PMID:15966750].","key_references":[{"PMID":"8824284","why":"Cloning of Y5 and its NPY pharmacology"},{"PMID":"15966750","why":"NPY highest affinities at Y1/Y2/Y5"}],"covers":["LR001144","LR004553"]},"LR003007":{"pair":"NRG1 -> ITGB4","headline":"Single abstract-level report that NRG1 binds integrin beta4 (ITGB4); one paper, stored per subunit, not the dimer.","interaction_type":"direct binding","direction_and_effect":"NRG1 (isolated EGF-like domain or native multi-domain form) binds integrins; Lys-to-Glu mutants suppressed integrin binding and ErbB3 phosphorylation, so integrin binding appears to support NRG1-ErbB3 signalling [PMID:20682778]. UniProt states this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"NRG1 binds the integrin heterodimers alphavbeta3 and alpha6beta4; the dossier stores them per subunit [PMID:20682778]. alpha6beta4 was functionally dominant for forming the integrin-NRG1-ErbB3 ternary complex [PMID:20682778]. A UniProt record says the ternary complex includes ERBB3 [DB:UniProt]. This row names only one chain; the evidence concerns the heterodimer.","affinity_potency":[{"value":"KD 136 nM (1.36 x 10(-7) m), to alphavbeta3","assay":"direct binding","system":"purified integrins","cite":"PMID:20682778"}],"species_and_systems":"Human ligand and human receptor, purified proteins; the mouse pair is projected from human evidence [PMID:20682778].","localisation_and_range":"NRG1 is flagged both secreted and transmembrane [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as abstract only. The KD is for alphavbeta3, not for this individual chain. Chain-only row for a heterodimeric receptor; the integrin dimer should be the unit scored.","key_references":[{"PMID":"20682778","why":"Direct NRG1-integrin binding and integrin-NRG1-ErbB3 ternary complex"}],"covers":["LR003007","LR006231"]},"LR012430":{"pair":"NRP2 -> KDR","headline":"NRP2 physically interacts with KDR (VEGFR2) in prostate cancer cells, from one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"NRP2 physically interacts with VEGFR2 via the intracellular SEA domain, activating STAT3 phosphorylation and SOX2 and driving NEPC differentiation [PMID:35986103].","molecular_requirements":"The interaction is through the intracellular SEA domain; other subunits not reported [PMID:35986103].","affinity_potency":[],"species_and_systems":"Prostate cancer cells and xenografts; species not stated in the abstract [PMID:35986103].","localisation_and_range":"Both annotated as transmembrane receptors [flag]; cis receptor-receptor association.","caveats":"Abstract only; no affinity; 2 papers different_entity, 3 abstract_insufficient. A co-receptor association rather than ligand binding, so direction is unclear.","key_references":[{"PMID":"35986103","why":"NRP2 interacts with VEGFR2 via SEA domain"}],"covers":["LR012430"]},"LR001153":{"pair":"NRTN -> GFRA1","headline":"NRTN binds GFRA1 in several 1997-1998 papers, with lower efficiency than GDNF in one.","interaction_type":"direct binding","direction_and_effect":"Neurturin binds either GFRalpha-1 or GFRalpha-2, and both mediate neurturin-induced Ret phosphorylation [PMID:9407096]. NTN bound GFRa1-Fc with similar affinity to GDNF [PMID:9883723].","molecular_requirements":"Ret was used with GFRa1 for signalling; TrnR1-Ret cells responded equivalently to NTN and GDNF [PMID:9182803]. Cells expressing GFRalpha-1 bind GDNF more efficiently than neurturin [PMID:9407096].","affinity_potency":[],"species_and_systems":"Human receptors in transfected cells [PMID:9182803]; Fc-body binding assay [PMID:9883723]; mouse pair is projected from human.","localisation_and_range":"NRTN is annotated secreted, not transmembrane [flag]; GFRA1 is GPI-anchored in the GDNF family [PMID:9182803].","caveats":"Two papers read as abstract only. One row for PMID 9883723 was pair_absent from the abstract alone, but full text reports binding [PMID:9883723]. GFRalpha-1 is the primary GDNF receptor, so NRTN is secondary here [PMID:9407096]. No affinity numbers in our evidence.","key_references":[{"PMID":"9407096","why":"NTN binds GFRalpha-1 or GFRalpha-2"},{"PMID":"9883723","why":"NTN and GDNF bind GFRa1-Fc with similar affinity"},{"PMID":"9182803","why":"TrnR1-Ret responds equivalently to NTN and GDNF"}],"covers":["LR001153","LR004562"]},"LR003016":{"pair":"NRXN1 -> CLSTN3","headline":"Direct binding of beta-neurexins to calsyntenin-3 reported; abstract only, NRXN1 not named, species unspecified.","interaction_type":"direct binding","direction_and_effect":"Beta-Nrxns bind Clstn3 directly through their LNS domain, and Clstn3 links to SS4-insert-positive Nrxns to induce presynaptic differentiation [PMID:32434929]. Direction: postsynaptic Clstn3 acts via presynaptic Nrxns [PMID:32434929].","molecular_requirements":"Needs SS4-positive beta-Nrxn variants; insert-negative variants did not reverse the Clstn3 synaptogenic defect. The Clstn3 cadherin domains are involved [PMID:32434929]. UniProt notes NRXN1 binds CLSTN3 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species not specified in the curation of this paper (mouse pair is the paper's likely context but is not stated here).","localisation_and_range":"Both are transmembrane [flag]; trans-synaptic contact.","caveats":"Abstract only. The abstract refers to beta-Nrxns as a group and does not name NRXN1. It also states that whether Nrxns bind Clstn3 directly had been debated.","key_references":[{"PMID":"32434929","why":"beta-Nrxn LNS domain binds Clstn3, SS4-dependent synaptogenic activity"}],"covers":["LR003016","LR006240"]},"LR003025":{"pair":"NRXN2 -> CLSTN3","headline":"Beta-neurexin binding to Clstn3 reported in general; NRXN2 is not named in our evidence.","interaction_type":"direct binding","direction_and_effect":"Beta-Nrxns directly interact via their LNS domain with Clstn3; SS4-positive beta-Nrxn variants reversed the impaired Clstn3 synaptogenic activity in Nrxn-deficient neurons [PMID:32434929].","molecular_requirements":"Needs SS4-insert-positive variants; Clstn3 cadherin domains are involved [PMID:32434929].","affinity_potency":[],"species_and_systems":"Species unspecified in curation; mouse pair is the non-inferred one.","localisation_and_range":"Both transmembrane [flag]; trans-synaptic.","caveats":"Abstract only. The abstract names beta-Nrxns as a group, not NRXN2.","key_references":[{"PMID":"32434929","why":"beta-Nrxn LNS domain binds Clstn3"}],"covers":["LR003025","LR006249"]},"LR001162":{"pair":"NTN1 -> ADORA2B","headline":"One 2000 abstract reports A2b as a netrin-1 receptor inducing cAMP; no independent confirmation in our evidence.","interaction_type":"direct binding","direction_and_effect":"A2b is reported as a netrin-1 receptor that induces cAMP accumulation on binding netrin-1 [PMID:11048721]. Curator assay_detail notes a dorsal spinal cord axon outgrowth readout [PMID:11048721].","molecular_requirements":"The abstract says DCC interacts with the adenosine A2b receptor, suggesting a DCC co-receptor context [PMID:11048721].","affinity_potency":[],"species_and_systems":"Species not specified in our evidence; abstract only [PMID:11048721].","localisation_and_range":"NTN1 flagged secreted, ADORA2B transmembrane [flag].","caveats":"Single paper, abstract only, no database records; the curator-listed assay is described as direct binding although the abstract emphasises cAMP signalling.","key_references":[{"PMID":"11048721","why":"A2b as netrin-1 receptor"}],"covers":["LR001162","LR004571"]},"LR003034":{"pair":"NTN1 -> DSCAM","headline":"Two papers support netrin-1 as a DSCAM ligand, acting independently of DCC; one reports binding, read as abstract only.","interaction_type":"direct binding","direction_and_effect":"Netrin-1 binds DSCAM and acts as an agonist: DSCAM mediates turning responses to netrin-1 and Xenopus neurons expressing DSCAM are attracted by netrin-1 independently of DCC [PMID:18585357]. Without DCC, DSCAM mediates netrin signalling, activating Fyn and Pak1 phosphorylation [PMID:19196994].","molecular_requirements":"DSCAM alone can mediate netrin signalling in transfected cells [PMID:19196994]. DSCAM and DCC can each mediate a turning response, and also collaborate in commissural axon guidance [PMID:18585357]. UniProt says the extracellular domain interacts with NTN1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Spinal commissural axons, Xenopus spinal neurons, transfected cells; siRNA knockdown in ovo [PMID:18585357][PMID:19196994]. Species labelled human for both partners in the curation, but the abstracts do not state it.","localisation_and_range":"Netrin-1 flagged secreted, DSCAM transmembrane (also flagged secreted) [flag].","caveats":"Both papers read as abstracts only. Binding is stated in the abstracts, with no affinity reported. The second paper is mostly functional (knockdown, signalling) [PMID:19196994].","key_references":[{"PMID":"18585357","why":"DSCAM binds netrin-1 and mediates turning independent of DCC"},{"PMID":"19196994","why":"DSCAM knockdown blocks netrin-induced outgrowth; DCC-independent signalling"}],"covers":["LR003034","LR006258"]},"LR001171":{"pair":"NTN4 -> UNC5A","headline":"Netrin-4 binds UNC5H1 (UNC5A)-transfected CHO cells via the N-terminal domain; single abstract-only study.","interaction_type":"direct binding","direction_and_effect":"AP4-tagged netrin-4 bound CHO cells transfected with DCC or UNC5 homolog 1 (UNC5H1), and only the N-terminal LNT domain bound [PMID:17174565].","molecular_requirements":"Not reported in our evidence beyond domain mapping; binding may involve other, unidentified neuronal receptors [PMID:17174565].","affinity_potency":[],"species_and_systems":"COS7-derived fusion protein, CHO transfectants, cortical neurons [PMID:17174565]. Reactome lists NTN4:DCC,UNC5A complex [DB:Reactome]. Both pairs ortholog-inferred.","localisation_and_range":"Netrin-4 is secreted and UNC5A is transmembrane [flag].","caveats":"Abstract only, no affinity. The mapping of UNC5H1 to UNC5A is the curators' own; the abstract names only UNC5H1.","key_references":[{"PMID":"17174565","why":"Netrin-4 binds UNC5H1 and DCC transfectants"}],"covers":["LR001171","LR004580"]},"LR003043":{"pair":"NXNL1 -> BSG","headline":"RdCVF (NXNL1) binds Basigin-1 in photoreceptors to protect cones; a single abstract-only paper plus UniProt supports it.","interaction_type":"direct binding","direction_and_effect":"RdCVF acts through binding to Basigin-1 (BSG1) on photoreceptors, leading to increased glucose entry into cones and survival via aerobic glycolysis [PMID:25957687]. UniProt describes BSG as a retinal cell surface receptor for NXNL1 [DB:UniProt].","molecular_requirements":"The BSG1 isoform is specified; BSG1 then binds the glucose transporter GLUT1 [PMID:25957687]. A missense RdCVF mutation abolishes BSG1 binding, glucose uptake and protection [PMID:25957687].","affinity_potency":[],"species_and_systems":"Abstract does not name species or binding affinity; a model of retinitis pigmentosa was used [PMID:25957687]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"RdCVF is a secreted thioredoxin-like protein [flag][PMID:25957687]; BSG is a transmembrane receptor [flag]. Paracrine from rods to cones [PMID:25957687].","caveats":"Single paper, abstract only; no affinity reported in our evidence. Both species pairs are inferred by orthology.","key_references":[{"PMID":"25957687","why":"RdCVF binds BSG1 to stimulate cone glucose uptake"}],"covers":["LR003043","LR006267"]},"LR001180":{"pair":"NXPH3 -> NRXN2","headline":"Neurexophilin-3 binds neurexin-2 LNS2 per a 2019 full-text study and a 1998 recombinant study.","interaction_type":"direct binding","direction_and_effect":"Nxph3 binding to Nrxn1-3 LNS2SS2- was tested [PMID:31566781], and neurexophilins 1 and 3 bind the second LNS domain of all three alpha-neurexins [PMID:9856994].","molecular_requirements":"LNS2 is the binding domain [PMID:9856994]. I401Q equivalents in Nrxn2 reduced Nxph1 affinity from the nanomolar to the micromolar range; the Nxph3 values are not stated in our excerpts [PMID:31566781].","affinity_potency":[],"species_and_systems":"Recombinant mouse proteins [PMID:9856994]; recombinant LNS2 constructs [PMID:31566781]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag]; membrane neurexin [flag].","caveats":"The quoted NXPH3 sentence is the lead-in to the test, not a stated result. No affinity numbers for Nxph3 in our evidence. The 1998 paper was read as abstract only.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001180","LR004589"]},"LR004600":{"pair":"OXT -> AVPR1B","headline":"Oxytocin acts on V1b only weakly supported: one islet functional study in mouse and a comparator paper.","interaction_type":"functional only","direction_and_effect":"In mouse islets, a V1b antagonist plus an OT-receptor antagonist inhibited OT-induced glucagon secretion more (69%) than the OT-receptor antagonist alone (45%), indicating V1b can mediate the OT effect; in V1bR-/- mice OT still stimulated secretion with unchanged efficacy [PMID:17283236].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse islets (OT presumed human peptide in dossier) [PMID:17283236]; recombinant human receptors in CHO cells in the comparator paper [PMID:16158071]. Human pair is ortholog-inferred.","localisation_and_range":"OXT is flagged secreted; AVPR1B is a transmembrane receptor [flag].","caveats":"PMID:16158071 is a compound-characterisation paper in which V1b is a comparator, and native OT binding to V1b is not independently measured there. Both papers are abstract only. In the islet study, receptor compensation complicates attribution [PMID:17283236]. GtoPdb pKi 5.7 to 7.0 [DB:GtoPdb].","key_references":[{"PMID":"17283236","why":"genetic and pharmacological evidence that V1b mediates OT effect in islets"},{"PMID":"16158071","why":"V1b comparator data only"}],"covers":["LR001191","LR004600"]},"LR003052":{"pair":"PCDHB6 -> PCDHB6","headline":"Mouse PCDHB6 binds itself homophilically in trans (K562 aggregation and SPR), with strict isoform specificity.","interaction_type":"direct binding","direction_and_effect":"Pcdhb6 shows strict trans homophilic specificity: \u03b26 and \u03b28 do not engage heterophilically despite 91-97% identity in EC2-EC3 [PMID:25171406]. Five interfacial residues account for its specificity versus \u03b28 [PMID:35253643].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse proteins: K562 aggregation [PMID:25171406]; EC1-4 fragments by SPR and K562 coaggregation [PMID:35253643]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Isoforms 91-97% identical in EC2-EC3 do not cross-react, so paralogs cannot substitute [PMID:25171406]. Surface delivery of alpha isoforms needs cis partners, per curator note, so a multimer may be what meets across the cleft.","key_references":[{"PMID":"25171406","why":"strict homophilic specificity across isoforms"},{"PMID":"35253643","why":"SPR and residues tuning beta6 specificity"}],"covers":["LR003052","LR006286"]},"LR006310":{"pair":"PDCD1 -> PDCD1LG2","headline":"PD-1 binds PD-L2 with measured SPR kinetics; PD-L2 shows 2-6-fold higher affinity than PD-L1.","interaction_type":"direct binding","direction_and_effect":"B7-DC (PD-L2)/PD-1 exhibited a 2-6-fold higher affinity and different association/dissociation kinetics compared with B7-H1/PD-1 [PMID:12893276]. UniProt: PDCD1 delivers inhibitory signals on ligand binding [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond soluble Ig fusion proteins of the extracellular parts [PMID:12893276].","affinity_potency":[{"value":"2-6-fold higher affinity than B7-H1/PD-1","assay":"surface plasmon resonance, soluble Ig fusion proteins","system":"human","cite":"PMID:12893276"}],"species_and_systems":"Human recombinant Ig fusions, flow cytometry and SPR [PMID:12893276]; mouse pair ortholog-inferred.","localisation_and_range":"PD-L2 annotated secreted, PD-1 annotated non-secreted [flag]; membrane-bound pair (contact).","caveats":"Abstract only; no absolute affinity in our evidence. Direction listed with PD-1 as ligand; the reverse-direction dossier is G03623.","key_references":[{"PMID":"12893276","why":"SPR comparison of PD-L2 and PD-L1 binding to PD-1."}],"covers":["LR003087","LR006310"]},"LR001207":{"pair":"PENK -> OPRK1","headline":"PENK-derived C-terminally extended peptides bind kappa receptor with high affinity in COS-1 cells; one abstract-only paper, no database records.","interaction_type":"direct binding","direction_and_effect":"C-terminally extended proenkephalin peptides (Met-Enk-Arg-Gly-Leu, Met-Enk-Arg-Phe), Peptide E, BAM peptides and metorphamide have high affinity for kappa; short Leu- and Met-enkephalin are delta selective [PMID:8624732].","molecular_requirements":"The paper proposes an Arg-X-extended core is needed for kappa [PMID:8624732]. The active peptides are processed forms.","affinity_potency":[],"species_and_systems":"Cloned receptors transiently expressed in COS-1 cells; experiment species recorded as human [PMID:8624732]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"PENK is flagged secreted [flag].","caveats":"Abstract only; no numeric affinities in our evidence. Full-length PENK is not tested; short enkephalins are not kappa-selective.","key_references":[{"PMID":"8624732","why":"Opioid peptide binding to cloned mu, delta, kappa receptors"}],"covers":["LR001207","LR004616"]},"LR001216":{"pair":"PGF -> NRP1","headline":"PlGF-2 (heparin-binding isoform) binds NRP1 b1b2 domain, heparin-dependent; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"125I-PlGF-2 co-precipitated with the NRP1 b1b2 domain, competed by VEGF165 [PMID:11986311]. A title states neuropilin-1 is a PlGF-2 receptor [PMID:9712843].","molecular_requirements":"b1b2 domain needed; heparin enhanced PlGF-2 binding 4-fold [PMID:11986311]. Binding in cells was heparin dependent [PMID:9712843].","affinity_potency":[],"species_and_systems":"Soluble Myc-tagged NRP1 domains from mammalian cells [PMID:11986311]; endothelial cross-linking, species unspecified [PMID:9712843]. Pair is ortholog-inferred.","localisation_and_range":"PGF flagged secreted; NRP1 flagged both secreted and transmembrane [flag].","caveats":"Isoform specific to PlGF-2; PlGF-1 marginal [PMID:9712843]. Both abstract only. UniProt agrees [DB:UniProt]; BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"11986311","why":"NRP1 b1b2 binds PlGF-2"},{"PMID":"9712843","why":"PlGF-2 binds neuropilin-1"}],"covers":["LR001216","LR004619"]},"LR003106":{"pair":"PLA2G2A -> ERBB3","headline":"sPLA2-IIa co-immunoprecipitates with HER3 in human cancer cells; one abstract-only paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIa binds EGFR and HER3 by co-immunoprecipitation, suggesting it functions as a ligand for both [PMID:28440478]. Curated direction: agonist, with HER/ERBB-elicited signalling supporting cancer stem cell properties [PMID:28440478]. BioGRID lists Affinity Capture-Western [DB:BioGRID 2524054].","molecular_requirements":"Not reported in our evidence; HER2 association is indirect [PMID:28440478].","affinity_potency":[],"species_and_systems":"Human lung (A549, H1975) and prostate (22Rv1) cancer cells; nude mouse xenografts [PMID:28440478]. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A flag [flag] and elevated tumour interstitial fluid levels [PMID:28440478].","caveats":"Abstract only; co-IP does not exclude intermediaries; no affinity reported [PMID:28440478].","key_references":[{"PMID":"28440478","why":"sPLA2-IIa binds EGFR and HER3 by co-IP"}],"covers":["LR003106","LR006327"]},"LR011233":{"pair":"PLAU -> MRC2","headline":"No judged papers; support is UniProt interaction statements and three pending rows.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says PLAU interacts with MRC2 [DB:UniProt P00749], and MRC2 interacts directly with PLAUR and PLAU/pro-uPA to form a tri-molecular complex [DB:UniProt Q9UBG0].","molecular_requirements":"Tri-molecular complex with uPAR per UniProt [DB:UniProt Q9UBG0]; whether MRC2 binds uPA alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental species or system in our evidence; pair is human.","localisation_and_range":"uPA secreted flag; MRC2 localisation: not reported in our evidence [flag].","caveats":"Three papers are pending and not judged; evidence is database annotation only.","key_references":[],"covers":["LR011233"]},"LR001225":{"pair":"PLAU -> PLAUR","headline":"Well-supported direct binding: uPA (amino-terminal fragment) binds uPAR, with a crystal structure, binding assays and several database records.","interaction_type":"direct binding","direction_and_effect":"uPA binds uPAR; the receptor-binding region lies in the uPA amino-terminal fragment, which inserts into a cavity formed by the three uPAR domains [PMID:16456079]. A peptide from uPA residues 12-32 inhibited receptor binding of labelled ATF, 50% at 100 nM; the paper was read as abstract only [PMID:3031025]. Effect on signalling not reported in our evidence.","molecular_requirements":"The amino-terminal fragment suffices for binding in the structure [PMID:16456079]. Binding sites on uPAR span domains I-III [PMID:11501527]. Single-chain pro-uPA binds without prior conversion to two-chain uPA [PMID:3023326].","affinity_potency":[{"value":"Kd 0.5 nM","assay":"pro-uPA binding to cells","system":"human U937 monocyte-like cells","cite":"PMID:3023326"}],"species_and_systems":"Human experiments throughout (crystal structure, phage display and peptide array, U937 cells) [PMID:16456079][PMID:11501527][PMID:3023326]. Mouse pair is projected from human evidence. PDB structures exist [DB:PDB 2FD6].","localisation_and_range":"Ligand flagged secreted; the receptor carries both secreted and transmembrane flags [flag]. A pro-uPA study indicates secreted pro-uPA reaches the cell-surface receptor [PMID:3023326].","caveats":"All four verified papers were read as abstracts only. UniProt notes that PLAUR can be cleaved and inactivated by its ligand [DB:UniProt].","key_references":[{"PMID":"16456079","why":"1.9 A crystal structure of uPAR with uPA amino-terminal fragment"},{"PMID":"3023326","why":"Kd 0.5 nM pro-uPA binding"},{"PMID":"11501527","why":"maps four uPA-binding regions across uPAR"}],"covers":["LR001225","LR004628"]},"LR003115":{"pair":"PLAUR -> ITGB3","headline":"Direct cell-based binding of soluble uPAR to beta3 (ITGB3) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Binding was to alphavbeta3 [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003115","LR006336"]},"LR001234":{"pair":"PMCH -> MCHR1","headline":"MCH binds and activates MCHR1 with sub-nanomolar affinity in human recombinant cells; well supported, but MCH is also non-selective for MCHR2.","interaction_type":"direct binding","direction_and_effect":"PMCH-derived MCH is a full agonist at MCHR1: it binds SLC-1 (renamed MCHR1) on HEK293 cells, mobilises intracellular Ca2+ and reduces forskolin-elevated cAMP [PMID:10421367]. Signalling via Galphai and/or Galphaq is reported [PMID:10421368]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"A single receptor chain (MCHR1) is sufficient in the reported assays; no co-receptor is described in our evidence. Truncated analogues show a disulfide-cyclic core plus N-terminal Arg is enough for full activation of MCH-1R or MCH-2R [PMID:11478907]. Five PDB complex structures are listed (PDB 8WSS and others) [DB:PDB 8WSS].","affinity_potency":[{"value":"sub-nanomolar affinity","assay":"binding to SLC-1/MCHR1","system":"HEK293 cells, human receptor","cite":"PMID:10421367"},{"value":"pKi 9.7-10.5","assay":"GtoPdb curated affinity","system":"not stated","cite":"PMID:10421367"}],"species_and_systems":"Human receptor and ligand in recombinant HEK293/CHO cells [PMID:10421367][PMID:11478907]; the mouse pair is projected from human evidence (ortholog-inferred), no mouse experiment in our evidence.","localisation_and_range":"Ligand flagged secreted and receptor flagged transmembrane [flag], so paracrine or endocrine signalling to a cell-surface receptor.","caveats":"MCH is a potent but non-selective agonist at MCHR1 and MCHR2 [PMID:11478907][PMID:11839762]. Several papers report data for synthetic analogues rather than native MCH [PMID:11375253][PMID:11839762]. All papers were read as abstracts only.","key_references":[{"PMID":"10421367","why":"MCH binds human MCHR1 with sub-nanomolar affinity and activates it"},{"PMID":"10421368","why":"companion paper, MCH activates SLC-1 signalling"},{"PMID":"11478907","why":"active core of MCH; non-selective at MCHR1/MCHR2"}],"covers":["LR001234","LR004637"]},"LR001243":{"pair":"POMC -> MC5R","headline":"POMC-derived peptides bind and activate MC5R in transfected cells; abstract-level evidence with several peptides.","interaction_type":"direct binding","direction_and_effect":"POMC-derived peptides alpha-MSH, ACTH1-39, ACTH1-17, ACTH1-10 and ACTH4-10 increase cAMP in HEK293 cells with mouse MC5R, and alpha-MSH and ACTH1-17 are most potent [PMID:11785979]. MC5R has higher affinity for alpha-MSH than gamma-MSH and beta-MSH in COS cell binding [PMID:7774675]. GtoPdb lists agonist action [DB:GtoPdb]; a POMC-MC5R structure is in the PDB [DB:PDB 8INR].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd 5.05 +/- 1.00 nmol/l","assay":"[125I][Nle4, D-Phe7]alpha-MSH binding","system":"COS cells; abstract text is ambiguous about which receptor this value belongs to","cite":"PMID:7774675"}],"species_and_systems":"Mouse MC5R in HEK293 cells with human ligand [PMID:11785979]; COS cells with species unspecified [PMID:7774675]. Both read as abstracts only.","localisation_and_range":"POMC flagged secreted, MC5R transmembrane [flag]; range not tested.","caveats":"The Kd value is ambiguous because the abstract labels two receptors as MC3 [PMID:7774675]. Distinct POMC products give different rank orders for cAMP and calcium, so a gene-level pair conflates peptides [PMID:11785979]. Ligand display name is beta-endorphin, not the peptides tested [flag].","key_references":[{"PMID":"11785979","why":"cAMP and calcium responses at mouse MC5R to POMC peptides"},{"PMID":"7774675","why":"Radioligand binding at MC5R"}],"covers":["LR001243","LR004645"]},"LR003124":{"pair":"POSTN -> ITGAV","headline":"Periostin is a ligand for alpha-V integrins, with binding shown for alphaVbeta3/beta5 and in vivo support in mouse haematopoietic stem cells.","interaction_type":"direct binding","direction_and_effect":"Secreted periostin is a ligand for alpha(V)beta(3) and alpha(V)beta(5) integrins and promotes ovarian cancer cell motility [PMID:12235007]. Postn acting through Itgav regulates HSC proliferation; Postn loss raises phenotypic HSC numbers, so the axis restrains proliferation [PMID:27905395].","molecular_requirements":"alphaV pairs with a beta chain; alphaVbeta3 and alphaVbeta5 are named [PMID:12235007]. The HSC paper notes Itgav (CD51) and Itgb3 (CD61) form a heterodimer known to bind Postn [PMID:27905395].","affinity_potency":[],"species_and_systems":"Human ovarian carcinoma cells [PMID:12235007]; mouse bone-marrow HSC in vivo [PMID:27905395]. Both read as abstracts, the second with full-text excerpts.","localisation_and_range":"Periostin is flagged secreted [flag]; matrix and paracrine range not tested beyond the papers.","caveats":"Neither paper reports affinity. The in vivo paper shows a functional link, and the excerpts shown do not themselves demonstrate direct binding [PMID:27905395]. Complex requirement: alphaV needs a beta partner, so score as heterodimer.","key_references":[{"PMID":"12235007","why":"Periostin is a ligand for alphaVbeta3 and alphaVbeta5"},{"PMID":"27905395","why":"Postn-Itgav axis regulates HSC in vivo"}],"covers":["LR003124","LR006345"]},"LR001252":{"pair":"PPY -> NPY5R","headline":"Database-asserted only: GtoPdb lists PP as a full agonist at Y5; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists PP as a full agonist at NPY5R, with affinity in pKi [DB:GtoPdb]; no paper in our evidence shows the effect directly.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence; the GtoPdb record cites PMID 8824284 but no paper was verified. Mouse pair is projected from human.","localisation_and_range":"PPY is flagged secreted and NPY5R transmembrane [flag].","caveats":"No verified papers: seven candidates were abstract_insufficient and one concerned a different entity. Reactome only records that NPY receptors bind NPY-related peptides in general [DB:Reactome]. No affinity value is given in our evidence.","key_references":[],"covers":["LR001252","LR004653"]},"LR003133":{"pair":"PRNP -> ADGRG6","headline":"Functional agonism of ADGRG6 (Gpr126) by the PrP amino-terminal flexible tail, with in vivo zebrafish support; one paper.","interaction_type":"functional only","direction_and_effect":"The PrP(C) flexible tail (residues 23-120) triggered a concentration-dependent cAMP increase in Schwann cells and Adgrg6-overexpressing HEK293T cells; ablating Gpr126 abolished the response [PMID:27501152]. The excerpts also report co-precipitation and increased binding of FT23-50 to Gpr126-expressing cells [PMID:27501152].","molecular_requirements":"The N-terminal flexible tail acts; a KKRPKPG cluster peptide (FT23-50) sufficed, and alanine substitution abolished activity [PMID:27501152].","affinity_potency":[],"species_and_systems":"Mouse Schwann cells and SW10 line, HEK293T cells with human Gpr126, mice and zebrafish [PMID:27501152]; the curator labels species as human.","localisation_and_range":"PRNP is flagged non-secreted and ADGRG6 transmembrane [flag]. The paper proposes PrP(C) acts in trans on Schwann cells [PMID:27501152].","caveats":"Evidence is mostly functional cAMP data with a fragment peptide; full-length PrP binding affinity is not reported. A third paper was review_only. Agonism is by the flexible tail, not shown for intact PrP.","key_references":[{"PMID":"27501152","why":"PrP flexible tail activates Gpr126 cAMP signalling"}],"covers":["LR003133","LR006354"]},"LR001261":{"pair":"PROS1 -> AXL","headline":"PROS1 binds and activates AXL in glioblastoma stem-like cells; one full-text paper plus a 1995 identification of TAM ligands; one caveat on prior literature.","interaction_type":"direct binding","direction_and_effect":"PROS1 secreted by tumour-associated macrophages/microglia was co-immunoprecipitated with AXL and recombinant PROS1 raised phosphorylated AXL, not total AXL, then p65/NF-kB activation, which BGB324 blocked [PMID:29531161]. Agonist action; the 1995 paper identified protein S and Gas6 as ligands of the Tyro 3/Axl family [PMID:7867073].","molecular_requirements":"Not reported in our evidence for subunits or co-receptors. A PROS1 blocking peptide reduced AXL phosphorylation by macrophage-conditioned medium [PMID:29531161].","affinity_potency":[],"species_and_systems":"Human patient-derived mesenchymal glioma stem-like cells, plus mouse tumour models, for PMID 29531161; 1995 paper used human proteins in vitro [PMID:7867073]. Mouse pair is ortholog-inferred.","localisation_and_range":"PROS1 is annotated secreted [flag]; the 2018 paper shows macrophage/microglia-derived PROS1 acting on tumour cells [PMID:29531161], so paracrine.","caveats":"The 2018 paper itself states that GAS6 was previously the only known AXL ligand, so this is a context-specific report from one lab [PMID:29531161]. The 1995 paper is abstract-only and names both Tyro 3 and Axl without separating them [PMID:7867073]. Co-IP used lysates with His-tagged PROS1, not purified binding.","key_references":[{"PMID":"29531161","why":"PROS1 co-IP with AXL, AXL phosphorylation and NF-kB in glioma stem cells."},{"PMID":"7867073","why":"Protein S and Gas6 identified as Tyro3/Axl family ligands."}],"covers":["LR001261","LR004661"]},"LR003142":{"pair":"PSAP -> MRC1","headline":"Mannose receptor takes up prosaposin precursor in mice in vivo; one paper, abstract-level, no direct binding shown.","interaction_type":"functional only","direction_and_effect":"In mice the mannose receptor system on macrophages participates in SAP precursor internalisation, and it removed intravenously injected precursor from blood into liver [PMID:9707421].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vivo experiments in mice; curator notes browser-read Discussion with spot-check pending [PMID:9707421].","localisation_and_range":"Ligand is flagged secreted and receptor transmembrane [flag]; precursor clearance is endocytic uptake.","caveats":"No direct binding measurement in the dossier; the quote is a curator browser read not yet spot-checked; paper abstract only in our record. Endocytic clearance, not signalling.","key_references":[{"PMID":"9707421","why":"In vivo mouse clearance of SAP precursor via mannose receptor."}],"covers":["LR003142","LR006363"]},"LR001270":{"pair":"PTH2 -> PTH2R","headline":"TIP39 (PTH2 gene product) is a well-supported agonist of PTH2R, with binding and cAMP data in recombinant cells.","interaction_type":"direct binding","direction_and_effect":"TIP39 is an agonist at PTH2R: a PTH1R/PTH2R chimera carrying the PTH2R juxtamembrane domain was fully activated by TIP39 (EC50 = 2.0 nm) [PMID:10854439]. TIP39 stimulates cAMP accumulation in PTH2R-expressing cells but is inactive at PTH1R [PMID:11159842]. TIP-(9-39) inhibited cAMP accumulation stimulated by agonists [PMID:11861531]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The PTH2R juxtamembrane domain specifies TIP39 signalling and binding selectivity over PTH1R [PMID:10854439]. Removing six N-terminal TIP39 residues eliminated PTH2R activation and reduced binding affinity 70-fold [PMID:10854439]. Co-receptors are not reported in our evidence.","affinity_potency":[{"value":"Kd 2.0 nM","assay":"TIP39 binding to wild-type PTH2 receptor","system":"recombinant PTH2R (human, as reported)","cite":"PMID:10854439"},{"value":"EC50 0.54 nM (human TIP39)","assay":"cAMP accumulation","system":"LLCPK1 cells expressing human PTH2 receptor","cite":"PMID:11861531"}],"species_and_systems":"Experiments are human ligand with human receptor in recombinant cells; PMID:11602681 used chimeric human/rat receptors [PMID:11602681]. Mouse pair is projected from human evidence (ortholog-inferred); mouse TIP39 also tested on the human receptor [PMID:11861531].","localisation_and_range":"TIP39 is flagged as secreted and PTH2R as transmembrane [flag]; range is therefore paracrine or endocrine.","caveats":"All four papers were read as abstracts only. TIP39 also binds PTH1R weakly (apparent 243 +/- 52 nM) and acts as an antagonist there [PMID:11159842]; PMID:11602681 mainly concerns PTH rather than TIP39.","key_references":[{"PMID":"10854439","why":"TIP39 binding and activation of PTH2R, juxtamembrane selectivity"},{"PMID":"11861531","why":"Human and mouse TIP39 potency at human PTH2R"},{"PMID":"11159842","why":"TIP39 agonist at PTH2R, antagonist at PTH1R"}],"covers":["LR001270","LR004670"]},"LR003151":{"pair":"PTN -> NRP1","headline":"PTN binds NRP1 directly and needs it for signalling and migration in human cells.","interaction_type":"direct binding","direction_and_effect":"NRP-1 is needed for PTN-induced MAPK and focal adhesion kinase signalling, HUVEC migration and tumour-cell invasion; NRP-1 silencing or blocking antibody inhibited them [PMID:26408254]. PTN binding stimulated NRP-1 internalisation and recycling [PMID:26408254].","molecular_requirements":"PTN interacts via its thrombospondin type-I repeat (TSR-I) domains [PMID:26408254]. PTN bound immobilised recombinant NRP-1 in an ELISA, and NRP-1 co-immunoprecipitated with PTN in PC3, MDA-MB231 and HUVEC cells [PMID:26408254]. PTN may also bind cells through ALK and RPTPbeta/zeta [PMID:26408254].","affinity_potency":[],"species_and_systems":"Human carcinoma cells and HUVEC; CHO cells lack NRP-1 [PMID:26408254]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. NRP1 is flagged as transmembrane [flag].","caveats":"Single paper, no affinity reported. Co-immunoprecipitation could reflect indirect interaction, but the ELISA supports direct binding [PMID:26408254].","key_references":[{"PMID":"26408254","why":"PTN-NRP-1 direct binding and role in PTN signalling"}],"covers":["LR003151","LR006372"]},"LR003160":{"pair":"PTPRD -> SLITRK1","headline":"PTPRD and SLITRK1 aggregate cells in a mouse assay and have a co-crystal structure in databases; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Slitrk1-expressing L cells specifically aggregated with PTP-delta-expressing L cells; the paper concludes Slitrks need LAR-RPTP family members to trigger synapse formation, with PTP-delta needed for inhibitory synapse differentiation [PMID:23345436]. Agonist or antagonist effect on PTPRD is not reported in our evidence.","molecular_requirements":"Not reported for single subunits; the databases hold a co-crystal structure and a reconstituted complex of SLITRK1 and PTPRD [DB:BioGRID] [DB:PDB 4RCA].","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells, plus rat brain data in the abstract [PMID:23345436]. Human and mouse pairs are both listed; the mouse pair is projected from human (ortholog-inferred).","localisation_and_range":"Both proteins are flagged transmembrane (SLITRK1 is also flagged secreted) [flag]; adhesion between cells implies contact-dependent (juxtacrine) action [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check. The BioGRID/PDB records cite PMID 25394468, which is not among the judged papers.","key_references":[{"PMID":"23345436","why":"Cell-aggregation assay between Slitrk and PTP-delta cells"}],"covers":["LR003160","LR006381"]},"LR006400":{"pair":"RBP4 -> TLR4","headline":"RBP4 is reported to prime the NLRP3 inflammasome through TLR4/MD2 and TLR2 in adipose tissue; a single abstract-only functional paper.","interaction_type":"functional only","direction_and_effect":"RBP4 primes the NLRP3 inflammasome for IL1beta release, in a glucose-dependent manner, through the TLR4/MD2 receptor complex and TLR2, impairing insulin signaling in adipocytes [PMID:33214151].","molecular_requirements":"The TLR4/MD2 complex and TLR2 are named; which is required is not reported in our evidence. Holo- or apo-RBP4 injection both caused insulin resistance [PMID:33214151].","affinity_potency":[],"species_and_systems":"Mice (RBP4-overexpressing and wild-type, injections, TLR4 inhibition) and adipocytes; curators label human/human but the abstract describes mouse work [PMID:33214151].","localisation_and_range":"RBP4 is flagged secreted [flag].","caveats":"Only functional evidence, no direct binding to TLR4 shown in our evidence. Paper read as abstract only; TLR4 inhibition effects do not prove direct ligand-receptor binding. No database support.","key_references":[{"PMID":"33214151","why":"RBP4 primes NLRP3 via TLR4/MD2 and TLR2"}],"covers":["LR003180","LR006400"]},"LR008989":{"pair":"RGMB -> BMPR1B","headline":"No verified paper; support is database-only (BioGRID and UniProt), as a receptor-receptor class pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. UniProt says RGMB interacts with BMP type I receptors including BMPR1B (by similarity) [DB:UniProt].","molecular_requirements":"UniProt also lists ACVR1, BMPR1A and ACVR2B as partners [DB:UniProt].","affinity_potency":[],"species_and_systems":"BioGRID records an affinity capture-Western result [DB:BioGRID]; species and system not reported in our evidence.","localisation_and_range":"RGMB is not flagged secreted [flag]; the class is Receptor-Receptor.","caveats":"No curator-confirmed paper; the only judged paper was review_only; the UniProt statement is by similarity.","key_references":[],"covers":["LR008989"]},"LR012412":{"pair":"ROR1 -> FZD6","headline":"ROR1 and FZD6 complexes detected by proximity ligation in PC-3 cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PLA detected FZD6-ROR1 complexes as fluorescent spots (siRNA-verified), and Wnt5A stimulation increased the number of FZD6-ROR1 complexes after 2 min [PMID:34769487]. Elevated phosphorylated MYPT1 suggested subsequent Wnt/PCP activation.","molecular_requirements":"ROR1 acts as a non-canonical co-receptor for FZD6, while LRP6 is the canonical co-receptor [PMID:34769487].","affinity_potency":[],"species_and_systems":"Endogenous proteins in human PC-3 prostate cancer cells, stimulated with Wnt5A or Wnt10B [PMID:34769487].","localisation_and_range":"Both cell-surface receptors; juxtamembrane proximity [PMID:34769487].","caveats":"Abstract only. PLA shows proximity, not direct binding. One cell line. Two other candidate rows judged as different entities.","key_references":[{"PMID":"34769487","why":"Endogenous FZD6-ROR1 PLA with Wnt5A-dependent increase"}],"covers":["LR012412"]},"LR001306":{"pair":"RSPO1 -> FZD8","headline":"RSPO1 physically interacts with the FZD8 ectodomain per one abstract-only paper that used the R-spondin family.","interaction_type":"direct binding","direction_and_effect":"Cristin/R-spondin proteins physically interacted with the extracellular domains of LRP6 and Fzd8 in vivo and in vitro and induced TCF reporter activity and beta-catenin stabilisation [PMID:16543246].","molecular_requirements":"R-spondin failed to form a ternary complex with both LRP6 and Fzd8 together [PMID:16543246].","affinity_potency":[],"species_and_systems":"Mouse cristin/R-spondin proteins [PMID:16543246]; human pair ortholog-inferred.","localisation_and_range":"RSPO1 secreted per flag; FZD8 non-secreted receptor [flag].","caveats":"Abstract only. Family-level result, not paralogue-resolved for RSPO1.","key_references":[{"PMID":"16543246","why":"R-spondin family binds Fzd8 and LRP6 ectodomains"}],"covers":["LR001306","LR004703"]},"LR001315":{"pair":"RSPO3 -> FZD8","headline":"Cristin/R-spondin proteins bind the FZD8 ectodomain in one abstract-only paper; RSPO3 itself is covered only as a family member.","interaction_type":"direct binding","direction_and_effect":"Cristin/R-spondin proteins act as FZD8 ligands and induce canonical Wnt/beta-catenin signalling, with TCF reporter activity and beta-catenin stabilisation [PMID:16543246].","molecular_requirements":"The proteins physically interacted with the extracellular domains of LRP6 and Fzd8 in vivo and in vitro, but failed to form a ternary complex with both together [PMID:16543246].","affinity_potency":[],"species_and_systems":"Mouse Cristin/R-spondin proteins per the title; assay system not otherwise reported in our evidence. The human pair is ortholog-inferred, the mouse pair is not [PMID:16543246].","localisation_and_range":"RSPO3 is flagged secreted [flag], so a paracrine or autocrine ligand; FZD8 is flagged as a receptor [flag].","caveats":"Family-level result: the experiments do not resolve RSPO3 from other R-spondin paralogues. Abstract only. No database records support this pair.","key_references":[{"PMID":"16543246","why":"Cristin/R-spondin family binds Fzd8 and LRP6 ectodomains and activates beta-catenin signalling"}],"covers":["LR001315","LR004712"]},"LR001324":{"pair":"RTN4 -> CNTNAP1","headline":"Nogo-66 appears to bind Caspr (CNTNAP1) directly in trans at CNS paranodes, in one abstract-only rat paper.","interaction_type":"direct binding","direction_and_effect":"Nogo-A interacts in trans with axonal Caspr at CNS paranodes, with possible roles in axon-glial junction architecture and K+ channel localisation [PMID:14592966]. Activating or inhibitory effect is not reported.","molecular_requirements":"CHO cells cotransfected with Caspr and F3 bound Nogo-66 peptide and GST-Nogo-66 substrates, F3 alone did not; binding persisted after PI-PLC removal of GPI-linked F3, suggesting direct Nogo-66-Caspr interaction [PMID:14592966].","affinity_potency":[],"species_and_systems":"Rat tissue and CHO cells; EAE rats and Shiverer and CGT-/- mice for pathology [PMID:14592966].","localisation_and_range":"Membrane-bound juxtacrine contact at paranodes (oligodendroglial Nogo-A with axonal Caspr) [PMID:14592966]; RTN4 flagged non-secreted [flag].","caveats":"Abstract only; no affinity. Binding was tested with Nogo-66 peptide in cell-substrate assays, not purified protein affinity. BioGRID lists affinity capture-Western records from the same paper [DB:BioGRID]. Distinct from the canonical NgR pathway.","key_references":[{"PMID":"14592966","why":"Nogo-A/Nogo-66 binds Caspr at paranodes"}],"covers":["LR001324","LR004721"]},"LR003205":{"pair":"S100A1 -> AGER","headline":"S100A1 binds the RAGE V domain in an NMR and modelling study (Kd about 6 uM); one paper plus database records.","interaction_type":"direct binding","direction_and_effect":"S100A1 binds the hydrophobic surface of the RAGE V domain, which is described as triggering signalling cascades for cell growth, proliferation and tumorigenesis (stated as background) [PMID:29444082]. S100B binds S100A1 and is modelled to block the S100A1-V domain site, acting as an antagonist; a WST-1 proliferation assay supports this [PMID:29444082]. UniProt lists S100 proteins among RAGE ligands [DB:UniProt].","molecular_requirements":"The RAGE V domain alone was used; residues K39, R48, W51, K52, L53, D93, F97, K110 and V115 map the interface, and the HADDOCK model is a heterotetramer with S100A1 as a dimer, Ca2+-bound [PMID:29444082]. Full-length receptor requirements are not reported.","affinity_potency":[{"value":"Kd 6.13 +/- 1.29 uM","assay":"NMR 1H-15N HSQC titration, S100A1 with RAGE V domain","system":"recombinant proteins","cite":"PMID:29444082"}],"species_and_systems":"Human recombinant S100A1 and RAGE V domain in vitro (NMR, HADDOCK model) [PMID:29444082]. IntAct holds an SPR record for this pair [DB:IntAct].","localisation_and_range":"S100A1 carries a secreted flag, suggesting paracrine signalling to a cell-surface receptor [flag].","caveats":"Isolated V domain, not full-length RAGE; the abstract states the S100A1-RAGE V binding as established background and the structure is a docking model. Kd given as mean over selected residues.","key_references":[{"PMID":"29444082","why":"NMR mapping and Kd of S100A1 with RAGE V domain"}],"covers":["LR003205","LR006425"]},"LR003214":{"pair":"S100A4 -> ANXA2","headline":"S100A4 binds annexin A2 in structural and binding studies; annexin II acts as a plasminogen co-receptor scaffold rather than a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Extracellular S100A4 binds annexin II and accelerates tPA-mediated plasminogen activation to plasmin on endothelial cells [PMID:15788416]. In the crystal structure, S100A4 binding dislocates the ANXA2 N-terminal domain and unmasks the concave side [PMID:28669632].","molecular_requirements":"The binding site lies in the N-terminal region of annexin II; an N-terminal peptide blocked S100A4-induced plasmin formation [PMID:15788416]. Plasmin acceleration also needs S100A4 C-terminal lysines and plasminogen [PMID:15788416].","affinity_potency":[],"species_and_systems":"Human proteins; endothelial cell culture and crystal structure [PMID:15788416][PMID:28669632]. Structures PDB 5LPU and 6T58 contain both chains [DB:PDB 5LPU][DB:PDB 6T58]. UniProt lists the interaction [DB:UniProt].","localisation_and_range":"S100A4 and ANXA2 are both flagged secreted [flag]; the paper describes extracellular S100A4 acting at the endothelial surface [PMID:15788416].","caveats":"Both papers read as abstracts only. No affinity reported in our evidence. ANXA2 is a scaffold, not a signalling receptor.","key_references":[{"PMID":"15788416","why":"Direct S100A4-annexin II binding and plasmin formation"},{"PMID":"28669632","why":"ANXA2-S100A4 complex crystal structure"}],"covers":["LR003214","LR006432"]},"LR003223":{"pair":"S100A8 -> AGER","headline":"In diabetic mice S100A8/A9 acts through RAGE on Kupffer cells to raise IL-6; evidence is for the S100A8/A9 pair, functional.","interaction_type":"functional only","direction_and_effect":"Neutrophil-derived S100A8/A9 interact with RAGE on hepatic Kupffer cells, increasing IL-6 and causing thrombocytosis; paquinimod, which inhibits S100A8/A9-RAGE binding, reduced thrombocytosis and atherogenesis [PMID:28504650].","molecular_requirements":"Evidence is for the S100A8/A9 complex; S100A8 alone is not separated [PMID:28504650].","affinity_potency":[],"species_and_systems":"Diabetic mice and type 2 diabetes patients [PMID:28504650]. Human pair is projected from mouse evidence.","localisation_and_range":"S100A8 is flagged secreted [flag].","caveats":"Abstract only; no binding assay or affinity in our evidence. Human pair is ortholog-inferred.","key_references":[{"PMID":"28504650","why":"S100A8/A9-RAGE axis in diabetic thrombocytosis"}],"covers":["LR003223","LR006440"]},"LR003232":{"pair":"S100A9 -> AGER","headline":"S100A8/A9 interacts with RAGE in a diabetic mouse model (abstract-only); pharmacological blockade, no binding assay.","interaction_type":"functional only","direction_and_effect":"In hyperglycaemic mice, neutrophil-derived S100A8/A9 interact with RAGE on hepatic Kupffer cells, increasing IL-6 and driving thrombocytosis; inhibiting S100A8/A9 binding to RAGE with paquinimod reduced thrombocytosis and atherogenesis [PMID:28504650]. UniProt states S100A9 binds TLR4 and AGER as an alarmin [DB:UniProt]. Agonist-like.","molecular_requirements":"The evidence concerns the S100A8/A9 complex, not S100A9 alone [PMID:28504650].","affinity_potency":[],"species_and_systems":"Diabetic mouse model and human type 2 diabetes plasma samples; the human pair is ortholog-inferred and the mouse pair is not [PMID:28504650].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. RAGE acts on Kupffer cells [PMID:28504650].","caveats":"Abstract only. Curator label direct_binding rests on pharmacological blockade; no direct binding data. UniProt text is a general function statement.","key_references":[{"PMID":"28504650","why":"S100A8/A9-RAGE axis in diabetic thrombocytosis, paquinimod blockade"}],"covers":["LR003232","LR006449"]},"LR003241":{"pair":"S100B -> AGER","headline":"S100B-RAGE is well supported: crystal structure, micromolar affinity, database binding records and functional work.","interaction_type":"direct binding","direction_and_effect":"S100B is recognized via the amino-terminal V-domain of RAGE; a 2.55 A crystal structure of S100B with a V-domain peptide (residues 54-68) shows two S100B dimers per peptide [PMID:25945582]. Structures are recorded in PDB [DB:PDB 4XYN] [DB:PDB 5D7F], with BioGRID, IntAct and UniProt interaction records [DB:BioGRID] [DB:IntAct] [DB:UniProt]. S100B triggers inflammation through RAGE [PMID:25945582]. Agonist. A second paper reports an additional S100B receptor, ALCAM, active in RAGE-/- cells [PMID:23729438].","molecular_requirements":"The V-domain is the recognition element [PMID:25945582].","affinity_potency":[{"value":"Kd 2.7 +/- 0.5 microM (wild-type V-domain); 1.3 +/- 0.7 microM (W61A mutant)","assay":"fluorescence titration","system":"S100B with intact RAGE V-domain, in vitro","cite":"PMID:25945582"}],"species_and_systems":"Human proteins in vitro [PMID:25945582]; mouse endothelial cells for the second paper [PMID:23729438].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. RAGE is flagged as a receptor [flag].","caveats":"Affinity values are reported as '2.7\u00b10.5' and '1.3\u00b10.7' microM in the abstract; structure used a peptide not full receptor. Abstracts only.","key_references":[{"PMID":"25945582","why":"Crystal structure and affinities of S100B with RAGE V-domain"},{"PMID":"23729438","why":"S100B also signals via ALCAM in RAGE-/- cells"}],"covers":["LR003241","LR006457"]},"LR005014":{"pair":"Sbpl -> Tlr6","headline":"PAUF associated with TLR6 in a co-immunoprecipitation panel; thin, binding-only evidence.","interaction_type":"direct binding","direction_and_effect":"In co-IP assays in HEK293T cells PAUF associated with TLR2, 5 and 6 but not with TLR3, 8, 9 or 10 [PMID:20802527]. No functional effect through TLR6 is reported in our evidence.","molecular_requirements":"TLR6 might act with TLR2; not tested in our evidence.","affinity_potency":[],"species_and_systems":"HEK293T co-IP; The paper calls the protein PAUF; curators mapped it to Sbpl, and the mouse pair is ortholog-inferred. [PMID:20802527]","localisation_and_range":"PAUF is secreted [flag].","caveats":"Single co-IP result from a supplementary figure; association is not proof of direct binding. The paper's text lists the positive TLRs inconsistently [PMID:20802527].","key_references":[{"PMID":"20802527","why":"Co-IP panel of PAUF against TLR family members"}],"covers":["LR005014"]},"LR001333":{"pair":"SCGB1A1 -> LRP2","headline":"Megalin is a co-receptor needed for CCSP uptake with cubilin, but does not bind CCSP itself; indirect evidence.","interaction_type":"functional only","direction_and_effect":"Internalization of CCSP was blocked by antibodies against megalin, and megalin-deficient mice showed defective tubular uptake and urinary CCSP excretion [PMID:11278724]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Megalin is described as an endocytic receptor that does not bind CCSP but associates with cubilin, acting as a coreceptor for cubilin-mediated uptake [PMID:11278724].","affinity_potency":[],"species_and_systems":"Human CCSP in cultured cells with megalin antibodies; mouse megalin-deficient animals [PMID:11278724].","localisation_and_range":"CCSP is secreted [flag]; renal proximal tubule uptake.","caveats":"Per the abstract, megalin does not bind CCSP directly, so a ligand-receptor edge depends on cubilin. Abstract only. A second confirmed paper is not shown.","key_references":[{"PMID":"11278724","why":"Megalin as endocytic coreceptor for cubilin-bound CCSP"}],"covers":["LR001333","LR004729"]},"LR007999":{"pair":"SDC2 -> FGFR4","headline":"No verified paper evidence; only an IntAct SPR record supports this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. IntAct lists a surface plasmon resonance interaction between the two proteins [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence beyond the IntAct record.","localisation_and_range":"SDC2 is flagged transmembrane and not secreted; FGFR4 is flagged secreted, receptor and transmembrane [flag].","caveats":"Two papers were judged abstract_insufficient and none confirmed, so support rests on one database record [DB:IntAct]. No affinity is reported.","key_references":[],"covers":["LR007999"]},"LR001342":{"pair":"SEMA3A -> PLXNA1","headline":"SEMA3A signals via a NRP1/PlexinA1 complex in cells; PlexinA1 alone does not bind Sema3A.","interaction_type":"direct binding","direction_and_effect":"Sema3A interaction with NP-1/Plex 1 complexes induces adherent cells to round up, and dominant-negative Plex 1 in sensory neurons blocks Sema3A-induced growth cone collapse [PMID:10520994]. Sema3 signals are transduced equally effectively by PlexinA1 or PlexinA2 [PMID:11239433]. Interaction class is stimulatory [flag].","molecular_requirements":"Plex 1 alone does not bind Sema3A; the NP-1/Plex 1 complex has higher affinity for Sema3A than NP-1 alone [PMID:10520994]. Sema3A/NP1 releases PlexinA1 sema-domain autoinhibition [PMID:11239433]. Reactome: Sema3A binds Nrp-1 bound to PlexinA [DB:Reactome].","affinity_potency":[{"value":"6-fold higher affinity","assay":"AP-Sema3A binding, NP-1/Plex 1 cells versus NP-1 cells","system":"COS-7 cells","cite":"PMID:10520994"}],"species_and_systems":"Experiments used mouse-labelled proteins in COS-7 cells and DRG neurons (chick E7 DRG in [PMID:11239433]); the human pair is projected from mouse [flag].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"Binding is to the NRP1/PlexinA1 complex, not PlexinA1 alone, so PLXNA1 on its own is not shown as a receptor. Evidence for direct binding in this pair rests on complex assays.","key_references":[{"PMID":"10520994","why":"NP-1/Plex 1 complex is the high-affinity Sema3A receptor"},{"PMID":"11239433","why":"PlexinA1 activation and autoinhibition in Sema3A signalling"}],"covers":["LR001342","LR004738"]},"LR001351":{"pair":"SEMA3D -> NRP1","headline":"Zebrafish in vivo knockdown data (two papers, abstract-level) support SEMA3D acting through Nrp1 for repulsion and actin stabilization.","interaction_type":"functional only","direction_and_effect":"In zebrafish, Sema3D may act as a repellent through receptors containing Npn-1A and as an attractant via Npn-1A plus Npn-2B [PMID:15456815]. Separately, autocrine Sema3d signaling through Neuropilin1 regulates actin organization via RhoA upstream of Rock, stabilizing the endothelial sheet [PMID:27799363].","molecular_requirements":"Npn-1A alone is tied to nucMLF repulsion; Npn-1A plus Npn-2B to attraction [PMID:15456815]. The endothelial Nrp1 effect was independent of PlxnD1 [PMID:27799363].","affinity_potency":[],"species_and_systems":"Zebrafish morpholino and mutant embryos in both papers; the curator's species label says human for PMID 27799363, but the text describes zebrafish [PMID:27799363]. The human and mouse pairs are ortholog-inferred.","localisation_and_range":"SEMA3D is annotated secreted [flag]; autocrine and mesenchymal paracrine sources are described [PMID:27799363].","caveats":"Both papers read as abstracts (the second has full-text excerpts); genetic knockdown, no binding or affinity data. One review_only row is not shown.","key_references":[{"PMID":"15456815","why":"Zebrafish Sema3D repulsion and attraction via Npn-1A and Npn-2B"},{"PMID":"27799363","why":"Sema3d-Nrp1 autocrine actin control in endothelial migration"}],"covers":["LR001351","LR004747"]},"LR001360":{"pair":"SEMA4C -> PLXNB2","headline":"Sema4C binds Plexin-B2 and signals through it in cerebellar development and breast cancer cells; binding plus functional evidence.","interaction_type":"direct binding","direction_and_effect":"Sema4C protein bound Plexin-B2-expressing cerebellar granule cells; Sema4C promoted granule-cell migration in transwell and explant assays, and had no effect on Plxnb2-/- cells, so the effect needs Plexin-B2 (agonist) [PMID:21122816]. In breast cancer cells, Sema4C/PlexinB2/LARG signalling maintains RhoA-GTP and cell growth [PMID:29555978].","molecular_requirements":"Binding to Plexin-B2 was strong, to Plexin-B1 weaker, none to Plexin-B3 in full-text excerpts [PMID:21122816]. Downstream, LARG, ErbB2 and RhoA-dependent kinases are named effectors [PMID:29555978].","affinity_potency":[],"species_and_systems":"Cerebellar work used mouse knockouts and mouse cells (dossier labels species human) [PMID:21122816]; breast cancer work used human mammary carcinoma cells and mice [PMID:29555978]. Human pair is ortholog-inferred.","localisation_and_range":"Sema4C is flagged transmembrane, not secreted [flag]; contact-dependent signalling is likely but substrate-coated assays used a recombinant protein [PMID:21122816].","caveats":"Binding paper read from abstract and excerpts; breast cancer paper abstract only. Sema4C-/- phenotype partial penetrance and other Plexin-B2 ligands likely exist [PMID:21122816]. IntAct has one solid-phase assay record [DB:IntAct].","key_references":[{"PMID":"21122816","why":"Binding and knockout genetics for Sema4C-Plexin-B2"},{"PMID":"29555978","why":"Sema4C/PlexinB2 signalling in breast cancer"}],"covers":["LR001360","LR004756"]},"LR005302":{"pair":"SERPINF1 -> PLXDC2","headline":"PEDF binds the extracellular domain of PLXDC2 and PLXDC2 mediates cell-type-specific PEDF responses.","interaction_type":"direct binding","direction_and_effect":"PLXDC1 and PLXDC2 were identified as cell-surface receptors for PEDF; knockdown of either decreased PEDF response in RAW267.4 cells [PMID:25535841]. PEDF is reported to dissociate basal receptor homooligomers to activate them [PMID:25535841].","molecular_requirements":"Biotinylated PEDF bound HEK293 cells expressing PLXDC2, with extracellular-domain and intracellular-domain deleted constructs as controls [PMID:25535841].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells and mouse-derived cell lines named in the excerpts [PMID:25535841]; dossier labels species human. Mouse pair is ortholog-projected from human.","localisation_and_range":"PEDF is flagged secreted [flag]; PLXDC2 acts as a cell-surface receptor in the paper [PMID:25535841].","caveats":"Single paper; no affinity reported; the same evidence supports PLXDC1.","key_references":[{"PMID":"25535841","why":"Identifies PLXDC1 and PLXDC2 as PEDF receptors"}],"covers":["LR001972","LR005302"]},"LR005311":{"pair":"SLAMF6 -> SLAMF6","headline":"SLAMF6 (NTB-A) is reported as its own ligand in a human NK-cell paper; supported by IntAct and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Trimeric recombinant NTB-A showed that NTB-A is its own ligand; homophilic engagement enhanced NK cell cytotoxicity and influenced proliferation and IFN-gamma secretion [PMID:15153464].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NK cells and recombinant trimeric proteins [PMID:15153464].","localisation_and_range":"Not flagged secreted; a surface receptor on NK, T and B cells, so contact-dependent [PMID:15153464].","caveats":"Abstract only; no affinity. IntAct lists FACS and solid phase records and Reactome a SLAMF6 dimer and binding reaction [DB:IntAct] [DB:Reactome]. One further row is pending and not described.","key_references":[{"PMID":"15153464","why":"NTB-A homophilic ligand; enhances NK cytotoxicity"}],"covers":["LR001982","LR005311"]},"LR003313":{"pair":"SLIT2 -> PLXNA1","headline":"SLIT2 (C-terminal fragment) binds PlexinA1 by co-immunoprecipitation; one paper, human pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Full-length Slit2 and Slit2C coimmunoprecipitated with PlexinA1, Slit2N did not [PMID:25485759]. The abstract reports PlexinA1 transduces a SlitC signal independently of Robos and Neuropilins and elicits a repulsive commissural response ex vivo [PMID:25485759].","molecular_requirements":"The C-terminal Slit fragment is the binding form; N-terminal fragment does not bind [PMID:25485759].","affinity_potency":[],"species_and_systems":"COS7 coimmunoprecipitation; ex vivo spinal cord commissural axons and knockout mice (species of the knockout work not stated in the excerpt) [PMID:25485759].","localisation_and_range":"SLIT2 flagged secreted [flag]; PlexinA1-SlitC complexes were detected in spinal cord extracts [PMID:25485759].","caveats":"Coimmunoprecipitation quote was browser-read and its spot-check is pending. Two other rows were judged a different entity and three abstracts insufficient. No affinity.","key_references":[{"PMID":"25485759","why":"PlexinA1 as Slit C-terminal receptor"}],"covers":["LR003313"]},"LR005320":{"pair":"SLITRK2 -> PTPRS","headline":"SLITRK2-PTPsigma rests on one family-level cell aggregation assay.","interaction_type":"functional only","direction_and_effect":"Slitrk2-expressing cells aggregated with PTPsigma-expressing cells [PMID:23345436]. PTPsigma was specifically required for excitatory synaptic differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L cells and rat neurons [PMID:23345436]. Mouse pair ortholog-inferred.","localisation_and_range":"Cell-contact adhesion; SLITRK2 flagged transmembrane [flag].","caveats":"Single paper, browser-read quote with spot-check pending; assay is family-wide, direct binding not reported in our evidence. Four review-only rows not shown.","key_references":[{"PMID":"23345436","why":"Slitrk2 and PTPsigma aggregation"}],"covers":["LR001991","LR005320"]},"LR003322":{"pair":"SLURP2 -> CHRNB2","headline":"SLURP-2 co-purifies the beta2 nAChR subunit and inhibits alpha4beta2 and alpha3beta2 currents; one paper.","interaction_type":"direct binding","direction_and_effect":"SLURP-2 inhibits ACh-evoked currents at alpha4beta2 and alpha3beta2 nAChRs; in keratinocytes, interaction with alpha3beta2 promoted proliferation [PMID:27485575].","molecular_requirements":"Beta2 pairs with alpha3 or alpha4 in the functional tests; beta2 alone was not tested for function. Binding was shown at subunit level by affinity purification [PMID:27485575].","affinity_potency":[{"value":"IC50 >3 \u03bcM","assay":"inhibition of ACh-evoked current, alpha3beta2 nAChR","system":"Xenopus oocytes, human receptor","cite":"PMID:27485575"}],"species_and_systems":"Recombinant human SLURP-2 (rSLURP-2); human receptors in Xenopus oocytes and CHO cells, affinity purification from cortical brain extracts, and human oral keratinocyte Het-1A cells [PMID:27485575]. Species of the brain extract is not reported in our evidence.","localisation_and_range":"SLURP2 is flagged as secreted [flag]; the receptor is flagged as a receptor [flag]. Range is not discussed in our evidence.","caveats":"Subunit-level evidence from tissue extract. The abstract gives an alpha4beta2 IC50 of ~0.17 \u03bcM [PMID:27485575]. Single paper.","key_references":[{"PMID":"27485575","why":"Recombinant SLURP-2 pharmacology and binding to acetylcholine receptors"}],"covers":["LR003322"]},"LR002008":{"pair":"SPON2 -> ITGB1","headline":"Mindin engages beta1 integrins in DC adhesion and HCC signalling; antibody and knockout evidence, abstract only.","interaction_type":"functional only","direction_and_effect":"DCs lacking beta1 integrin had reduced adhesion to mindin matrix, with reduced Rac1/2 expression and priming capacity [PMID:16917498]. SPON2-alpha4beta1 signalling activated RhoA and Rac1 and promoted M1-like macrophage recruitment [PMID:29440144].","molecular_requirements":"beta1 pairs with alpha4 and alpha5 in these reports [PMID:16917498] [PMID:29440144]. beta1 alone is not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Mouse DCs, including genetic beta1-null DCs [PMID:16917498]; HCC context [PMID:29440144].","localisation_and_range":"Mindin is an extracellular matrix protein [flag].","caveats":"Abstracts only; adhesion is blocked, not binding measured directly. No affinity. The beta1 chain is evidence in complexes with alpha4 or alpha5.","key_references":[{"PMID":"16917498","why":"beta1-null DCs adhere less to mindin"},{"PMID":"29440144","why":"SPON2-alpha4beta1 signalling"}],"covers":["LR002008","LR005336"]},"LR001405":{"pair":"SPP1 -> ITGA4","headline":"Thrombin-cleaved osteopontin acts on alpha4beta1 and alpha9beta1 integrins in hemopoietic stem cells; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"The N-terminal thrombin cleavage fragment of OPN, through binding to alpha9beta1 and alpha4beta1, attracts and retains hemopoietic stem and progenitor cells; trOPN is a chemoattractant [PMID:19417209].","molecular_requirements":"The active form is thrombin-cleaved N-terminal OPN; alpha4 acts as the alpha4beta1 heterodimer [PMID:19417209]. Reactome lists an SPP1:Integrin alpha4beta1 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Murine and human HSCs studied; ligand and receptor species recorded as unspecified [PMID:19417209].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGA4 secretion flag not given in our evidence.","caveats":"One paper, read as abstract; it does not separate alpha4 from alpha9 contributions, and the pair is for a cleaved fragment. Reactome citation is a different paper [DB:Reactome].","key_references":[{"PMID":"19417209","why":"Thrombin-cleaved OPN migration via alpha9beta1 and alpha4beta1"}],"covers":["LR001405","LR004800"]},"LR003331":{"pair":"SPP1 -> ITGA8","headline":"Spp1 is proposed to act on fibroblast-SMC communication through Itga8/Itgb1 in Marfan aneurysm; computational/expression-led, abstract-only.","interaction_type":"functional only","direction_and_effect":"Spp1 might regulate fibroblast and SMC communication primarily through Itga8/Itgb1; Spp1 reduced Acta2 and Tagln in SMCs and increased collagen expression in fibroblasts [PMID:35414038].","molecular_requirements":"Itga8 with Itgb1 is the proposed receptor [PMID:35414038]. Reactome lists an Integrin alpha8beta1:SPP1 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Fbn1C1041G/+ Marfan mice and single-cell data; plasma SPP1 in patients [PMID:35414038].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGA8 is a receptor [flag].","caveats":"Language is 'might regulate'; direct binding is not shown in this paper. The dossier assay detail notes effect direction as antagonist, while the abstract describes suppression of SMC contractile genes; no antagonism of the receptor is shown. Abstract only.","key_references":[{"PMID":"35414038","why":"Spp1-Itga8/Itgb1 proposed in Marfan aortic aneurysm"}],"covers":["LR003331","LR006538"]},"LR001414":{"pair":"SST -> SSTR5","headline":"Somatostatin peptides bind human SSTR5 with high affinity in recombinant membranes; supported by binding assays and a PDB structure, no in vivo data.","interaction_type":"direct binding","direction_and_effect":"Agonist: SST-14 and SST-28 dose-dependently inhibited forskolin-stimulated cAMP, consistent with adenylyl cyclase inhibitory coupling [PMID:7908405]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Binding was reduced by GTP, GTPgammaS, Na+ and pertussis toxin, indicating pertussis-toxin-sensitive G-protein coupling [PMID:7908405]. A PDB structure with both chains is recorded [DB:PDB 8ZBJ], and IntAct lists a FRET interaction [DB:IntAct].","affinity_potency":[{"value":"Ki = 2.24 nM","assay":"radioligand competition, SST-14","system":"COS-7 membranes expressing hSSTR5","cite":"PMID:7908405"},{"value":"Ki = 0.19 nM","assay":"radioligand competition, SST-28","system":"COS-7 membranes expressing hSSTR5","cite":"PMID:7908405"},{"value":"pKi 8.4-9.9","assay":"GtoPdb range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in transfected COS-7 and CCL39 cells [PMID:7908405][PMID:9652348][PMID:9650799]. Mouse entry is projected from human evidence.","localisation_and_range":"SST flagged secreted, SSTR5 transmembrane, implying paracrine or endocrine action [flag].","caveats":"All three shown papers were read as abstracts only. hSSTR5 is SST-28 selective over SST-14 [PMID:7908405]. Sst5 affinity values varied 2-123-fold depending on the radioligand used [PMID:9652348]. Two of the papers used octreotide or an SST-28 analogue as the radioligand rather than SST-14 itself [PMID:9652348][PMID:9650799].","key_references":[{"PMID":"7908405","why":"cloning of hSSTR5 with SST-14/SST-28 Ki values and cAMP inhibition"},{"PMID":"9652348","why":"sst2 and sst5 radioligand pharmacology in CCL39 cells"},{"PMID":"9650799","why":"five-subtype binding profile with SST-28 analogue control"}],"covers":["LR001414","LR004809"]},"LR003340":{"pair":"SVEP1 -> TIE1","headline":"SVEP1 (Polydom) binds TIE1 directly, shown by two 2023 studies with pull-down and solid-phase binding.","interaction_type":"direct binding","direction_and_effect":"Polydom directly binds Tie1 and promotes lymphatic endothelial cell migration in a Tie1-dependent manner via PI3K/Akt; Akt phosphorylation rose but no significant Tie1 phosphorylation was induced [PMID:37338522]. In zebrafish svep1 and tie1 mutants share lymphatic defects and show genetic interaction [PMID:37097004].","molecular_requirements":"Polydom binds Tie1 via CCP20 [PMID:37338522]. Tie2 showed no significant binding to Polydom [PMID:37338522]; in the other study SVEP1 association with TIE2 was seen in co-IP but not in pull-down [PMID:37097004]. The C-terminus of human SVEP1 (aa 2261-3571) was sufficient for TIE1 binding [PMID:37097004].","affinity_potency":[{"value":"43 \u00b1 4 nM","assay":"apparent dissociation constant, solid-phase binding of Tie1 to coated Polydom","system":"recombinant proteins","cite":"PMID:37338522"}],"species_and_systems":"Zebrafish Svep1/Tie1 and human SVEP1/TIE1 in transfected HEK293T cells [PMID:37097004]; Polydom/Tie1 with mouse Polydom-deficient LECs [PMID:37338522]. Mouse pair is projected from human.","localisation_and_range":"SVEP1 flagged secreted [flag]; described as an ECM protein [PMID:37338522].","caveats":"Both papers abstract-level with excerpts. Tie1 is an orphan receptor and signalling output is Akt, not Tie1 phosphorylation. TIE2 binding is inconsistent between assays.","key_references":[{"PMID":"37338522","why":"Polydom binds Tie1 via CCP20, Kd 43 nM, drives LEC migration"},{"PMID":"37097004","why":"svep1-tie1 genetic and binding evidence in zebrafish and human"}],"covers":["LR003340","LR006547"]},"LR001423":{"pair":"TAC4 -> TACR3","headline":"Hemokinin-1 (TAC4) is reported as a full agonist at NK3 (TACR3) in isolated tissue assays; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"In isolated bioassays HEK-1 was a full agonist at tachykinin NK(1), NK(2) and NK(3) receptors [PMID:11786503]; responses in guinea-pig ileum were blocked by SR 142801 [PMID:11786503]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 8.6-9.1","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Guinea-pig ileum bioassay [PMID:11786503]; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"TAC4 flagged secreted [flag].","caveats":"Abstract only; no binding data at NK3 in the abstract. The GtoPdb row cites a different paper [PMID:11226387].","key_references":[{"PMID":"11786503","why":"HEK-1 agonism at NK3 in guinea-pig ileum"}],"covers":["LR001423","LR004818"]},"LR002017":{"pair":"TFF3 -> CXCR4","headline":"Functional and modelling evidence that CXCR4 contributes to TFF3-induced migration; no binding data.","interaction_type":"functional only","direction_and_effect":"TFF3 stimulated cell migration in a conjunctival epithelial cell line, completely suppressed by blocking CXCR4 and/or CXCR7 [PMID:26780310]. Proliferation was unaffected by blocking either receptor, and ERK1/2 activation was independent of CXCR4 [PMID:26780310].","molecular_requirements":"Modelling predicted CXCR4 and CXCR7 dimers as possible TFF3 binding partners [PMID:26780310].","affinity_potency":[],"species_and_systems":"Human ocular surface tissues and a conjunctival epithelial cell line; mouse pair is ortholog-inferred [PMID:26780310].","localisation_and_range":"TFF3 is annotated secreted [flag].","caveats":"Abstract only. Blocking was of CXCR4 and/or CXCR7, so the CXCR4 contribution is not separated. Binding is computational prediction only.","key_references":[{"PMID":"26780310","why":"TFF3 migration blocked by CXCR4/CXCR7 inhibition"}],"covers":["LR002017","LR005345"]},"LR001432":{"pair":"TFPI -> VLDLR","headline":"Binding and blocking experiments indicate VLDL receptor recognizes full-length TFPI and mediates its antiproliferative effect on endothelial cells.","interaction_type":"direct binding","direction_and_effect":"TFPI inhibited proliferation of bFGF-stimulated endothelial cells; this effect was inhibited by receptor-associated protein and anti-VLDL receptor antibodies [PMID:11278667].","molecular_requirements":"Full-length TFPI, but not a truncated form with two Kunitz domains, is recognized; the carboxyl-terminal region is required [PMID:11278667].","affinity_potency":[],"species_and_systems":"Endothelial cells; species not stated in the abstract. Mouse pair is ortholog-inferred [PMID:11278667].","localisation_and_range":"TFPI is annotated secreted [flag]; VLDLR is annotated transmembrane [flag].","caveats":"Abstract only. The paper calls binding 'high affinity' but no value is in our evidence.","key_references":[{"PMID":"11278667","why":"VLDL receptor binds full-length TFPI"}],"covers":["LR001432","LR004827"]},"LR001441":{"pair":"TGFB1 -> ITGB8","headline":"Strong evidence: alphaVbeta8 binds latent TGF-beta1 with high specificity (cryo-EM, binding assays).","interaction_type":"direct binding","direction_and_effect":"alphaVbeta8 binds latent TGF-beta with exquisite specificity and this is essential for activating it [PMID:31955848]. SLC binds alphaVbeta8, followed by MT1-MMP-dependent release of active TGF-beta [PMID:11970960].","molecular_requirements":"Needs the alphaV partner. Leu-218 after the RGD motif in the latency-associated peptide defines high-affinity binding via the beta8 I-like domain [PMID:27033701].","affinity_potency":[],"species_and_systems":"Cryo-EM of ectodomain with intact ligand [PMID:31955848]; human proteins [PMID:27033701]; PDB structures [DB:PDB 6OM2].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Latent complex presented at the cell surface; mature TGF-beta signals within the latent complex without release [PMID:31955848].","caveats":"Ligand is the latent complex. Affinity values are not given in the dossier. One further paper abstract-insufficient; PMID:27033701 read as abstract only.","key_references":[{"PMID":"31955848","why":"Cryo-EM of alphaVbeta8 bound to latent TGF-beta"},{"PMID":"27033701","why":"Leu-218 defines alphaVbeta8 specificity"},{"PMID":"11970960","why":"SLC binds alphaVbeta8, MT1-MMP-dependent activation"}],"covers":["LR001441","LR004836"]},"LR009100":{"pair":"TGFB2 -> ENG","headline":"TGF-beta2 to endoglin: the one verified paper says endoglin cannot bind ligand alone; UniProt asserts binding. Conflicting.","interaction_type":"conflicting","direction_and_effect":"A curator-verified negative reports that endoglin cannot bind ligand on its own and needs the signalling receptors, acting as an auxiliary component [PMID:12015308]. UniProt says endoglin binds TGFB1 and TGFB2 with high affinity [DB:UniProt].","molecular_requirements":"Endoglin associates with TbetaRI and TbetaRII; extracellular region 437-558 contacts TbetaRII [PMID:12015308].","affinity_potency":[],"species_and_systems":"Abstract-only reading; system not detailed in our evidence.","localisation_and_range":"Ligand secreted [flag].","caveats":"Negative result is explicit but taken from the abstract, and concerns TGF-beta1 responses. A TGFBR2-containing complex row may be the better representation.","key_references":[{"PMID":"12015308","why":"Endoglin needs TbetaRI/TbetaRII to bind ligand"}],"covers":["LR009100"]},"LR001450":{"pair":"TGFB3 -> ENG","headline":"TGF-beta3 and endoglin: one paper says endoglin binds TGF-beta3 only with signalling receptors; UniProt says it does not bind TGFB3.","interaction_type":"conflicting","direction_and_effect":"Endoglin binds TGF-beta1 and -beta3 by associating with the TGF-beta type II receptor and cannot bind ligand on its own [PMID:9872992]. UniProt states high affinity for TGFB1 and TGFB2 but not TGFB3 [DB:UniProt]; BioGRID lists ENG-TGFB3 affinity capture-western [DB:BioGRID].","molecular_requirements":"Requires TGF-beta type II receptor coexpression [PMID:9872992].","affinity_potency":[],"species_and_systems":"Human endothelial and leukaemic cells, affinity labelling [PMID:9872992].","localisation_and_range":"Ligand secreted [flag].","caveats":"Abstract-only; conflicts with UniProt text. Endoglin is an accessory protein, not a standalone receptor.","key_references":[{"PMID":"9872992","why":"Endoglin binds TGF-beta1/-beta3 via type II receptor"}],"covers":["LR001450","LR004845"]},"LR011008":{"pair":"THBS4 -> ITGA3:ITGB1","headline":"No curated paper; only IntAct co-immunoprecipitation records, which do not resolve ITGA3.","interaction_type":"database-asserted only","direction_and_effect":"IntAct records physical association by anti-bait co-immunoprecipitation from PMID 32567740 [DB:IntAct]. Direction not reported in our evidence.","molecular_requirements":"Complex of ITGA3 and ITGB1; the IntAct examples shown name P35443 and P05556 and do not mention ITGA3 [DB:IntAct].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"THBS4 flagged secreted [flag].","caveats":"Three papers are pending curation; support is database-only and unverified for ITGA3.","key_references":[],"covers":["LR011008"]},"LR003403":{"pair":"TIMP2 -> MMP14","headline":"TIMP-2 binding to MT1-MMP is asserted by multiple databases; no curated paper confirmed it here.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists reconstituted-complex, affinity-capture and co-localisation records for TIMP2-MMP14 [DB:BioGRID]; IntAct lists co-IP records [DB:IntAct]; Reactome describes MMP14 (MT1-MMP) binding TIMP2 and a plasma-membrane MMP14:TIMP2 complex [DB:Reactome].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"Reactome places the MMP14:TIMP2 complex at the plasma membrane [DB:Reactome]; MMP14 is flagged non-secreted [flag].","caveats":"No paper passed curation (two abstract_insufficient). Support is database records only, and the dossier gives no signalling or effect direction.","key_references":[],"covers":["LR003403","LR006604"]},"LR003412":{"pair":"TNC -> TLR4","headline":"Tenascin-C binds the TLR4 ectodomain directly and activates TLR4 signalling, shown with human proteins and cells.","interaction_type":"direct binding","direction_and_effect":"Tenascin-C acts as an agonist of TLR4 and drives NF-kB activation and inflammatory cytokine synthesis [PMID:29150600]. Activity was blocked by a neutralizing TLR4 antibody or the antagonist TAK 242 [PMID:29150600]. Three sites in tenascin-C are reported to interact directly and cooperatively with TLR4 [PMID:29150600].","molecular_requirements":"The fibrinogen-like globe (FBG) domain of tenascin-C was sufficient to bind the TLR4 extracellular domain and activate cells; positively charged residues in loop 5 were needed for activation [PMID:29150600]. Co-receptors (MD-2, CD14) are not reported in our evidence.","affinity_potency":[{"value":"KD ~50-60 nM","assay":"solid phase binding of FBG domains (FBG-C, -R, -W) to TLR4 extracellular domain","system":"recombinant proteins","cite":"PMID:29150600"}],"species_and_systems":"Human proteins; THP1 NF-kB reporter cells and primary human macrophages [PMID:29150600]. An IntAct ELISA record supports the pair [DB:IntAct].","localisation_and_range":"Tenascin-C is flagged secreted, a matrix protein induced upon tissue damage [flag][PMID:29150600].","caveats":"The KD range is quoted for FBG domains of tenascin-C, -R and -W together, not tenascin-C alone. Endotoxin contamination was excluded by LPS quantification and polymyxin B treatment [PMID:29150600]. Curators read the abstract only for the row, but excerpts come from the full text.","key_references":[{"PMID":"29150600","why":"Maps tenascin-C binding sites and TLR4 activation"}],"covers":["LR003412","LR006613"]},"LR001513":{"pair":"TNF -> TNFRSF1A","headline":"TNF binds TNFR1 directly, with structural, affinity and signalling-complex evidence from human and mouse systems.","interaction_type":"direct binding","direction_and_effect":"TNF acts as an agonist at TNFR1 [PMID:33495441][PMID:7852363]. After TNF stimulation TNFR1 forms a membrane complex I (TNFR1, TRADD, RIP1, TRAF2) that signals NF-kB activation, and a later cytoplasmic complex II with FADD and caspase-8 can induce apoptosis [PMID:12887920].","molecular_requirements":"TNF is a trimer; in the absence of compound it binds three TNFR1 molecules, while a small-molecule-distorted trimer binds a dimer of TNFR1 [PMID:33495441]. In deletion mapping, domain 3 but not domain 4 of TNFR-1 binds ligand directly [PMID:7852363].","affinity_potency":[{"value":"KD ~290 nM","assay":"binding affinity comparison of TNF-alpha with the mutein TNF-SAM2 (abstract gives 2. 9x1-7 M)","system":"human proteins, Colo205 cells","cite":"PMID:17195449"}],"species_and_systems":"Human TNF and TNFR1 in structural, SPR and mass-spectrometry work [PMID:33495441] and deletion mapping [PMID:7852363]. The complex I/II study used mouse proteins per the curator [PMID:12887920]. A mouse pair was projected from human evidence.","localisation_and_range":"TNF is flagged secreted and transmembrane, so both soluble and membrane forms are possible [flag].","caveats":"The KD comes from an abstract with garbled exponent; the curator reads it as ~290 nM, so check it against the paper [PMID:17195449]. Several papers were read as abstract only. One confirming paper (PMID:19084540) mainly concerns receptor-selective TNF mutants and gives no constant for wild-type TNF [PMID:19084540].","key_references":[{"PMID":"33495441","why":"Crystal structure and affinity of TNF-TNFR1 complex"},{"PMID":"12887920","why":"TNFR1 signalling complexes I and II"},{"PMID":"7852363","why":"Domain mapping of TNF binding to TNFR1"}],"covers":["LR001513","LR004903"]},"LR001504":{"pair":"TNFSF13 -> TNFRSF17","headline":"APRIL binds BCMA with high affinity; well supported by several binding papers plus an AML functional study.","interaction_type":"direct binding","direction_and_effect":"APRIL binds BCMA and TACI and competes with TALL-I for receptor binding; soluble BCMA and TACI block APRIL-stimulated B-cell proliferation [PMID:10973284]. In AML cells, TNFSF13 drove NF-kappaB-dependent proliferation, and a TNFRSF17 blocking antibody hindered proliferation and NF-kappaB activation in human Mono-Mac-6 cells [PMID:30819903].","molecular_requirements":"BCMA binds APRIL via the canonical TNF fold, while HSPG binds a separate lysine motif; the two bind simultaneously [PMID:15846369]. HSPG binding is reported to help TNFSF13 oligomerise and bind TNFRSF13B or TNFRSF17 [PMID:30819903].","affinity_potency":[{"value":"IC50 = 11 +/- 3 nm","assay":"binding of monomeric BCMA to APRIL","system":"human proteins","cite":"PMID:14764606"}],"species_and_systems":"Human proteins for binding [PMID:14764606][PMID:10973284]; murine MLL-AF9 leukemia cells and mouse knockouts plus human myeloid lines in the AML study [PMID:30819903]; BCMA-Fc blocked antibody production in mice [PMID:10973284].","localisation_and_range":"APRIL flagged secreted, BCMA transmembrane [flag].","caveats":"Binding papers are abstract-only; AML paper has full text. Neither BCMA nor TACI is essential for APRIL's tumor-promoting effects [PMID:15846369]. APRIL is the preferred ligand versus BAFF (BAFF IC50 = 8 +/- 5 microm) [PMID:14764606].","key_references":[{"PMID":"14764606","why":"APRIL-BCMA affinity and specificity residues"},{"PMID":"10973284","why":"APRIL binds BCMA/TACI, competes with TALL-I"},{"PMID":"30819903","why":"Functional BCMA-dependent signalling in AML"}],"covers":["LR001504","LR004894"]},"LR002026":{"pair":"TOR2A -> ATP5F1B","headline":"Salusin-beta (TOR2A) was reported to bind ATP synthase beta chain using native-membrane proteoliposomes; single paper.","interaction_type":"direct binding","direction_and_effect":"ATP synthase beta chain is identified as a cell surface receptor for salusin-beta; salusin-beta inhibited cell surface ATP synthase activity and prevented sarcoma cell-induced angiogenesis in an in vivo mouse air sac model, acting as an angiogenesis inhibitor [PMID:30552345].","molecular_requirements":"Beta chain of ATP synthase; the alpha chain is the angiostatin target in other work, and its role here not reported in our evidence.","affinity_potency":[],"species_and_systems":"Liposomes with endogenous membrane proteins from animal tissues; mouse air sac model [PMID:30552345]. Both pairs are ortholog-inferred.","localisation_and_range":"Described as a cell surface receptor [PMID:30552345]. ATP5F1B carries no transmembrane or secretion flag here; the ligand is flagged secreted [flag].","caveats":"Single paper, abstract-level evidence in the dossier. Detergent-based techniques identified a beta-actin-profilin complex instead and failed to identify this receptor [PMID:30552345]. An ATP synthase subunit is normally mitochondrial, so surface function rests on this report.","key_references":[{"PMID":"30552345","why":"Proteoliposome identification of ATP synthase beta chain as salusin-beta receptor"}],"covers":["LR002026","LR005354"]},"LR003421":{"pair":"TRIM21 -> CLEC1A","headline":"TRIM21 was identified as an endogenous CLEC-1 ligand by pulldown, co-IP, Biacore and ELISA; CLEC-1 acts as a myeloid checkpoint.","interaction_type":"direct binding","direction_and_effect":"Antagonism of CLEC-1 function is the therapeutic angle: CLEC-1 blockade with chemotherapy prolonged mouse survival, and antihuman CLEC-1 antagonist antibodies enhanced antitumor immunity in CLEC-1 humanized mice [PMID:36399563]. Whether TRIM21 itself activates or inhibits CLEC-1 signalling is not reported in our evidence; CLEC-1 loss increased cross-presentation by cDC1 [PMID:36399563].","molecular_requirements":"Fc-CLEC-1 and His-CLEC-1 both bound TRIM21; direct interaction of recombinant human TRIM21 with human CLEC-1 was validated by Biacore and ELISA [PMID:36399563].","affinity_potency":[],"species_and_systems":"Human recombinant proteins, UV-treated necrotic human cell lines (Raji, Hpb-all), mouse tumour models and CLEC-1 humanized mice [PMID:36399563].","localisation_and_range":"TRIM21 is released by necrotic cells and is flagged secreted [flag]; it is also a cytosolic protein, so its extracellular role is damage-associated [PMID:36399563].","caveats":"TRIM21 is an intracellular protein; the Fc part was controlled for by using His-CLEC-1. A purified-protein affinity value is not given in the excerpts. Mouse ortholog pair is inferred.","key_references":[{"PMID":"36399563","why":"TRIM21 identified and validated as a CLEC-1 ligand; CLEC-1 checkpoint"}],"covers":["LR003421","LR006622"]},"LR001522":{"pair":"UCN -> CRHR1","headline":"Urocortin 1 binds CRF1 receptor with sub-nanomolar affinity in several radioligand and binding studies; abstract-level evidence, strong and consistent.","interaction_type":"direct binding","direction_and_effect":"Urocortin acts as an agonist: synthetic human urocortin binds CRF receptor types 1, 2 alpha and 2 beta and stimulates cAMP accumulation in transfected cells [PMID:8612563]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor or subunit requirement is reported in our evidence. Binding was to the single CRF1 receptor expressed recombinantly [PMID:9423932]. The CRF-binding protein also binds human urocortin and can prevent its ACTH-releasing effect in vitro [PMID:8612563].","affinity_potency":[{"value":"Kd 0.18-0.31 nM","assay":"[3H]-rat urocortin saturation binding, reported across human CRF1, rat CRF2alpha and rat CRF2beta receptors and rat cerebellum","system":"stably transfected cell homogenates","cite":"PMID:9423932"},{"value":"pKd 8.3 to 9.8","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:11123370"}],"species_and_systems":"Binding experiments used human CRF1 in transfected cells with rat urocortin as the radioligand [PMID:9423932]; human and Xenopus receptors were compared with human and rat urocortin [PMID:11123370]; human urocortin was tested on rat pituitary cells [PMID:8612563]. The dossier covers human and mouse pairs; the mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and receptor flagged as transmembrane receptor [flag], suggesting a secreted peptide acting on a cell-surface GPCR.","caveats":"All four cited papers were read as abstracts only (one browser-read Results sentence is unverified [PMID:11416224]). Urocortin binds CRF1 with affinity similar to other CRF-family peptides in one study [PMID:9423932], so it is not selective for CRF1.","key_references":[{"PMID":"8612563","why":"Human urocortin binds CRF receptors and stimulates cAMP"},{"PMID":"9423932","why":"[3H]-urocortin Kd on recombinant CRF1"},{"PMID":"11123370","why":"Urocortin high-affinity binding with agonist or antagonist radioligands"}],"covers":["LR001522","LR004912"]},"LR003430":{"pair":"UNC5A -> FLRT2","headline":"Extracellular binding of UNC5A and FLRT2 shown in a mouse-protein screen; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5A is annotated as a transmembrane receptor and FLRT2 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. Unc5A stripes gave no attractive or repulsive neuronal response (n=257/257, 100% permissive) [PMID:26633812]. UniProt records the interaction [DB:UniProt].","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003430","LR006631"]},"LR001531":{"pair":"VCAM1 -> ITGB2","headline":"Evidence is for the alphaDbeta2 heterodimer binding VCAM-1; ITGB2 is the shared chain, abstract only.","interaction_type":"direct binding","direction_and_effect":"Recombinant soluble alphaDbeta2 and the alphaD I-domain bind VCAM-1; mutation of VCAM-1 D40 abrogates binding [PMID:10438935].","molecular_requirements":"beta2 pairs with alphaD for VCAM-1; LFA-1 and Mac-1 are noted in the abstract as binding ICAM-1, not VCAM-1, so ITGB2 alone does not imply binding [PMID:10438935].","affinity_potency":[],"species_and_systems":"Human transfectants and recombinant proteins [PMID:10438935]. Mouse pair is ortholog-inferred.","localisation_and_range":"VCAM1 flagged secreted and transmembrane [flag].","caveats":"Chain-only entry; one abstract-level paper. UniProt lists ITGAD:ITGB2 as VCAM1 receptor [DB:UniProt].","key_references":[{"PMID":"10438935","why":"alphaDbeta2 binds VCAM-1"}],"covers":["LR001531","LR004920"]},"LR001540":{"pair":"VEGFA -> ITGB1","headline":"VEGF-A binds integrin alpha9beta1, so ITGB1 is supported only as the beta chain of that heterodimer.","interaction_type":"direct binding","direction_and_effect":"VEGF-A is described as a direct ligand for alpha9beta1; adhesion and migration of human endothelial cells are dependent on it, and a blocking antibody inhibited angiogenesis [PMID:17363377].","molecular_requirements":"The receptor is the alpha9beta1 heterodimer, so ITGB1 alone is chain-only evidence and needs ITGA9. VEGFR-2 cooperates [PMID:17363377].","affinity_potency":[],"species_and_systems":"Human endothelial cells [PMID:17363377].","localisation_and_range":"Not reported in our evidence.","caveats":"One paper, abstract only, and it does not test ITGB1 independently of alpha9. Other beta1 integrin pairings are not covered.","key_references":[{"PMID":"17363377","why":"VEGF-A direct ligand for alpha9beta1"}],"covers":["LR001540","LR004929"]},"LR004132":{"pair":"VEGFD -> FLT4","headline":"VEGF-D is a dual VEGFR-2/VEGFR-3 ligand needing proteolytic processing; two abstract-level papers plus database records.","interaction_type":"direct binding","direction_and_effect":"VEGF-D is a ligand for both VEGFR-2 and VEGFR-3 and can activate these receptors [PMID:9435229]. Residues between the reported proteolytic cleavage sites are important for VEGF-D binding and activation of VEGFR-3, but not of VEGFR-2 [PMID:21148085].","molecular_requirements":"VEGF-D is produced as a precursor with propeptides; proteolytic removal enhances VEGFR-2/VEGFR-3 binding [PMID:21148085]. It does not bind VEGFR-1 [PMID:9435229].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, recombinant binding and functional assays; abstract-level reading [PMID:21148085] [PMID:9435229]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Affinity not reported in our evidence. BioGRID reconstituted-complex records [DB:BioGRID] and Reactome binding reaction [DB:Reactome]. Two review-only rows and one pending are not shown.","key_references":[{"PMID":"9435229","why":"VEGF-D identified as VEGFR-2/VEGFR-3 ligand"},{"PMID":"21148085","why":"structure and processing requirements of VEGF-D"}],"covers":["LR000648","LR004132"]},"LR011242":{"pair":"WNT10A -> FZD4:LRP5","headline":"Database-asserted only: an IntAct co-IP record, with no confirmed paper for WNT10A with FZD4:LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. IntAct EBI-54877040 records an association by anti-tag coimmunoprecipitation [DB:IntAct]; the record is not specific to this complex.","molecular_requirements":"Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the IntAct record are not reported in our evidence.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Judged papers: pending 3.","key_references":[],"covers":["LR011242"]},"LR002035":{"pair":"WNT10A -> FZD5","headline":"WNT10A signals through FZD5 in a human reporter-cell knockout panel; functional, not binding.","interaction_type":"functional only","direction_and_effect":"Wnt10a, with Wnt1, Wnt8a, Wnt7b and Wnt8b, induced signalling via FZD5 and FZD8 in an FZD knockout panel [PMID:28733458].","molecular_requirements":"FZD8 was also responsive; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 reporter cells, full text [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Functional inference only; binding is not shown.","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR002035","LR005361"]},"LR011332":{"pair":"WNT11 -> FZD1","headline":"WNT11 to FZD1 rests only on Reactome records; no paper was judged as confirming the pair.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a generic WNT:FZD complex at the plasma membrane [DB:Reactome]; the pair is annotated stimulatory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Four papers were judged abstract_insufficient, so no verified experiment supports this pair. The Reactome complex is a generic WNT:FZD entry, not specific to WNT11 and FZD1 [DB:Reactome].","key_references":[],"covers":["LR011332"]},"LR011260":{"pair":"WNT2 -> FZD2:LRP5","headline":"WNT2 to FZD2:LRP5 is inferred from a FZD2-only paper; LRP5 was not tested.","interaction_type":"functional only","direction_and_effect":"WNT2 stabilised and phosphorylated FZD2 and activated STAT3 in ESCC cells [PMID:32766155].","molecular_requirements":"LRP5 contribution is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ESCC cells [PMID:32766155].","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"One review-only and two abstract_insufficient rows. Support is for FZD2 alone.","key_references":[{"PMID":"32766155","why":"WNT2/FZD2/STAT3 in ESCC (FZD2 only)"}],"covers":["LR011260"]},"LR002044":{"pair":"WNT3A -> FZD10","headline":"FZD10 interacts with WNT3A by proximity ligation and mediates WNT3A signalling when LRP6 is present.","interaction_type":"direct binding","direction_and_effect":"In the presence of LRP6, FZD10 promoted WNT3A signalling in an 8xSuperTopFlash assay [PMID:24599775]. Without LRP6, FZD10 co-expression inhibited WNT3A signalling [PMID:24599775]. A CRISPR rescue map reports Wnt3/Wnt3a signalling via all FZDs [PMID:28733458].","molecular_requirements":"LRP6 co-expression was needed to turn FZD10 into a signal-promoting receptor; PLA signal for WNT3A-FZD10 occurred with or without exogenous LRP6, with slightly fewer punctae without it [PMID:24599775].","affinity_potency":[],"species_and_systems":"In situ proximity ligation in transfected COS7 cells, reporter assay in HEK293T cells and chick embryo spinal cord expression [PMID:24599775]; HEK293T FZD1/2/7 mutant rescue [PMID:28733458]. Curators label the constructs human.","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Proximity ligation shows closeness within 40 nm, not direct binding or affinity. Overexpressed FZD10 alone suppressed signalling. The second paper's sentence is generic across FZDs [PMID:28733458]. Mouse interaction is ortholog-inferred.","key_references":[{"PMID":"24599775","why":"PLA interaction and LRP6-dependent WNT3A signalling via FZD10"},{"PMID":"28733458","why":"functional FZD-Wnt rescue map"}],"covers":["LR002044","LR005370"]},"LR008101":{"pair":"WNT3A -> FZD8:LRP6","headline":"No curated paper for this complex; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence beyond database records.","molecular_requirements":"UniProt says LRP6 interacts via beta-propeller regions 3 and 4 with WNT3A [DB:UniProt]; FZD8 enters via an IntAct pull-down [DB:IntAct].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence for this complex.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Records include BioGRID [DB:BioGRID], IntAct [DB:IntAct] and Reactome complexes with FZD unspecified [DB:Reactome]. Papers were review_only. A separate paper in G04918 reconstituted Fz8 CRD.Wnt3a.LRP6 in vitro, but it is not attached to this dossier.","key_references":[],"covers":["LR008101"]},"LR003502":{"pair":"WNT4 -> LRP5","headline":"One co-IP result in mouse cells shows a Wnt4-LRP5 complex; other papers were abstract-insufficient.","interaction_type":"direct binding","direction_and_effect":"Co-IP revealed a Wnt4-LRP5 binding complex [PMID:31216173].","molecular_requirements":"Wnt4-Fzd1/Fzd2/Fzd6 complexes and LRP-Fzd complexes were also found, so a Frizzled may bridge the interaction [PMID:31216173].","affinity_potency":[],"species_and_systems":"Co-IP in MC3T3 (mouse) cells, per curator note [PMID:31216173]. Human pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and LRP5 flagged transmembrane [flag].","caveats":"Single browser-read result, not spot-checked; co-IP does not show direct binding. No affinity in our evidence.","key_references":[{"PMID":"31216173","why":"co-IP of Wnt4 with LRP in MC3T3 cells"}],"covers":["LR003502","LR006702"]},"LR001603":{"pair":"WNT5A -> FZD4","headline":"Wnt5a is supported for FZD4 by binding, structural-BRET and signalling studies; Wnt5a stimulates FZD4 CRD dimerization and dissociates FZD4-G12/13.","interaction_type":"direct binding","direction_and_effect":"WNT5A stimulated dimerization of membrane-anchored FZD4 CRDs and oligomerization of full-length FZD4 in BRET [PMID:28546512]. The FZD4-G protein complex dissociated on WNT-5A stimulation [PMID:27458145]. Xfz4 interacts with Xwnt5A to activate the beta-catenin pathway in Xenopus [PMID:10990458].","molecular_requirements":"Oligomerization required the integrity of the CRD palmitoleoyl-binding residues [PMID:28546512]. FZD4 assembles with Ga12/13 specifically, independent of DVL [PMID:27458145]. LRP involvement is not reported for this pair, see the FZD4:LRP5 dossier.","affinity_potency":[{"value":"KD = 22\u201326 nm","assay":"Bio-layer interferometry, WNT-5A binding to FZD CRD-Fc, reported jointly for the FZD1/2/4 CRDs","system":"mouse proteins, in vitro","cite":"PMID:25605717"}],"species_and_systems":"Human FZD4 BRET and G-protein work in cells [PMID:28546512][PMID:27458145]; mouse proteins for BLI [PMID:25605717]; Xenopus for the pathway study [PMID:10990458].","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Most papers were read as abstracts only. Recombinant WNT5A protein did not significantly increase full-length FZD4 interactions, whereas transfected WNT5A DNA did [PMID:28546512]. The affinity quote is from a browser read, spot-check pending [PMID:25605717].","key_references":[{"PMID":"25605717","why":"BLI binding of WNT-5A to FZD CRDs"},{"PMID":"28546512","why":"WNT5A stimulates FZD4 CRD dimerization and oligomerization"},{"PMID":"27458145","why":"WNT-5A dissociates FZD4-G12/13 complex"}],"covers":["LR001603","LR004992"]},"LR001612":{"pair":"WNT5A -> RYK","headline":"RYK mediates WNT5A effects in several functional studies; one study measured weak binding and found RYK is not a co-receptor of FZD5.","interaction_type":"functional only","direction_and_effect":"RYK knockdown reversed WNT5A-induced apoptosis in prostate cancer cells [PMID:29930766]; WNT5A signalling in rheumatoid synoviocytes required RYK, via WNT/Ca2+ [PMID:33178184]; Wnt5a acts as a chemorepulsive ligand for Ryk in mouse callosal axons [PMID:16723543]. Curated stimulatory.","molecular_requirements":"RYK acted as a single receptor; sequential binding showed RYK does not act as a co-receptor for FZD5 and WNT5A binds FZD5 or RYK at the same site [PMID:29930766].","affinity_potency":[],"species_and_systems":"Human PC3 cells and rheumatoid synoviocytes; Ryk-deficient mice for axon guidance [PMID:16723543].","localisation_and_range":"Membrane receptor; Reactome lists WNT5A:RYK:VANGL2 [DB:Reactome R-HSA-4551548].","caveats":"Binding in the surface assay needed high concentrations, and WNT5A binding to FZD5 was 31% higher than to RYK [PMID:29930766]. Effect direction is mixed: agonist in cells, antagonist label for axon guidance; two papers are abstract-only.","key_references":[{"PMID":"29930766","why":"RYK knockdown and binding data in prostate cancer cells"},{"PMID":"33178184","why":"RYK required for WNT5A in synoviocytes"},{"PMID":"16723543","why":"Ryk and Wnt5a axon guidance in mouse"}],"covers":["LR001612","LR005001"]},"LR003511":{"pair":"WNT5A -> VANGL2","headline":"Wnt5a induces a Ror2-VANGL2 complex and VANGL2 phosphorylation in mouse; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Agonist: Wnt ligands including Wnt5a strongly induced Ror2-Vangl2 complex formation and dose-dependent Vangl2 phosphorylation [PMID:21316585]. Reactome lists a WNT5A:ROR2:VANGL2 plasma-membrane complex [DB:Reactome R-HSA-4551543].","molecular_requirements":"VANGL2 acts together with ROR2; Ror2 and Vangl2 double knockouts resemble Wnt5a knockouts [PMID:21316585]. VANGL2 alone as a binder is not shown.","affinity_potency":[],"species_and_systems":"Mouse embryos, limb bud, mouse embryonic fibroblasts [PMID:21316585]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Direct Wnt5a-Vangl2 binding is not shown; VANGL2 works as part of a Wnt5a-ROR2 complex [PMID:21316585]. Curated from the abstract; excerpts available. Ror family members mediate only part of Wnt5a signalling in vivo [PMID:21316585].","key_references":[{"PMID":"21316585","why":"Wnt-induced Ror2-Vangl2 complex and Vangl2 phosphorylation"}],"covers":["LR003511","LR006711"]},"LR003520":{"pair":"WNT7A -> FZD4","headline":"Weak: WNT7A bound FZD4 only at trace level in one paper; a second shows functional G-protein dissociation.","interaction_type":"conflicting","direction_and_effect":"In a full-text paper, full-length cell-surface FZD4 and recombinant sFZD4-Fc did not detectably bind WNT7A and only trace binding was seen with sFZD4-His; STF activity with Lrp5 was modestly increased by Fzd4, suggesting low-affinity binding [PMID:30304675]. WNT-7A stimulation dissociated a FZD4-Galpha12/13 complex, an agonist effect [PMID:27458145].","molecular_requirements":"FZD4 co-expressed with Galpha12/13 for the G-protein readout; FZD8 bound WNT7A far better in the first paper [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human proteins; HEK293 cells in both papers [PMID:30304675][PMID:27458145]; the mouse pair is projected from human evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; signalling at the cell surface.","caveats":"The binding paper is largely negative for FZD4. The second paper is abstract only and functional.","key_references":[{"PMID":"27458145","why":"WNT-7A dissociates FZD4-Galpha12/13 complex"},{"PMID":"30304675","why":"FZD4 binds WNT7A only weakly"}],"covers":["LR003520","LR006720"]},"LR005005":{"pair":"WNT7A -> LRP6","headline":"WNT7A binds LRP6 ECD and is blocked by anti-LRP6 antibodies; binding plus functional support.","interaction_type":"direct binding","direction_and_effect":"Recombinant LRP6 ECD bound WNT7A [PMID:30304675]. Anti-LRP6 Wnt1-class Fabs inhibited Wnt7a signalling in a SuperTopFlash reporter [PMID:20713706]. In rat PC12 cells WNT7A acted via a Frizzled-5.LRP6 complex and was antagonised by Dickkopf-1 and -3 [PMID:12857724].","molecular_requirements":"Evidence of PMID:12857724 is for the Frizzled-5/LRP6 complex rather than LRP6 alone. Wnt1-class Fabs bind the first propeller of LRP6 [PMID:20713706].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 [PMID:30304675, PMID:20713706]; human WNT7A on rat PC12 cells [PMID:12857724]. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. Receptor is flagged transmembrane [flag].","caveats":"Two of three papers are abstract-only; the PNAS evidence is antibody inhibition, not binding. No affinity reported. Active WNT7A is short-lived in medium [PMID:30304675].","key_references":[{"PMID":"30304675","why":"LRP6 ECD binds WNT7A (full text)"},{"PMID":"20713706","why":"Anti-LRP6 Fabs block Wnt7a signalling"},{"PMID":"12857724","why":"WNT7A via Frizzled-5/LRP6, DKK antagonism"}],"covers":["LR001616","LR005005"]},"LR001621":{"pair":"XCL2 -> XCR1","headline":"Well supported functional agonist pair: XCL2 activates XCR1 with potency matching XCL1 in human recombinant systems.","interaction_type":"functional only","direction_and_effect":"XCL2 (SCM-1beta) induced chemotaxis and calcium mobilisation in XCR1 (GPR5)-expressing L1.2 cells, with efficient mutual cross-desensitisation with SCM-1alpha, indicating a shared receptor [PMID:9632725]. The monomeric form of XCL2 activates XCR1 [PMID:25497737]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Monomer is the active form; locked-monomer CC3 constructs were more potent than wild type, while the preferential dimer W55D showed no measurable Ca2+ flux [PMID:25497737]. Reactome describes an XCR1:XCL1,XCL2 complex [DB:Reactome].","affinity_potency":[{"value":"EC50 ~ 15 nM","assay":"Ca2+ flux, monomeric CC3 form","system":"XCR1-transfected HEK 293 cells","cite":"PMID:25497737"},{"value":"EC50 ~ 50 nM","assay":"Ca2+ flux, wild-type XCL2","system":"XCR1-transfected HEK 293 cells","cite":"PMID:25497737"},{"value":"pEC50 7.3","assay":"curator-recorded activation by monomeric XCL2","system":"human","cite":"PMID:25497737"}],"species_and_systems":"Human ligand and receptor, recombinant, in L1.2 cells [PMID:9632725] and HEK 293 cells [PMID:25497737]. Mouse and rat genomes show no second XCL gene [PMID:25497737].","localisation_and_range":"XCL2 is flagged secreted and XCR1 transmembrane [flag]; paracrine chemokine signalling is implied. The XCL2 dimer binds heparin [PMID:25497737].","caveats":"No direct binding constant for XCL2 is reported in our evidence; binding to XCR1 is inferred from functional activation and cross-desensitisation. Abstract-only reading for PMID:9632725. XCL2 is absent from rodents [PMID:25497737], so no mouse evidence applies.","key_references":[{"PMID":"9632725","why":"XCL2 (SCM-1beta) activates XCR1; shared receptor"},{"PMID":"25497737","why":"XCL2 monomer activates XCR1; EC50 values"}],"covers":["LR001621"]},"LR002062":{"pair":"ZP3 -> CHRNA7","headline":"One abstract-read paper reports ZP3 binding to alpha7 nAChR in a mouse sperm system; human pair is inferred from mouse.","interaction_type":"direct binding","direction_and_effect":"A microfluidic affinity in vitro assay showed alpha7 nAChR interacted with ZP3; isolated zona pellucida or alpha7 agonists induced the acrosome reaction in wild-type but not alpha7-null sperm, suggesting ZP activates alpha7 (agonist) [PMID:22577141].","molecular_requirements":"Activation of alpha7 was proposed to lead to SFK-dependent EGFR activation, Ca2+ influx and the acrosome reaction, so EGFR acts downstream [PMID:22577141].","affinity_potency":[],"species_and_systems":"Mouse sperm (wild type and Chrna7-knockout) and egg zona pellucida [PMID:22577141]. The human pair is ortholog-inferred, not tested.","localisation_and_range":"ZP3 is flagged secreted [flag]; in the paper it is a component of the egg zona pellucida matrix that contacts sperm, so signalling is contact-dependent [PMID:22577141].","caveats":"Abstract only; the identity of the sperm ZP receptor is described as uncertain [PMID:22577141]. No affinity reported. Human evidence is projected from mouse.","key_references":[{"PMID":"22577141","why":"Microfluidic assay: ZP3 interacts with alpha7 nAChR; Chrna7-null sperm"}],"covers":["LR002062","LR005388"]},"LR000046":{"pair":"AGT -> AGTR2","headline":"Angiotensin-derived peptide (Ang A / Ang II) binds and activates AT2 (AGTR2); well supported by binding and functional papers, mostly abstract-read.","interaction_type":"direct binding","direction_and_effect":"Agonist at AT2. Ang A has higher affinity for AT2 than Ang II [PMID:17138938], while a later study reports similar affinity for AT1 and AT2 and no AT2 contribution to pressor or renal responses in vivo [PMID:21464395]. In mouse AgRP neurons, Ang-II stimulation was blocked by the AT2R antagonist PD-123319 [PMID:37540598]. In human proximal tubular cells, Ang II/AT2R engagement was linked to apoptosis [PMID:15930094].","molecular_requirements":"Single receptor chain (AGTR2). The ligand is the processed octapeptide (Ang A or Ang II), not full-length AGT; the entity is named angiotensin A [PMID:17138938].","affinity_potency":[],"species_and_systems":"Human recombinant and tissue systems (HEK-293 cells, COS-7 cells) [PMID:21542804][PMID:8185599]; rat kidney and rat/mouse in vivo [PMID:17138938][PMID:21464395]; mouse AgRP neuron recordings [PMID:37540598]. The dossier covers human and mouse pairs, neither ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor flagged transmembrane [flag]; plasma presence of Ang A is reported [PMID:17138938].","caveats":"Most papers were read as abstracts only. Several describe Ang II or Ang A, not AGT itself. Binding at AT2 was functionally silent in one in vivo study [PMID:21464395]. A numeric affinity is not reported in a quotable form in our evidence.","key_references":[{"PMID":"21542804","why":"Systematic peptide binding at AT1R/AT2R in HEK-293 cells"},{"PMID":"17138938","why":"Ang A has higher AT2 affinity than Ang II"},{"PMID":"8185599","why":"Human AT2 cloning with specific angiotensin analog binding in COS-7 cells"}],"covers":["LR000046","LR003596"]},"LR004312":{"pair":"IL1B -> IL1R2","headline":"IL1R2 binds IL-1 beta directly and acts as an inhibitory decoy; supported by radioligand binding and structure.","interaction_type":"direct binding","direction_and_effect":"Inhibitory decoy. Soluble type II IL-1 receptor is a specific inhibitor of IL-1 beta, and binding the precursor blocked its processing to the mature 17-kDa form [PMID:7878046].","molecular_requirements":"Single chain. Soluble and cell-surface receptor bound the same regions of IL-1 beta. The cell-surface form did not bind the IL-1 beta precursor, but the released soluble form did [PMID:7878046]. A PDB complex exists [DB:PDB 3O4O].","affinity_potency":[],"species_and_systems":"Human Raji B cell line, competition binding [PMID:7878046]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL1B is annotated secreted [flag]. IL1R2 occurs as a membrane form and a released soluble form, which extends its range [PMID:7878046].","caveats":"Single paper, read as abstract only; no affinity value stated in our evidence. Affinity for IL-1ra dropped by a factor of 2000 for the soluble form [PMID:7878046]. Reactome lists a complex with IL1B [DB:Reactome].","key_references":[{"PMID":"7878046","why":"Competition binding and blocking of IL-1 beta precursor processing by IL1R2."}],"covers":["LR000882","LR004312"]},"LR008200":{"pair":"CSPG4 -> ITGA3:ITGB1","headline":"Database-asserted only: UniProt says integrin alpha-3/beta-1 is a receptor for CSPG4; the one paper checked did not support the ITGA3 complex.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records state integrin alpha-3/beta-1 is a receptor for CSPG4 [DB:UniProt]. Agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"The UniProt SUBUNIT entry for Q6UVK1 describes interaction with the integrin composed of ITGB1 and ITGA3 [DB:UniProt]. Whether one chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entries; no experimental system is described in our evidence.","localisation_and_range":"Annotation flags mark CSPG4 as secreted, transmembrane and a receptor, and the integrin chains as receptors [flag]. Mode of action is not reported in our evidence.","caveats":"No curator-confirmed paper. A 2026 single-cell study of acral melanoma fibroblasts, read as abstract only, names the CSPG4 pathway with ITGA2+ITGB1, not ITGA3, so it gives no support to this ITGA3 complex [PMID:42206704]. Support rests on database text.","key_references":[],"covers":["LR008200"]}};